/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230724-8","meetingId":"r05-cm07","date":"2023年7月24日","dateIso":"2023-07-24","committee":"建設委員会","time":"午後 １時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"品川区自転車活用推進計画策定に向けた検討状況","agenda":"品川区自転車活用推進計画策定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この第３回協議会が行われたということで、協議会での意見や質疑など、どのような話があったのかというところを伺いたいと思います。整備はされているけれども位置づけられていない、ネットワークの中に入っていないというものがほかにもあるのかどうか、そこを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"第３回協議会でいただいたご意見・ご質問等ですが、エリア別で課題や方針を示しておりますが、どのようなことをイメージして記載されているのか。今資料２のほうには、基本的に整備が終わっているところは全てネットワークのほうに入れ込んでいるというような状況です。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたものを見ていますと、そこに区として何か支援をしていくということができないのかなと思ったのですけれども、いかがでしょうか。狭いところで似たような形で、走行位置が分かりやすいような整備をしていってほしいと求めましたけれども、区の今のお考えを伺えればと思います。","respondent":"鈴木都市計画課長","answer":"区のほうで整備支援的なところのお話をいただきましたが、ほかの自治体の取組、まず商店街の主体的な取組を支えていきたいです。意識を持って自転車に乗っていただく、より明確に明示していけるような整備の考え方、整備形態を次回以降しっかり検討してお示ししたいと思います。","id":"exchange-002"},{"speaker":"のだて委員","kind":"意見","question":"駐輪場の整備もそうですし、形態の通行位置の明示、分かりやすくというのも、やはり利用者を含め、あと車、歩行者を含め、そういった分かりやすくしていくということ、整備していくということが、やはり安全にもつながってくると思いますので、そこはしっかりとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"それと、結局この計画の目的は何でしょうか。前回もそうなのですけれども、これの目標・目的は何なのか、これは何をするためのものかというのを説明するよう求めました。","respondent":"鈴木都市計画課長","answer":"実施検討にあたって令和４年の１１月、在住区民のアンケート４,０００世帯を無作為抽出しまして、区民アンケートを行ってあります。アンケートを実施しているというところで、計画の策定にはそうした声もしっかり反映して計画の検討を進めていきたいというところとともに、今。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"持っていかれてしまうと三千幾らですか、四千円弱のお金がかかるわけです。でも自転車がないと買い物ができないというのもあるので、そこもうまくいろいろ計画の中に入れてもらいたいと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"車の運転をしている方々もそれを意識して、車を運転していただくというようなものが、自転車ネットワークの整備の考え方です。その商店街店舗を利用していただく等々の啓発周知というのも、しっかり並行して行っていかなければいけないことなのかなと考えています。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"店舗もやはり責任という、自分たちのお店で買物しているわけだから、その人たちが利便性のいいように努力をするということが必要なのではないですか。でも、やはりやめていただきたいと思っているので、そこの啓発も同時にお願いしたいと思います。","respondent":"鈴木都市計画課長","answer":"個々の商店街、様々な取組、各々でやられている方もいらっしゃるでしょうし、そうしたところもできるだけ好事例等も集めて、そうしたところも先ほどのママチャリでの安全な乗車というか利用というか、そうしたところも計画の中では啓発も含めてしっかり行っていきたいと思います。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"その後補助２６号線が開通したことによって、ということは、そういったことの経過というのが今回のこの計画の中で反映されているのかどうか。いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"令和４年１１月から令和５年度にかけてですので、もう既に補助２６号線が開通された以降での調査をかけしていますので、まさに現状に合わせて調査をかけさせていただいたところです。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"今後も道路側の新規路線が開通したりして、車の流れがまた変わってくることが予想されますので、その対応もぜひお願いしたいと思います。今後はそうするとキックボード専用の駐輪場というのでしょうか、区として電動キックボード、その辺のお考えをお聞かせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"骨子案の１０ページのほうに、現在の民間事業者の電動キックボードのポートの整備状況が示されております。あるいは中間の見直しの中で、利用状況の変化を捉えて、必要な記載をそのときにまたしっかり行っていくというような考えです。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひご対応をお願いしたいのと、啓発行動というのでしょうか、そういったことも区の施策として併せてぜひご対応してほしいと求めました。そういった意味での考え方というのでしょうか、１０ページの部分とシェアサイクルの部分というのは、そこのご対応もお願いしたいと思います。","respondent":"鈴木都市計画課長","answer":"この７ページの今後の取組のところは、区として東京都から借り受けて商店街に貸し出すというような考えは、今現在ございません。この自転車の考え方とは別に、都市計画道路の暫定利用の考え方については、区としても前向きに考えていきたいです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"で乗捨てのマナーというのでしょうか、またその乗り捨てられたものの対策ということも念頭に置いた取組をぜひお願いしたいと思います。取締りのほうはしっかりするだとかということも考えてもいいのではないかと思えるのですが、その辺の基本的な考え方はいかがか尋ねました。","respondent":"工藤交通安全担当課長","answer":"そういったところも考えまして、また、駐輪スペースの確保をさせていただいているところです。はこちらのほうで駐輪スペースを確保し、引き続きそのような形でやらせていただければというように考えてあります。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"取締り強化というような観点からの取組も必要になってきているのではないかと思いますので、これは意見として述べさせていただき、質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"通行抑制となるとこれは警察のほうになるのでしょうか、というところのご意見・ご要望等の声があると。ご意見・ご要望というのは、だからこういうまちづくりとか行政とか通行抑制とかということに、というふうに理解していいのかという確認です。","respondent":"鈴木都市計画課長","answer":"恐らくですが、なかなか自動車を運転していてのアンケートのお答えいただいた数が、数的には少なかったのかなという受け止めです。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"そこら辺はここにどういうふうに表すかというのは別ですけれども、そういう感覚は、道路管理者として理解はしていただきたいなと。それから２点目のほうは、この計画以外のところになるのかなとも思うのですけれども、そういったところのお話というのは何かあるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"行政と商店街の連携のお話ですが、やはり計画の中ではしっかり記載をして、基本は計画の中でしっかり考え方と施策的なところを位置づけていきたいと。","id":"exchange-013"},{"speaker":"まつざわ副委員長","kind":"確認","question":"災害が発生したときは徒歩が原則という中で、これは自転車活用もありなのかなというふうに私は少し感じてしまったので、そこを確認させてください。私は何かそれぐらい踏み込んでいかないと、結局この自転車利用の交通安全の意識づけというのはできないと思っていますので、そこら辺のご見解を。","respondent":"鈴木都市計画課長","answer":"この点につきましては第３回の協議会の中で、第３回の協議会の中でちょっと誤解を与える、より分かりやすい記載を心がけていきたいと思います。","id":"exchange-014"}]},{"id":"topic-02","title":"都市計画道路の計画変更およびそれに伴う用途地域等の変更に係る説明会の開催","agenda":"都市計画道路の計画変更およびそれに伴う用途地域等の変更に係る説明会の開催","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それが南側のところですか。先ほど、この変更によって既存不適格はないということだったのですけれども、ほかにも住民に考えられる影響などがあれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今回の変更は、計画線を現状の道路に合わせるですので、さらにそれ以上何か整備がその後発生するということはございません。用途地域等の変更によって、法律を離れてのお話になりますとなかなかお答えづらいところもありますが、基本的にはないのかなと受け止めてあります。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"その下のピンクも４００から３００まで下がっているということなのですが、要は評価が下がるという影響があるのかどうかというのはいかがでしょうか。いわゆる地権者の方も、そこも理解をされているのかというところはいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"ご指摘のとおり容積率が変更前が４００から変更後は３００に下がっていく形ですが、変更前が４００から変更後は３００と基準容積は下がっているのですが、そこはしっかり権利者の方にも丁寧に説明していきたいです。","id":"exchange-016"}]},{"id":"topic-03","title":"品川区無電柱化推進計画の一部改定","agenda":"品川区無電柱化推進計画の一部改定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これはこの無電柱化を進めていく、これはどういった場合に単独地中化を進めていくというものになるのか、そこを伺いたいと思います。区道が対象ということになっているわけなのですけれども、今全体としてはどこまで進んでいるという状況なのか伺いたいと思います。","respondent":"森道路課長","answer":"今、路線としての幅員が少し狭いというところもありますので、引き続き沿線事業者等々と検討していきたいと考えているところです。狭い区道が多いところですけれども、今お示しした２路線も加えて、できるところを時期を見て積極的に取り組んでいきたいと考えております。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、約７％ということで、なかなか道のりは長いという感じですけれども、ぜひこれは防災性の観点からも含めて進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"早くしてほしいという地域の切実な思いがあるのですけれども、無電柱化と同時に、街灯があると当然電柱がなくなっても意味がないです。それはどういう工夫をされるのか尋ねました。","respondent":"森道路課長","answer":"夜間の安全を確保していますが、それが電柱がなくなってしまいますと、やはり街路灯として単独で設置をする必要があろうと思っています。それを確実に離して、できるだけ端っこのほうに載せまして、通行の支障ができるだけないようにしたいとは思っています。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、このピンクのところのほかに次の候補というのはないのですか。そういう計画はあるのか尋ねました。","respondent":"森道路課長","answer":"それと含めて連携して無電柱化が進められるところをしていきたいということで、避難道路として拡幅するに合わせて、今回無電柱化を図るです。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に整備方式というのがあるのですけれども、１８ページ辺りでしょうか。非常にコストがかかるというお話だったのですが、大分ここは改善されているのか尋ねました。","respondent":"森道路課長","answer":"コストにつきましては、例えばより浅いところに埋設をするとか、そういった技術については従来から国交省のほうで提言をされているところです。","id":"exchange-021"},{"speaker":"田中委員","kind":"確認","question":"あそこは分かるのですが、6)番のほうはこの下の拡大図の今のこの線形に並行して拡幅されるということでいいのでしょうか。なので確認したいのは、6)番のほうはこれで終わりということではなくて、今後も延長する可能性はあるのかというところを確認したいと思います。","respondent":"森道路課長","answer":"6)番につきましても、今財務省の旧官舎といいましょうか集合住宅がありますけれども、そちらの方向に２ｍ程度拡幅する予定です。文章本文の下から２段落目、広域避難場所である林試の森公園にアクセスする道路の無電柱化も今後検討していきたいというふうに示しています。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。それと、その先の三間通りまでのルートが今回の地中化の対象になり得るのかというところのお考えをお聞かせほしいと求めました。","respondent":"森道路課長","answer":"ここの考え方につきましては、バリアフリー計画にも位置づけられているような事業をしっかりと進めていければと考えているところです。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問","question":"個別にはまたいろいろ意見がありますけれども、ないところについては当然点字ブロックも同時に検討、敷設されるという理解でよろしいのか尋ねました。","respondent":"森道路課長","answer":"あるいは景観の面というところでの目的で電柱を撤去していこうと考えているところでございまして、それに基づいて設置していければと考えています。","id":"exchange-024"}]},{"id":"topic-04","title":"バリアフリー特定道路整備工事","agenda":"バリアフリー特定道路整備工事","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"工事期間が７月１４日からなので、理解が得られているのかどうかというところで伺いたいと思います。先ほど路線数とかがあったのですけれども、同様に病院があるところで、ほかにも整備できていないところというのはあるのかどうか伺いたいと思います。","respondent":"森道路課長","answer":"十分ご理解いただいているとは思いますけれども、工事にあたりまして、具体的なご要望も真摯に対応してまいりたいと考えております。なかなか抜本的な部分は難しいのですけれども、引き続き検討していければと考えているところです。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"ということで、ぜひこうしたバリアフリー化というのを進めていってほしいと求めました。ぜひ、今ほかのところも検討しているということでしたけれども、それは進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"そのうち２１路線・区間が完成ということなのですが、完成したところが具体的にどういうところだったのかを見た上で質疑をすべきだったと思いますが、品川区においてその区間が選定されているという考え方でいいのか尋ねました。","respondent":"森道路課長","answer":"ですので、例えば武蔵小山駅という旅客施設から福祉施設である病院までというような形で進められております。国道と、都道もそうですけれども、区と一緒にやって進めているです。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"確認ですが、そうすると、品川区におきましては２４路線がその対象であり、これが完成すれば、その目的は、もうこの法律に基づいた目的としては完成されるということで、新規の指定をする必要性のある場所はもうないという考え方でいいのか尋ねました。","respondent":"森道路課長","answer":"ただ、それで区としてもバリアフリーが終わりというふうには全然考えておりません。そういったものは道路改修のたびに進めていくべきものだろうと考えておりますので、引き続きバリアフリーを進めていきたいと考えていいます。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問","question":"聞かれなかったので、２４分のこれで２２か所目が完成するということで、あと２か所はどこか尋ねました。","respondent":"森道路課長","answer":"それから、もう一つが中小企業センターから補助２６号線までの間です。誘導ブロックの整備であったりというようなものを進めていきたいと考えておりますけれども、整備の時期を考えていきたいと思っています。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/372951?Template=document&Id=4384#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":36804,"voices":87}},{"id":"r05-20230724-9","meetingId":"r05-cm07","date":"2023年7月24日","dateIso":"2023-07-24","committee":"文教委員会","time":"午後 １時００分～午後 ３時３６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"令和５年度第１回家庭教育講演会","agenda":"令和５年度第１回家庭教育講演会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回の講演の内容と講師を決めた考えというか理由を伺いたいなというのが１つです。第２回は子どものレジリエンスについて講演予定ということなのですが、これは同じ方なのか尋ねました。","respondent":"宮尾庶務課長","answer":"第２回につきましては、資料に記載のとおり、子どものレジリエンスについて、同じ平野真理さんにご講演をいただく予定で、今、進めているところです。周知についてですが、それから関係者の皆様にお配りをさせていただいて、ご覧いただくというような周知の方法をとってあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"ガイドラインについて伺ったのですが、令和５年度に向けてガイドラインを最終的に今つくっているのですというご答弁でしたけれども、それも含めて簡単に教えてもらえればと思います。","respondent":"宮尾庶務課長","answer":"変更点といたしまして、特定の考え方、一言注意書きとして加えさせていただいたところです。","id":"exchange-002"}]},{"id":"topic-02","title":"学校選択制の運用等","agenda":"学校選択制の運用等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この入学率というのはどういう意味なのか伺いたいのと、あと２行目ですが、伺いたいと思います。","respondent":"柏木学務課長","answer":"１つ目、入学率ですが、私立等に抜ける方もいらっしゃいますので、その部分を抜いた区立の学校に入ってくる方の率となります。大きなマンション計画、何百戸とかというものについては、それなりに影響を与えるものと考えています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"再開発と書いているものですから、こういうことを書いているのかなということで伺いたいというのが一つ、後で教えてください。区域内にいる子どもたちを全員受け入れるとしたら３５学級必要なわけであって、具体的にどういうふうに対応する考えなのか、伺いたいと思います。","respondent":"柏木学務課長","answer":"それと、再開発だけでなく、こちらの資料に書いてありますけれども、３５人学級の影響も一つの要因と考えています。最大２８教室以上の対応につきましては、学事制度審議会のほうで通学区域の変更を含めた学事制度を検討いただき、制度設計を考えてあります。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのが、１つ目が、この予測資料は誰が作成したのかというのが１つ。４つ目は、どういう関係部署との連携になっているのか、具体的に伺いたいなと思います。","respondent":"柏木学務課長","answer":"大型マンション等の情報ですとか連携についてですが、具体的には４０戸以上の集合住宅の建設計画については教育委員会にも照会が来ます。内容等については教育委員会でも認識し、計画１件１件について、まちづくりの所管のほうに意見としては出しています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"最後のところなのですが、では、２の(1)の表というのは、そうした照会があった集合住宅の増加数を加味している内容だということなのかを確認したいのと、それと、照会とありましたけれども、どこから、どのようなタイミングで、どんな目的で照会が来るのか、そこら辺、お伺いします。","respondent":"柏木学務課長","answer":"マンション等の計画ですが、４０戸以上のマンションの場合は、教育委員会にも、業者、デベロッパーというのですか、から直接照会が来ます。それに基づいて、教育委員会でも把握するという状況になってあります。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"そうですかと思ったのですけれども、今出されている資料の時点でいうと、どこまでが加味されているものなのか。例えば何年後に建てるマンションが加味されているかとか、そこら辺を最後にお伺いしたいと思います。","respondent":"柏木学務課長","answer":"就学人口にどこまで加味しているかというと、今、計画されているものについては全て加味しているという状況になります。ですので、これから大型のものをつくるというものまでは、ここには入ってございません。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと答弁漏れがあったかなと思うので、もう１回聞くのですが、分かりました。そういう照会があったときに何を返しているのか、どういう回答をしているのかというのがもしあれば、伺います。","respondent":"柏木学務課長","answer":"こういう計画を提出する予定という形で、事業者のほうから今こういうものを計画していますという情報が来るです。","id":"exchange-008"},{"speaker":"吉田副委員長","kind":"質問","question":"予想不可能なところはあると思うのですけれども、それから、今後も品川区は学校選択制を続けるという方針なのでしょうか。当然子どもも増えていくということだと思うのですが、その辺を今後どのように見込んでおられるのか、まず伺いたいと思います。","respondent":"柏木学務課長","answer":"城南小学校のもともとの見込みですが、全部で１８学級という見込みと記憶しています。選択制を継続するのかということですけれども、現時点では、選択制はこのまま進めていくということで考えてあります。","id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問","question":"ということは、やはり城南小学校を建てたときの見込みは大きく狂ったと言わざるを得ないということなのでしょうか。そうなるのではないかなと思うのですけれども、その辺についてどうお考えなのか尋ねました。","respondent":"柏木学務課長","answer":"城南小学校の見込みが間違っていたのではないかというご指摘かと思いますが、結果としては、見込みを大きく上回っているということがありますので。それは浜川小学校ですとか第四日野小学校も同様の進め方です。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問","question":"今のこの状況の、その辺は考慮してほしいというような、そういう庁内での意見の出し方とかいうのはないものなのでしょうか。教育委員会のほうでこれだけの教育が準備できるという言い方がいいのかどうか分からないのですが、そういうことは一切ないということなのか尋ねました。","respondent":"柏木学務課長","answer":"教育委員会の意見を言えるかというところですけれども、４０戸以上の集合住宅の建設計画については、先ほど言いました照会があります。","id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"子どもたちの最適な教育環境を維持するという方向で、ぜひ今後も学校の建て替えとか、そういうことは考えてほしいと求めました。もし何かコメントがあったら伺いたいのですが、いかがか尋ねました。","respondent":"柏木学務課長","answer":"今改築している学校等につきましては、今後、就学人口が減った場合でも、そういう転用も含めて考えた上での設計、建設をしています。","id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"何点かお伺いします。ビジョンを教えていただきたいのと、新しい学校を建設するという考え方があるのかどうか、説明を求めました。","respondent":"柏木学務課長","answer":"学事制度のほうで、通学区域変更を含めた学事制度の検討を行っていただいておりますが、通学区域変更以外での方策についてですが。それと、新たに学校をつくるという計画ですが、今のところ、新しく学校をつくるという計画はございません。","id":"exchange-013"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"区としてもしっかりと情報提供してあげてほしいのと、実はここ、その辺はぜひ早急に取り組んでいただきたいと要望しておきます。それはなぜかというと、その点、もし考えがあれば説明を求めました。","respondent":"柏木学務課長","answer":"今、委員からあった江東区ではないかというお話ですけれども、うちのほうに情報がないものですから、そこら辺は情報を得ながら研究してまいりたいと思います。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、つまり引っ越してこられる方も出てくると思うので、その辺の浜川小学校の見込みをもうちょっと具体的にお願いしますというのが一つ。学事制度審議会では、新しい学校も含め、あるいは今までの学校の適正配置に関しての議論なども諮問の中に入ってくるのか尋ねました。","respondent":"柏木学務課長","answer":"浜川小学校の学級数の件ですが、今、浜川小学校は最大３０クラスまで対応できるような形でつくってあります。就学人口の見込み等でいきますと、それで十分だろうです。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今後の小学校の運営をしてほしいと求めましたが、その点、浜川小学校についてはいかがでしょうか。学事制度審議会のほうは、適正配置については今回はないということで確認しました。","respondent":"柏木学務課長","answer":"３０クラスあれば、大型マンションができたとしても、ある程度までは対応できると考えています。それ以上につきましては、その都度、また情報があり次第、検討したいと思います。","id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"最後、１つだけ付け加えて。学級増に対応してほしいと求めましたが、その点、お願いします。","respondent":"柏木学務課長","answer":"今、委員からございましたように、普通学級を優先して特別支援が必要な子どもの対応にしわ寄せがいくというのは、教育としては最悪なパターンですので、当然そういうことはないようにしてまいります。","id":"exchange-017"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"精査の上、不正がということになりますと、結果についてもぜひ報告してもらいたいと思いますので、よろしくお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"すまいるスクールのお弁当のことをお尋ねしたのですが、尋ねたのですけれども、それはなぜかということが２つ目。学校名とか、そういうことを委員会で、こういう事例があったということを委員会などで報告しないのはなぜなのでしょうかということをお尋ねします。","respondent":"染谷子ども家庭支援センター長、大澤子ども育成課長、中谷指導課長","answer":"ヤングケアラーに関するＳＮＳを活用した相談窓口の開設につきましては、７月３日付で開設を行っております。予定ですけれども… その他で報告を予定しておりましたが、所管質問で出ましたので、その中でまとめてお答えをさせていただいたところです。今後、試行が始まりますので… 体罰につきましては、おっしゃっていただいたとおり、こちらの文教委員会で報告しています。","id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"質問","question":"どれぐらい申込みの方がいらっしゃったのかぐらいは教えていただけると、もう夏季休業が始まってしまっているのですが、知りたいところではあります。ごめんなさい、現状の申込みというのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問","question":"それはもちろんそれでいいと思うのです。こういうことで１名あったとかということは、非公表ですから議事録を見ても私たちは分からないので、いかがか尋ねました。","respondent":"米田教育次長","answer":"教員の服務事故に関しましては、教育委員会はそういうような形で非公表の場で行っているものです。確実に委員の皆様方に伝わるような方策について、今後、適切に対応していければと思ってあります。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5104#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":14937,"voices":67}},{"id":"r05-20230724-5","meetingId":"r05-cm07","date":"2023年7月24日","dateIso":"2023-07-24","committee":"総務委員会","time":"午後 １時００分～午後 ２時０３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"行政評価","agenda":"行政評価","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ここにも書いてあるのですけれども、改めて導入した目的、なぜ実施するのかという背景とともにご説明いただきたい。肩書というのでしょうか、メンバーはしっかり公表していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"今回、予算事務事業の全てを対象としているというところと、先ほど申し上げた新公会計制度基本方針に基づきまして実施するというところで。外部の方も評価しやすい、あるいは意見を言いやすいといったものがあるかと思いまして、政策評価を実施するものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"そうした評価は進めていただきたくないと思うのですけれども、一言、伺いたいと思います。それもご説明ほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"必要性、執行率の高い・低いだけで何か事業の評価をするということではないので、そちらだけご了承いただきたいと考えています。６番の評価のところの、Ｄを、各所管あるいは企画部でつけていくという形です。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"今回、行政評価シート、またいろいろ変わってきたのですが、これはどこかの自治体で何かやっているところを参考にされたのですか。それを説明するよう求めました。","respondent":"吉岡政策推進担当課長","answer":"こちらの行政評価シートですけれども、他自治体が使っているもの、そのままということではなくて、そういった他自治体の動向や内容をしっかりと吟味させていただきながら、品川区の行政評価にふさわしいといいますか、かなうような形で、シートを作成・検討したものです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"なかなか役所の仕事というのは、建築でも土木でも教育でも福祉でも、専門性が高いじゃないですか。私たちはどういうふうにすればいいのですかというときに、区民の意見もどこかに添えられるような、何か工夫も必要なのか。","respondent":"吉岡政策推進担当課長","answer":"事前勉強検討会というところを設けさせていただいて、２つの分野につきまして、しっかりと事業の内容をご説明する時間を設けさせていただいた。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"それで、企画部でまたチェックするということですけれども、やはり人間関係というのがあるじゃないですか。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問","question":"私はパフォーマンスで終わってほしくないと思っているので、きちんと実りあるものにしてほしいと思うのが１つ。だから、そういう発想がないのに、ただ委員構成をやっても意味がないような気がしてならない私がいるので、何か、少し分かるように説明してほしい。","respondent":"吉岡政策推進担当課長","answer":"そういった意味で、このタイミングを捉えて今年度、行政評価を実施するです。今後の選定、次年度以降のところで検討するというところと、あるいは事前の検討会といったものを有意義に活用して実施していきたいと考えています。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"どうなのかと考えていくのであれば、そういう組織改正をどういうふうにしていくのかということも視野に入れてやらないと、やる意味がないと思う。そう思うのは、要望だけにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"やるからには充実したものになってほしいと思うのですけれども、評価シートのほうをお伺いしたいのですけれども、他の自治体ですと。例えば会計年度任用職員の方がどれぐらい関わられているなどというところが、どこかで分かるようになっていくのかどうか、お願いいたします。","respondent":"吉岡政策推進担当課長","answer":"委員のご紹介がございましたように、給与関係費のところが、いわゆるそれぞれの事業でどれだけ人件費がかかっているかを判断する数字です。あるいは委託事業のところでできることはないかとか、そういった判断につながるというふうに、こちらとしては考えているところです。","id":"exchange-008"},{"speaker":"松本委員","kind":"意見","question":"多分もう、１回作られているシートなので、なかなか難しいところはあると思うのですけれども、その辺りもぜひ今後お考えほしいと求めました。しっかりと見られるのかなとも思うのですけれども、その辺りは何か考慮されているのか、お願いいたしますとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"令和２年度は、令和２年度から４か年分、載せさせていただいているところです。令和２年度からの実績だけで判断するということではなくて、判断、評価するです。","id":"exchange-009"},{"speaker":"塚本副委員長","kind":"質問","question":"こういう評価を来年度の予算案にどういうふうに反映していくのかというところをお聞きしたいのですけれども、それとも、お伺いできればと思います。どのように予算編成に反映していく、影響があるのかというところをお聞きしたいというのが１つ。","respondent":"吉岡政策推進担当課長","answer":"あくまでも行政評価は評価という部分になりますので、予算の査定ではございません。やはりこの評価を踏まえたところで、予算要求、予算編成をしていくというようなところです。","id":"exchange-010"},{"speaker":"塚本副委員長","kind":"質問","question":"影響されるかというのは、どのように期待されているというか、思われているのか。そこをお聞きしたい。","respondent":"吉岡政策推進担当課長","answer":"行政評価の今後の見込みというところになるかと思うのですけれども。今後新しい展開が見込めないものに関しては、さらに全庁的な事業をよりよくしていきたいというような考え方で、この評価を行っているところです。","id":"exchange-011"},{"speaker":"塚本副委員長","kind":"意見","question":"(2)のほうで、例えば防災・強靭化、例えば地域防災計画などというのが評価の対象になるのか。どういう評価の中身というか、どういう流れを見込んでいらっしゃるのかを、最後に聞きたいと思いますとの意見を述べました。","respondent":"吉岡政策推進担当課長","answer":"政策評価の２つのテーマについてですけれども、総合実施計画に載っている政策の柱の単位のところで、評価していくというようなところです。","id":"exchange-012"}]},{"id":"topic-02","title":"大井第三地域センター・区民集会所移転に伴う内装工事請負契約","agenda":"大井第三地域センター・区民集会所移転に伴う内装工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"大井第三地域センター、新たに区民集会所をつくるのですが、ここの全体は民間の土地であり所有物なのですか。それとも、大井第三地域センターは、これはもう品川区のものなのだというような、所有区分はきちんとなっているのか尋ねました。","respondent":"佐藤（聡）経理課長、小林施設整備課長","answer":"所管から聞いている限りということになってしまいますけれども、本件の共同住宅に関しましては、委員ご指摘のとおり、民間の所有物になっております。したがいまして、この地域センターおよび区民集会所部分については… あるいはエレベーターの設置だったり、トイレを設置したりする工事、これらにつきましてはテナント側で行う工事になります。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"もしここを退去するときは、居抜きということで、そのまま残していっていいのですか。参考のために説明を求めました。","respondent":"小林施設整備課長","answer":"これも一般論となってしまいますが、基本的には原状復旧が原則になりますので、区で行った工事の部分については、区で撤去してお返しする形になります。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"居抜きで使ってくれてもいいけれども解体費分をどうやって、こういうのは原則、誰が考えるのか。施設整備課長がやるのか分からないけれども、各所管でやるのか、どういう判断を品川区はしているのかとの意見を述べました。","respondent":"佐藤（聡）経理課長","answer":"相手方がある場合は相手方と調整して、必要な予算があるのであれば、年度の予算編成の中で検討していくという形になろうかと思います。検討して、検討体制についても検討されて、チェックしていくということになろうかと思います。","id":"exchange-015"},{"speaker":"澤田委員","kind":"質問・要望","question":"質問が２点ほどありまして、まず授乳室が２階にあると思うのですが、授乳室の内容について教えていただきたいと思っています。この場所は一般開放できる場所なのか、それともできない場所なのかを説明するよう求めました。","respondent":"小林施設整備課長","answer":"３点のご質問のうち、まず授乳室ですが、２階に設置しておりますが、キッチン、いわゆる給湯関係は設置しております。それから、屋上部分の開放かと思うのですが、通常、屋上の開放というのはしないと所管から聞いてあります。","id":"exchange-016"},{"speaker":"澤田委員","kind":"質問","question":"最初の授乳室の件ですけれども、ミルクをつくる電子レンジなどは、聞き逃したのですけれども、給湯室にあるのですか。授乳用の椅子はあると今おっしゃられたと思うのですが、特におむつ替えなどの台はないということか尋ねました。","respondent":"小林施設整備課長","answer":"備品での対応になりますので、お湯をつくるという話になりますと、そちらで対応できるかと思ってあります。たしか各トイレに、おむつが替えられるシートを設けてありますので、そちらで対応できるかと考えています。","id":"exchange-017"},{"speaker":"澤田委員","kind":"質問","question":"授乳室の件はよく分かりました。残りの部分を有効活用したり、休憩スペースだったりというのが特にないのかなと思うので、そういうものをつくったりというのは難しいか尋ねました。","respondent":"小林施設整備課長","answer":"いろいろと所管の考えの中では、やはり屋上部分について、様々懸念はあるかと思ってあります。様々設計を進めていく中で、当然、施設の状況とか屋上の使用状況によって様々変わってくるのかと思ってあります。","id":"exchange-018"},{"speaker":"澤田委員","kind":"質問・要望","question":"最後に要望ですけれども、少し休めたりするかと思うので、最後のは要望です。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"品川区立五反田産業文化施設内イベントホール舞台照明設置その他電気設備工事請負契約","agenda":"品川区立五反田産業文化施設内イベントホール舞台照明設置その他電気設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"先ほど石田秀男委員からも少し質問が出ましたけれども、人員、交渉人という人はいるのですか。その辺は、もちろん快諾されてやるのでしょうが、そういうのは何か問題点はなかったのか尋ねました。","respondent":"佐藤（聡）経理課長、小林施設整備課長","answer":"先ほどの案件のご回答にもつながりますけれども、各所管で、まずは相手方と交渉を通してやっていくということになろうかと思います。地域のにぎわいというところで、商業・ものづくり課で所管して… 私から、後段の部分のご質問にお答えします。今年の１２月までに終わる予定ですので、１月から工事を始めて終わらせる形ですので、支障はないと考えています。","id":"exchange-020"}]},{"id":"topic-04","title":"バリアフリー特定道路整備工事請負契約","agenda":"バリアフリー特定道路整備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"何でここの場所を今整備しないといけないのかという。段差解消とか勾配の改善とかありましたけれども、そんなに問題ないかと思ったのですけれども、その点について分かる範囲で説明を求めました。","respondent":"佐藤（聡）経理課長","answer":"生活関連施設であります病院がありますので、そちらへの動線ということで、バリアフリーを図るべき道路ということで指定されております。点字ブロックですとか、車道との段差を解消することによって、よりバリアフリーに使えるようにという意図で整備するところです。","id":"exchange-021"},{"speaker":"松本委員","kind":"質問","question":"植物、街路樹を含めて、この辺りはどのぐらいのスペースを取るような計画になるのでしょうか。お願いします。","respondent":"佐藤（聡）経理課長","answer":"聞いている限りということになってしまうので恐縮ですけれども、歩道に関しては、現行の１.８メートルから２メートルに拡幅すると聞いております。全面同じような形ではなく、通れる範囲を確保しつつ、そういった利便性も含めて整備すると聞いているところです。","id":"exchange-022"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"その他ということで、１点、７月１８日に発表された職員の懲戒処分について伺いたいと思います。伺いたいことは、さらに重いと思うのですけれども、その点についてはどう考えているのかという点をお伺いしたいと思います。","respondent":"崎村人事課長","answer":"最初にこういった事案ですということをご報告させていただいた後、懲戒処分を実施した後、報告させていただいたということがございました。引き続き、研修等を通じてですけれども、綱紀粛正等を図っていくといった考えです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"意見","question":"区として認識したのが６月中旬だったというお話がありましたけれども、担当の管理職に４月からなって、やはり重いと思うのです。やはり４月２２日というのは重いと思うので、その点についても最後に一言コメントをいただけたらと思いますとの意見を述べました。","respondent":"崎村人事課長","answer":"２か月近く遅れていたということ、管理職としての適格性がいかがなものかといった判断もございましたので、係長級への降任といった分限処分も併せて実施したところです。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"１点だけお伺いしたいのですが、すごく負担が増えているとお聞きしているのですが、その辺に相当負担がいってしまっているのですか。説明を求めました。","respondent":"崎村人事課長","answer":"詳細が国から示されるかと思いますので、そういったことについて戸籍住民課等から人員配置についてのご相談があったときには、真摯に対応していきたいと思います。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"その負担ということで、分かる範囲で説明を求めました。","respondent":"横田情報推進課長","answer":"現在、国から、どれぐらい負担があるか、どういう事務を行っていくかという調査が来ていまして、それを１回国に戻しまして、それから国からの調査が再度、こういう調査をしてくださいというのが秋頃の予定になっています。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2272#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":21286,"voices":85}},{"id":"r05-20230725-14","meetingId":"r05-cm07","date":"2023年7月25日","dateIso":"2023-07-25","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"午前中の新庁舎整備に係る説明会でも質疑が様々ありましたけれども、しっかりと受け止めていただきたいと、要望だけ言っておきます。ご説明いただけますか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"エレベーターの考え方についてのご質問にお答えします。様々な条件により、台数等々が変わってきますので固定ではありませんが、動線としては区分するような形で考えているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"エレベーターとしては、低層と高層の２種類に分けるということでよいのか、確認させてください。その手引の作成に障害がある方の当事者も加えて、ぜひ当事者の意見が反映するように進めてほしいと求めましたけれども、併せていかがか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"３点目の質問で、今年度というくくりではないのですけれども、基本設計が来年度の５月３１日まで実施する予定です。どのような形で実施するかにつきましては、様々な場で周知等させていただいたり、この場でお知らせさせていただければと思ってあります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"バリアフリー化１つとっても、ぜひ当事者の意見を聞いてほしいというのは、繰り返し指摘があったと思います。来年５月３１日までに手引を作るということであれば、手引に反映してほしいと求めましたが、改めて伺います。","respondent":"大友新庁舎建設担当課長","answer":"先ほど、委員からお話がありました、計画の中にあるゾーニング計画の４２ページ目。この道路レベルでも配置を検討しているというところ、２階がメインの協働・交流スペースになるのかなというところで、検討を進めているところです。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、広町の部長・課長もいらっしゃるので、１点だけ確認したいことがあるのです。活用という言われ方はしているのですけれども、これはどのような意味なのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"確認","question":"ただ、いずれにしても、今の第二庁舎の機能としては、新しい庁舎に入ってくる。これは変わっていないということでよいのか、その点だけ確認したいと求めました。","respondent":"山下新庁舎整備課長","answer":"今、ご質問のあった第二庁舎における行政機能につきましては、新庁舎への集約ということで考えているところです。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"提案","question":"そのときの座長の提案で、議会機能以外の部分についての各会派の意見をまとめたものを当時の行財政改革特別委員会に送っているのです。理事者側はそのような認識があるのか、ないのか、少しお伺いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"こんの委員長","kind":"確認","question":"私から、前回の行財政改革特別委員会で出されたものが、私としても未確認の状態ですが、それを１１月のまとめに反映するのか、どうなのかというところはご答弁をいただけるものか尋ねました。","respondent":"山下新庁舎整備課長","answer":"議会機能検討を基本計画の段で進めていただく形で、作業としては仕切っていただいて、ご意見を承っているところです。議会機能部分については改めてご意見をいただいてまいりますけれども、また基本設計機能検討の段階でご意見を承る形になろうかと考えています。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"提案","question":"それに基づいて、幾つか質問をさせていただきたいのと、その大前提として、少し確認させてください。プロポーザルの段階で食堂についての提案等は、各５つの事業者からあったのかどうか、前提としてそれを伺いたいと思いますとの意見を述べました。","respondent":"大友新庁舎建設担当課長","answer":"続きまして、２点目のご質問なのですけれども、食堂につきましては、基本計画を基にプロポーザルを実施しております。基本的には、規模等々については様々でありますけれども、各社から食堂やカフェが入った形での提案を受けているという状況です。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も初めて伺って、先ほど、企画をした中で優れているということでこれを選ばれたのでしょう。そうすると、この配置がどう優れているのかということを教えていただきたいなというのが１つ。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"１点目、また階段やエレベーターがあることによって、中の執務スペースとして使える場所が広く取れる。食堂の導入の検討状況につきましては、様々な検討を進めて、導入の中身を確定していきたいと考えているところです。 １点だけ補足します。プロポーザルの提案内容に含まれた、どういった位置にあるかというところにつきましては、お答えを差し控えさせていただきたいと存じます。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"３つの中ではこれが選ばれるのかな、これを提案してくるのかなと思っていたのですが、そうではないということです。もう一つだけ伺いますとの意見を述べました。","respondent":"大友新庁舎建設担当課長","answer":"書かない窓口機能を設置すること、お話しいただいた点も踏まえて、どのような機能が求められるかということを具体的に検討してまいります。早期に反映させていくのですけれども、基本的には実施設計の中で実現できるように、検討のペースで進めていきたいと考えているところです。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"我々からは、区民が最もアクセスしやすい正面フロアの近くに配置していただきたいということを要望させていただいています。今日は基本設計の提案ということで、この辺りについても、どのように基本設計に反映していただけるのか教えてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"導入機能等々の中で検討していくもの、そのような声を多数いただいているところもあり、検討してまいりたいと考えています。２点目、緑の考え方につきまして、できるだけ緑を取り入れた整備を検討してまいりたいと考えているところです。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"提案","question":"職員用の防災備蓄スペースを十分に確保していただきたいということもご提案しています。前回の繰り返しになっているのですが、一応、会派の提案ということなので、念のため、確認しますとの意見を述べました。","respondent":"大友新庁舎建設担当課長","answer":"ヘリポートも必要機能ということで、検討の素材には挙がるのですが、そのほかにも屋上の活用方法として様々なものがあります。こちらを比較検討して、検討させていただいて、導入機能を決めていきたいと考えているところです。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今、広場１号のところが整備されていまして、Ｂ１地区が、まさに新庁舎の建設予定地になっております。なぜこのような通常の免震工事ではなくて、技術的な面というのは、どのような面で優れていたのかということを教えてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"地下から免震をしていくというところで、２階の部分に免震層を入れるとなると、その部分についての業務継続性の確保が少し難しいという点があります。地下から免震をすることによって、建物全体での業務継続性が生まれるというところで、高く評価されているところではあります。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３５ｍから４０ｍぐらいがりんかい線が通っていて、それに至った理由になった、そのような構造にしたのかなと思いました。建物を建設するに当たっては問題ないのかなとは思うのですけれども、もしお分かりになれば、りんかい線との関係性を教えてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"一番浅い部分で行くと、地盤面から１３ｍ程度、深いところで２０ｍ程度の位置に入っているところです。その荷重内で建物を建てる形もできるような区分地上権でございまして、その制限の中で活用を図っていくということで設計を進めている状況です。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"建設するには特別の支障はないということでいいのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"りんかい線の部分には全て地下構造物を作れなくなってくるので、全くないかと言われると、制限はあるという形にはなります。その制限の上での整備、設計を進めていくという形になります。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問・要望","question":"少しお伺いしたいのが、今回の資料で言うところのＢ－１地区は赤い外枠で囲まれていて、赤枠の中に長方形が２つあるかと思うのです。この２つの関係というのはどのように理解すればよろしいのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"左下の図の中で、赤枠の中に四角が２つあるという点についてお答えさせていただきたいと思います。基本的には右側に四角が１個あるような状態だったかと思うのですけれども、少し建物を建築していく考えで、設計を進めているところです。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"そうすると、歩行者デッキの部分と動線がかぶってくるのかなと思うので、左側の部分に建てるのは、２階建てのものを建てる計画なのか、あるいは歩行者デッキをぶち抜いていく形で造ることを今のところ想定しているのか、どちらなのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"さらに、そこに広場をという考えも用意しなくてはならないところもありますので、現実的には難しいのかなと思います。ですので、高くても２階、３階までのもの、もしくは平の１階になるのかなと考えています。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"図面の執務機能の北側にある２基のエレベーターは、比較的建物の真ん中といいますか、横面の真ん中ぐらいに設置されています。そうすると、２階と３階ぐらいからはせり上がってくるといいますか、はみ出してくるという構造を想定されているという理解でよろしいか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"私からも少しご説明をすると、これからの検討にもなるかと思うのですけれども、ロータリーの上部も建物になる。２階・３階部分以降は、今、設計を検討しています。","id":"exchange-018"},{"speaker":"塚本委員","kind":"確認","question":"少し細かいところで確認させてください。現庁舎にあります国および都の機関が過不足なく新しい庁舎にも入ってくるというところで、最終的にどうなっているのかということを説明するよう求めました。","respondent":"大友新庁舎建設担当課長","answer":"今、国の機関は、その形での調整を図っているところになります。国のどのような機能が入るのかというところにつきましては、調整段階というところでお答えさせていただければと思います。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、法務局がこの先どうなるかということについては、現段階では、まだ入るとも言えないし、入らないとも言えないという理解でよろしいか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"現機能をそのまま持っていくという前提で国との協議をしているところではありますけれども、確定的な形でのお答えができないというところで、ご理解いただければと思います。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"今後とも協議をよろしくお願いしたいと思います。基本設計の段階で、ほぼこのフロアのこの位置というのは、もう決めていくという理解でよろしいか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"サテライトスタジオなど、設計に関わって導入する機能につきましては、導入するか、しないかも含めて、基本設計の段階で、配置検討まで含めて実施してまいります。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"どちらをとるかみたいな議論も出てくるかと思うのですけれども、ぜひそこは重々検討していただきたいとお願いしたいと思うのです。再度、ご答弁をお願いいたします。","respondent":"大友新庁舎建設担当課長","answer":"近接にあるべき機能、連携を図るべき機能等につきましては、その連携なども含みで、設計段階で配置計画をしてまいりたいと考えています。","id":"exchange-022"},{"speaker":"筒井委員","kind":"提案","question":"基本的な確認になるかと思うのですけれども、今回の資料は、設計事業者選定プロポーザルでの提案内容を基に作成しておりますということです。その辺りの確認をさせてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"設計会社につきましては、ＪＲの設計会社は異なるとお聞きしています。ＪＲとは常に協議体、会議体を設けて、調整しながら連携などを図って設計を進めているところです。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"約１年ないし２年ぐらいのずれが生じてしまうのかなと思っているのです。その辺りは、そのような理解でよろしいのか尋ねました。","respondent":"泉広町事業調整担当課長、大友新庁舎建設担当課長","answer":"先ほどいただきましたＡ－１地区、Ａ－２地区などの地区名が決まっているものにつきましては、地区計画といったものが定まってあります。そういった都市計画の中で地区を定めて、この地区名を準用して、今回も示させていただいてありま… それぞれの建物の竣工時期の違いにつきましては、今、お話しいただいたとおり、ＪＲ側が先行してオープンするという形で、Ｂ－１地区の新庁舎のほうが１年か２年遅れて竣工することになってあります。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"その辺りを区としてはどのようにお考えなのでしょうか。ＪＲとの連携とおっしゃいますけれども、ＪＲ側との調整というか、そうしたお話もされているのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"外観デザインの考え方につきましては、それに伴って周辺市街地への圧迫感の軽減に努めるということで、ＪＲの建物は１１５ｍとお聞きしています。庁舎としてのシンボル性にも考慮し、外観デザインを検討して進めてまいりたいと考えているところです。","id":"exchange-025"},{"speaker":"山本委員","kind":"質問・要望","question":"ほかの委員からのご質問で、通常のセンターコアなどに比べて、ビルの強度やコスト面でどうなのかということを少し教えていただきたい。特にコスト面などでデメリットはないのか少し気になっているので、メリットは先ほどお伺いしたのですが、デメリットがあれば教えていただきたいです。","respondent":"大友新庁舎建設担当課長","answer":"今までご答弁させていただきまして、１５階から１９階という想定の話の中では、低いほうで収められるのではないかなと考えているところです。","id":"exchange-026"},{"speaker":"山本委員","kind":"確認","question":"確認なのですけれども、日照というのは中側のフロアの日照、日当たりのことを言われているという理解でいいかどうかということ。何となくコスト高になるような印象を持つのですが、そういったコスト的なものは特には変わらないという見立てなのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"デメリットとしてもお話しさせていただいたのですけれども、メリットも大きいです。基本的な考え方としては一部あるかもしれないのですけれども、確実に周辺分散コアだから高いということは、一概には答えられないところではあります。","id":"exchange-027"},{"speaker":"松永委員","kind":"質問・要望","question":"多分、エアコンの室外機などかなということを想像してしまうのですが、そのことについて伺いたいと思います。この図を見ると、全部囲まれて、外が見えないのかなと思うのですが、少しその構造についてお知らせほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"電気をつけるに当たっては、電力だけに頼らないシステムということで、ガスを活用して電気にするというシステムの導入の検討もしています。具体的に導入する設備については検討上ではあるのですけれども、想定としては、そのようなところになります。","id":"exchange-028"},{"speaker":"松永委員","kind":"質問","question":"では、今の屋上のような感じではないということでよろしいか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"３６０度見渡せる屋上という形ではないという状況が今の検討段階の素案です。","id":"exchange-029"},{"speaker":"松永委員","kind":"質問・要望","question":"最後に１点、喫煙所の問題なのですが、新庁舎について、喫煙スペースは造られるのかどうかということを伺いたいと思います。中には難しいかもしれませんが、どういったところに造られるのか、教えてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"喫煙所につきましても、先ほど話がありましたサテライトスタジオのように、導入機能の中で検討していくものになります。一応、施設整備上の規定によりますけれども、こちらについては今後の検討とする形になります。","id":"exchange-030"},{"speaker":"せお副委員長","kind":"質問","question":"先ほど、飲食などの食堂やカフェなどの質問のご答弁で、カフェなどで十分なのかなみたいなお話があったと思うのです。周辺の整備状況を踏まえ計画となっているので、ここが一緒になっている理由というか、そういったところの考え方を説明するよう求めました。","respondent":"山下新庁舎整備課長","answer":"先ほど、来庁された方にすぐ届く場所に設置していくというところは、１つの目線として取り組んでいく必要があるのかなと考えています。比較的そこまで広いスペースをとらずに設置できる可能性はあるのかなと受け止めておりまして、また、その指導者の方を含めて。","id":"exchange-031"},{"speaker":"せお副委員長","kind":"質問・要望","question":"どういった方向性でいるのかというところも調査していただいて、私は目的で分けていただいて、調査していただきたいなと考えているところです。そこは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問","question":"それは、なぜなら、大空間を置かなければいけない。５つの事業者があって、それが１つの選定理由で特筆されている理由というか、もし現状を教えていただけるようなニュアンスがあれば説明を求めました。","respondent":"大友新庁舎建設担当課長","answer":"Ａ３のカラー刷りの資料をご覧いただければと思うのです。この高さを活かしたところで、広く区民に関わって、議場を身近に感じることができるという点を挙げさせていただいているところです。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"意見","question":"先ほど、区民を見下ろす、見下ろさないという話がありましたが、区民に上から見ていただいているということで、なるほど、特筆すべきだなというところで、ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"えのした委員","kind":"質問","question":"先ほど出ましたが、コア配置の比較で、周辺分散コア型の自由度が高いとお伺いしました。基本計画には、例えば、中央コアは豊島区、両端コアは中野区という事例がありますが、他の自治体でこういった事例はあるのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"自治体の事例といたしましては、把握してないところです。低層の２階や３階ではよくある話ではありますけれども、オフィス棟の実績等々は多分にあるというコアです。","id":"exchange-035"},{"speaker":"えのした委員","kind":"確認","question":"オフィスなどでは多いということで確認がとれました。ちょうど今整備中の中野区や、完成している他の自治体の庁舎の視察や聞き取り調査など、これからもしていく予定はありますか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"近隣区の視察、また、近隣区でなかったとしても、同規模の庁舎を建てた事例など、調査をしています。その調査の中での働き方なども含めて新庁舎の状況を確認しているところで、今後も継続して視察等々を進めていきたいと考えているところです。","id":"exchange-036"},{"speaker":"まつざわ委員","kind":"質問","question":"行き届く、そういった周知の工夫というのは、相当頑張ってやらなければいけないかなと思っているのです。そこだけお願いします。","respondent":"山下新庁舎整備課長","answer":"一定、取り組む方策の１つとして考えている方式は、広く皆様に知らせるように取り組んでいきたいと思います。広報しながわでしたり、ＳＮＳの活用が１つ大きいかなと思っておりまして、皆様に普及できるような方法を今後も研究してまいりたいと考えています。","id":"exchange-037"},{"speaker":"まつざわ委員","kind":"意見","question":"ぜひ本当にいろいろな町会を回っていただいて、それこそ私たち議員も協力の下、何町会あってもいいと思うのです。地域センターでもいいと思っていますので、丁寧にしつこくやっていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/642035?Template=document&Id=6152#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":27259,"voices":99}},{"id":"r05-20230726-19","meetingId":"r05-cm07","date":"2023年7月26日","dateIso":"2023-07-26","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時１２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/924121?Template=document&Id=6638#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":716,"voices":5}},{"id":"r05-20230727-10","meetingId":"r05-cm07","date":"2023年7月27日","dateIso":"2023-07-27","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"しながわシティラン実行委員の推薦","agenda":"しながわシティラン実行委員の推薦","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"７月２４日に議長に依頼が来たということで、７月２８日までというのは、意見というのは申し上げたのでしょうか。これはタイト過ぎると思うのですけれども、その辺はどうなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し検討する時間の余裕を持って通知をしてほしいという意見は述べてほしいと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"どういうものなのか、いきなり議会で２名出してくださいというのは、ちょっと変な話ですよね。頼むほうも頼むほうだけれども、受けるほうも、これを受けていいのですかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"令和５年第３回定例会","agenda":"令和５年第３回定例会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"何回か要望を出させていただいていて、議会費の予算要望にも出させていただいているのですが、３日目の民生費がかなり盛りだくさんなのです。何度か提案させていただいているのですけれども、ここでも検討していただきたいのですけれども、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"安藤委員","kind":"提案","question":"申し合わせ確認事項についても、少なくとも提案をしているわけですから、それをどこかで議論するという考え方はないのでしょうか。議会改革推進会議なのか、ここなのか分かりませんけれども、少なくとも正副委員長で、少しもんでいただきたいのですが、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"}]},{"id":"topic-03","title":"令和６年度予算（議会費）","agenda":"令和６年度予算（議会費）","exchanges":[{"speaker":"せりざわ委員","kind":"質問・要望","question":"そういったところを使って、電話を気兼ねなくできるようなスペースというのをつくれないかという思いで、要望させていただきました。以上４点、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりやすい資料、パンフレット等を作っていく費用ということで、予算を要望いたします。３つ目は、区議会だよりだけによらず、ＳＮＳ等を使ってということで行っていきたいということでの予算を要望したいということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"山本委員","kind":"質問・要望","question":"併せてお伝えさせていただきたいのですけれども、１つ目が政務活動費に関して、要望したいと考えています。もう一つが、委員会のウェブ中継を進めていくこととなると考えているのですが、それに対する検討の費用の予算化を要望できればと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"５は、予算を増やせばすぐに実行できることだと伺っていますし、ぜひお願いしたいと思います。ですので、予算を増やして対応してほしいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"これも国と同じように事前通告をして、そろそろインターネットで放映するようなことを品川区も考えていったらどうなのでしょうか。ＳＮＳもこれだけ普及している時期ですから、どんな質問をしているのだろうとか、そろそろ何か改革したほうがいいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-04","title":"その他の(1)議員研修会","agenda":"その他の(1)議員研修会","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"これも研修、これも研修で、でも、どちらかにしてほしいのです。１日１本ぐらいにしてほしいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5512#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":10816,"voices":44}},{"id":"r05-20230821-6","meetingId":"r05-cm08","date":"2023年8月21日","dateIso":"2023-08-21","committee":"区民委員会","time":"午後 １時００分～午後 ３時１２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"大井第三地域センター・区民集会所の移転","agenda":"大井第三地域センター・区民集会所の移転","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"一定期間公園は使えないのですけれども、その後、そういった検討とかもあったのでしょうかというところでお聞かせください。区民の皆さんや町会・自治会の皆さんからご意見、要望等をお聞きになっていらっしゃって、それを反映されているのかというところを説明するよう求めました。","respondent":"宮澤地域活動課長","answer":"そのままその場所で建て替えという検討もありましたけれども、今回、移転するところです。２つ目の質問で、２台分の駐車場と駐輪場のスペースの賃貸料を含めまして、月額３３９万８,３４０円の賃料となっております。","id":"exchange-001"},{"speaker":"西村委員長","kind":"提案","question":"移転に関しましては、今後議案として提案される見込みですので、その際の来る議案審査においてもご質疑いただくことができます。７月２４日の総務委員会におきまして、踏まえてご質疑ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問","question":"議案審査として質疑ができるということで理解いたしました。今、質問に対してお答えいただいたのは１つ目と、３つ目の質問にはお答えいただいていましたか。","respondent":"宮澤地域活動課長","answer":"地域からの声としましては、防災機能の強化だとか図書館という声がありました。その中で、防災備蓄倉庫ということで、防災機能の強化という意見を含めたところです。","id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ要望を取り入れていただきたいという思いがありますので、防災のところで取り入れていただいているというところで、よいなと思うところ。例えば、トイレの使いやすさとか、障害者の方にも使いやすいような実際の細部の設計とかもぜひ声を聞いて進めていただきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"確認","question":"今の質疑の中で確認なのですけれども、全体で月額３３９万円余と聞こえたのですが、この確認が一つ。どのように考えればいいのかということが、要するに、全体的に狭くなってしまうのではないですかということが一つ。","respondent":"宮澤地域活動課長","answer":"２階部分に共用トイレというのも新たに設置いたしました。庁内で確認したところ、大井町駅前にも公衆トイレとして設置されているところなのですが、それ以外では初めてと聞いているところです。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"どういう地域なのかというところで、先ほど月額３３９万８,０００円余ですか。今回、区有施設として、建物の中では初めて入れるということで先ほど確認をさせていただきました。","respondent":"宮澤地域活動課長","answer":"大井町駅前とか、そういったところと比べても、適切な金額と認識しているところです。１階にバリアフリートイレもある中で、２階部分に障害者の方の機能というのはない部分ではありますけれども、というのを設置すると。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"設計段階から品川区としては集会所として借りるからというような、契約までいかなくても、下準備があったのでしょうか。何でそこを伺うかというと、賃貸で入れようと思っていますというような報告は、たしかなかったような気がするのです。","respondent":"宮澤地域活動課長","answer":"２つ目で、跡地活用の部分なのですけれども、現在の大井第三地域センターにつきましては、企画部門含めて、今現在検討中と伺っています。町会・自治会支援もありますので、また、移転なのかという形で様々検討しているという状況です。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"１つ目の質問で、町会等を所管している区民委員会には、そういう計画があるという時点できちんと報告すべきだと私は思います。そこの設計段階で、区と交渉している段階でこの常任委員会で言うべきだと私は思うのですけれども、その辺についていかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"協議を重ねていく中で、今回、こういった形になったです。委員会報告すべきタイミングにつきましては、委員のご意見も踏まえて、今後、参考にさせていただきたいと思います。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"区民の皆様の税金を使って施策をしていくわけですから、その辺はしっかり区民委員会において報告をどんどんしていっていただきたいと思うのです。改めてその辺についていかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"先ほど答弁したとおり、このほかの地域センターの改築というのは、将来的にはまた出てくるところであります。地域センターの改築に関わらず、当然、議会報告というのはしっかりと時期を見てさせていただきたいと思います。","id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"幾つか確認なのですけれども、まず、建設のほうなのですが、建物自体の完成というのは１月頃なのでしょうか。最後に３点目、授乳室が２階にあるのですけれども、どういうイメージをされているのかというのを説明するよう求めました。","respondent":"宮澤地域活動課長","answer":"その後、まだ日にちは決まっていないのですが、２月に開所式をする予定という形です。隣に給湯室がありますので、そちらもご利用いただきつつです。","id":"exchange-010"},{"speaker":"せらく委員","kind":"質問・要望","question":"今回、防災機能の整備をするということで、２階に防災備蓄倉庫というふうに平面図で確認いたしました。その点について伺えればと思います。","respondent":"宮澤地域活動課長","answer":"１階にも集会室を設けたというところと、そういったところをいろいろ検討した上で、２階部分になったです。この中には、いわゆる毛布であったり、アルファ化米であったりといった備蓄品が格納される予定です。","id":"exchange-011"}]},{"id":"topic-02","title":"令和５年度地域振興基金を活用した区民活動助成制度の審査結果","agenda":"令和５年度地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"１つだけお伺いしたいと思います。今回、ヤングケアラーへの取り組みというテーマで応募をされたほかの団体というのはどれぐらいあったのか、教えてほしいと求めました。","respondent":"宮澤地域活動課長","answer":"その中でトライ助成につきまして申請をいただいたのは、今回選定された１団体のみでした。その中では、お話を聞きにいらした団体はあったところではありますが、申請については１団体になったです。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"確認","question":"お話も代表理事の方から伺ったことがありますし、そこで今回のこの2)のところで、一応確認のために聞かせてください。どういう説明があったのかということと、具体的にはどのような手法でこういう普及啓発を行っていくのかということを教えてほしいと求めました。","respondent":"宮澤地域活動課長","answer":"トライ助成、９月から事業を実施するということで申請をいただいております。子どもたちを前にヤングケアラーについて説明をして、いわゆる認識のない方を含めた掘り起こしということで普及啓発をしていくです。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"確認","question":"実績がある団体というのは理解をした上で質問しておりますが、応募に至ったのは１つの団体だけであって、トライ助成の金額が大きいのですよね。区民委員会という場ですから、一応、どういう趣旨で選ばれたのかということは確認をさせてほしいと求めました。","respondent":"宮澤地域活動課長","answer":"その中で９月からまず取っかかりとして始めるというところで、経費としてのボリューム感というのがこういう形でありました。申請に当たっては、かかる経費というところも当然申請にありますので、そこを審査した上で、適切と判断して採択されたです。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"確認","question":"この使途についてはまた確認があるとは思いますけれども、期間が短いというところで、少し質問をさせていただきました。先ほどの繰り返しでこれも３回目になりますが、非常に実績のある団体だというのは理解しておりますので、これで終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"えのした委員","kind":"意見","question":"やはり助成金、結構、今のトライ助成などというのは高額ですので、分かりやすく説明して、また来年以降に続くような報告会をしていただけるとありがたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]},{"id":"topic-03","title":"物価高騰等総合支援資金（事業）の延長","agenda":"物価高騰等総合支援資金（事業）の延長","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"４の実績ですが、申請してから実行されるまで１か月余りというお話があった中においても、半分近く実行されていないわけではないですか。そういう考えでいいのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"先ほどの審査期間は１か月程度というのが平均なのですけれども、早いものですと２週間ぐらいで、もう少し時間がかかるものもあります。７月末現在ということで１７６件、実行に至っているものが９５件ですけれども、かなりの確率で区内金融機関に使っていただけると考えています。","id":"exchange-017"},{"speaker":"藤原委員","kind":"確認","question":"もう１回確認するけれども、７月末で１７６件ということで、あっ旋する数というものもまた上がってくるわけですよね。この数字だけを見てしまうと、最終的には、あっ旋状を出したのと実行されるのは限りなく近いと思っていていいのですね。","respondent":"小林商業・ものづくり課長","answer":"ただいまの藤原委員のご指摘に近いというか、実際に、否決というのは確率的にかなり低いものでございまして、最終的にこれが年度末というか、最終的に集計の段階にいきますと、実行件数というのはあっ旋状況にかなり近くなってくるというご理解で結構だと思います。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"最後に１点だけ伺いたいのですけれども、中小企業、個人事業主の方にもあっ旋、そして、このように資金繰りが厳しいところに助成をしてあげますよね。信用保証協会を使うわけですから、お金をお渡しというか、所管課というのはそこをきちんと押さえておかないといけないわけですよね。","respondent":"小林商業・ものづくり課長","answer":"支援をしているところではありますけれども、雇用、やはり区内経済にとって大事なポイントだと考えています。そういう趣旨です。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"この予算を見ても、約２億６,０００万円を使うわけではないですか。この施策を、しっかり押さえてやっていってほしいと求めましたので、今後とも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"横山委員","kind":"質問","question":"質問なのですけれども、どういった形で小学校の意見を取り入れていくのかというところが気になりましたので、ご説明をほしいと求めました。そちらからお願いします。","respondent":"篠田文化観光課長","answer":"品川区と、それから水辺に近いということで港区のお子さんも含めて募集をして、２０人ぐらいのお子さんが集まったということがありました。１つは、小学校の場合は３年生で区内を勉強するはずなのですが、全体のプランニングをしています。","id":"exchange-021"},{"speaker":"横山委員","kind":"意見","question":"そういったところにもつながっていけるのかと思いましたが、今回実施をしていただいて、どういった形になっていくのか。そうしたことをヒアリングしていただいて、今後の展開につなげていただけたらと思うのですけれども、一言お願いいたしますとの意見を述べました。","respondent":"篠田文化観光課長","answer":"いわゆる授業の一環として実施をするのは初めてのことですので、観光協会も持っていますし、私どももぜひ後押しをしていきたいと考えています。来年度以降、どういった形で実施、来年度以降に活かしていけるような形で取りまとめをしていきたいと考えているところです。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"ですから、いろいろな方に伝えていくというような、期待を持って私も見守っていきたいと考えています。令和２年度・３年度、具体的にどのような感想であったりとか、評価をしていらっしゃるのかというのを教えていただけたらと思います。","respondent":"篠田文化観光課長","answer":"少しずつインバウンドの方も戻ってこられていますので、実際の体験という形で、また以前やっていたような形で実施をしています。今後も引き続きこの対応を続けていきまして、うまくすれば、そういった地の利も含めた展開を考えていければと考えているところです。","id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"ご答弁をお聞きしていて思い出したのが、様々、区と一緒に地域の方と詰めていっていただきたいと考えています。今後の展開と課題のところで、私、地域資源をテーマごとに束ねるというのはどういったイメージを区としてお持ちなのかというところを説明するよう求めました。","respondent":"篠田文化観光課長","answer":"少し表現として分かりにくい形になってしまって申し訳ございませんでした。一つ一つはそれほど有名ではなくても、まとまると一つの流れとして繋がってくるようなもの、そういったものを想定しています。","id":"exchange-024"},{"speaker":"横山委員","kind":"意見","question":"個別でＰＲをするのではなくて、集合体として集めてＰＲしていくという、そういった理解でよろしいのかと思いました。そうしたところ、そのテーマに基づいた束ね方というところを意識していただくといいのかと思いましたので、ぜひ進めていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"えのした委員","kind":"質問","question":"私たちも、どの方がＳＮＳを発信しているというのは、例えば、「＃品川区」とか、「＃わ！しながわ」とか、発信するときにはこのようにするようにといった、そういった指示みたいなものは出ているのか尋ねました。","respondent":"篠田文化観光課長","answer":"しながわ」でまとめるとかということは難しい状況があります。逆に言うと、国内では、品川区民に対してやっていますというのはなかなかお知らせしづらいような形になっているのは間違いないところです。","id":"exchange-026"},{"speaker":"えのした委員","kind":"質問","question":"私たちもどういった情報が発信されているのか気になったのですけれども、そのようなことで発信しているということで、ありがとうございました。品川区というのは大使館が１２か国、そういった交流はどうですかみたいな話があって、そういったことはこれからお考えか尋ねました。","respondent":"篠田文化観光課長","answer":"なかなか役所的には、大使館の対応というのは平和・国際担当がやっているものですから、実際のところは今のところはないという状況です。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"提案","question":"小学校５年生というところで、観光協会に品川区から予算を下ろして、観光協会の事業としてこれを学校側に提案するという考え方なのか。そこの辺り、今、品川区としてどうお考えになっているのか、教えてほしいと求めました。","respondent":"篠田文化観光課長","answer":"今年度実施する「しながわ」宝探しの旅、その中で実施をする事業ということで、事業自体は観光協会の事業という扱いになったものです。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"提案","question":"私も区議会議員として１４年目になりますけれども、かなり会派としても提案をさせていただいて、読み物としては非常に面白い。この２つをお伺いしますとの意見を述べました。","respondent":"篠田文化観光課長","answer":"対応件数が、令和３年度で対応件数６８件、それなりの効果が出てきているのではないかと感じているところです。今年度からは、これに加えて、例えば、ロケ弁のご案内などができないかとか、具体的なところも取り組んでいきたいと考えておるところです。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"提案","question":"横山委員なども、そこはぜひ着実に育てていっていただきたいというのが１つです。今まであるもの、船宿とか、そこのところをそういう観点でまたいろいろ提案をしていきたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"山本委員","kind":"質問","question":"１つ、ぜひそれぞれのところで、同じようなことができていったらいいと思っている次第です。例えば、そういう小学校の校長先生はどういう形でアプローチしていくと、どういったやり方がいいのかというのを教えてほしいと求めました。","respondent":"篠田文化観光課長","answer":"私どもも台場小学校に限らず、どういったところまで広げられるか分かりませんけれども、できるだけたくさんのお子様方にも見ていただきたいと。","id":"exchange-031"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。ぜひ多くの小学校の皆さんに拡げてもらえるように前向きにご検討いただきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問","question":"私が質問した後の議論を踏まえましてお尋ねしたいと思うのですけれども、大体どのくらいの年代の方に向けて発信をしているようなイメージなのか、教えていただけたらと思います。","respondent":"篠田文化観光課長","answer":"インフルエンサーの方は、大体２０代の後半から３０代にかけての方、比較的若い方が多くいらっしゃいます。見られる方も、それぞれ多少別々になってしまいますので、それぞれの方に合った視聴者層の方にアプローチをしているのだろうと考えているところです。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問","question":"芝浦工業大学の原田曜平教授のお話を伺ってきたのですけれども、１０代後半から２０代前半ぐらいの方、六歳ぐらいまででしょうか。ですから、その辺り、ご意見を伺えたらと思います。","respondent":"篠田文化観光課長","answer":"インフルエンサーの方には、これからも引き続き様々な活動をお願いしていくことになると思います。例えば、どちらかに偏るということではなくて、幅広く情報が広まるような形で取り組んでいければと考えているところです。","id":"exchange-034"},{"speaker":"西村委員長","kind":"質問","question":"では、私から１点だけお伺いできればと思います。区民ガイドのような、そういう方たちの育成とか、区民を巻き込んでいくような広がりというのは何かあるのかというのを１点伺ってよろしいか尋ねました。","respondent":"篠田文化観光課長","answer":"実際に、今も区内では旧東海道を中心に、ボランティアで様々な形で区の紹介をしていただいている方々もいらっしゃいます。内陸のほう、そういった方々にも働きかけを進めて、ぜひ観光の分野でもお力添えいただければという形で進めていければいいなと思っているところです。","id":"exchange-035"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"ホッケータウン公式認定プログラムというのは、趣旨は分かったのですけれども、これに応募する条件とか、現状、このホッケータウンに公式認定されている都市が幾つぐらいあるのか、ちなみにそこはどこなのか、参考のために教えてほしいと求めました。","respondent":"三井スポーツ推進課長","answer":"すみません、調べ切れていないのですが、調べが終わりましたら個別にご説明するという形でよろしいでしょうか。認定条件としては、ホッケーを通じた地域活性化を行っている、あるいは目指している区市町村ということになっております。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"まだ特に１件も、本当にそういう意味では、まだそんなに認定されていないということでの認識で今はいたいと思います。品川区としては、ホッケータウンになることについてどのようにお考えになっているのか、念のため確認をさせてほしいと求めました。","respondent":"三井スポーツ推進課長","answer":"今後レガシーとして地域のにぎわいづくりに活用していくという考え方を、今、ホッケータウンとして申請をしていきたいと考えています。地域のにぎわいづくりを通して、スポーツを支える人口を増やすなど、そういうことについてつながりを持たせていければと考えています。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2966#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":43576,"voices":116}},{"id":"r05-20230821-7","meetingId":"r05-cm08","date":"2023年8月21日","dateIso":"2023-08-21","committee":"厚生委員会","time":"午後 １時００分～午後 ４時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"こんの委員","kind":"意見","question":"前例のとおり、報告の前にお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"令和５年度高齢者福祉行事","agenda":"令和５年度高齢者福祉行事","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"今回コロナが５類になったということで、その中で特に、熱中症の対策がどのように取られているのかということを１つお聞きしたいと思います。そういう熱中症に対しての啓発というところもぜひ入れていただきたいなと思ったのですけれども、その点についても伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"イベントの実施者、運営者である認知症サポーターが中心にはなるのですけれども、区のほうも声かけを実施していきたいと考えています。こまめに飲物を飲んでいただくこと、あと帽子等かぶって実施していただくことは、事前に競技を参加される方に説明をしていくような形です。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"どのようにされているのかというところをちょっと伺いたい、特にこのようなイベントを通してやっていただきたいということに対しても、どう考えられているのかについても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"在宅介護支援センターや、あとは７月の地区民協のときに、お配りするなど見守りをしてくださいということを呼びかけております。例えばチラシを少しお配りするなど工夫をして、少しでも高齢者の熱中症が予防できるように、心がけていきたいと思っているところです。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"まだまだ知識として持てていないという思いがしているのです。そのようなことも含めて、熱中症の高齢者に対しての知識の普及と啓発というようなところを、ぜひとも進めていただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問・要望","question":"贈呈事業の中から２つお伺いしたいと思います。そうしたところも含めてなので、施設でのお祝いと、町会・自治会等でのこの１万円という予算、これの考え方について伺いたいと思います。","respondent":"東野福祉計画課長","answer":"お祝いというところで１つの町会・自治会にお配りするというようなこと、恐らくそれ以上、今のところ考えていることはないかなと推測されます。区の事業ではないので、まず推測というところの意見になります。","id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"区としての事業等になっていないというところはなぜなのかというところを確認させてください。元気高齢者、区としてもそうした高齢者のお祝いというところの事業があってもいいのかなと考えるところですけれども、いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"１００歳の方、または長寿の方に対してのお祝い品をお配りするということは、区のほうで行っているところです。改めて町会に対してというような事業ということは考えていないのですけれども、実態を踏まえて今後研究してまいりたいと思います。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"できるだけ多くの方に参加していただきたい。集いを７０歳からとか、町会によっては７５歳からとか、いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"社会福祉協議会とも、その辺につきましては連携を取って、どのようなことができるのか、また地域活動課などでも、たくさん行事のほうの支援をしておりますので、その辺とのバランスを持って、考えていきたいと思います。","id":"exchange-007"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、この町会・自治会敬老祝金についてですが、よく町会で７５歳以上の方にお祝い品などをお届けしているということがあるのですけれども、それはあくまで町会の団体としての行事であって、それとはこれは別という理解でよろしいのか尋ねました。","respondent":"東野福祉計画課長","answer":"恐らく町会の中での決まり事として、そのようなものに取り組んでいらっしゃる町会がいらっしゃると思われます。それから社会福祉協議会として贈呈するものということになりますので、町会が独自にやっているものとはまた別のものという理解でお願いします。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"それで、今回のこの社会福祉協議会のやる祝金というものは、その贈呈の要件としては、敬老会を開催するということは前提ということになりますよね。一律１万円というのは在り方としてどうなのかと思っているのですが、その辺り、どのように区としてはお考えなのか尋ねました。","respondent":"東野福祉計画課長","answer":"今年度につきましては、区内のほとんど全部の町会・自治会のほうで敬老会事業を行うというように聞いてあります。それから、この１万円だけでは心もとないのではないかという部分につきましては、決まりを持ってやっていると伺っております。","id":"exchange-009"}]},{"id":"topic-03","title":"（仮称）小山七丁目障害者グループホームの整備・運営事業者の選定","agenda":"（仮称）小山七丁目障害者グループホームの整備・運営事業者の選定","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"幾つか質問させてください。これは具体的にどのようなところがよかったのかということを６行以外であれば教えていただきたいということと、その２点について説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"夜間帯などにおける緊急事態の対応などのために、関係機関との連携および支援体制の確保ができるということが期待できます。今後の、あと評価について、提示という部分になりますけれども、今後区としても検討して、公表することも含めて検討してまいります。","id":"exchange-010"},{"speaker":"ひがし委員","kind":"質問・要望","question":"精神疾患のみならず、もし障害、そのほかのものが出たときに対応できる事業所を選んだということで理解をいたしました。ぜひ決めた理由というところを示していただけるように要望をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問","question":"ちょっと基本的なところを伺いたいのですけれども、なぜ３０年で廃止して更地で返すようにという、まずそこのところを説明するよう求めました。","respondent":"川崎障害者施策推進課長","answer":"３０年後を見据えたところになりますが、こちら民設になりますので、基本的には運営事業者が、今後のことを見据えて計画していくことになります。ただ、区としましても、３０年後に向けた用地確保の見通しを定期的に運営事業者に確認やヒアリングはしてまいります。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問","question":"ここは３０年たったら、その方の安定のためには、そのようなことにしないとできないということになっていくのでしょうか。グループホームをそのまま改めて延期して継続するというようなことはできないという仕組みになっているのか、その点も説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"それで、３０年後ですけれども、区の土地ということではあります。地域活性化や防災機能といった、そのときの地域のニーズを踏まえまして、今後の計画をしていくことになるかと考えております。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問","question":"なぜ今回これを区立にして、６月議会のところで報告があった、そのような手法にしたと思うのです。何というのですか、無償貸付で３０年後には廃止する、そこのところの理由も説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"重度の方の対象のグループホームというものも、２３区では民間の社会福祉法人でも運営しているという実績があります。品川区としましても、民間事業者でも運営可能なものは民間参入を促していくという方針であります。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"同じ時期の出石つばさの家のほうが、ではなぜ指定管理者にして、こちらは民設民営ということにしたのか、そこの違いというものは何なのか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"出石つばさの家は、地域生活支援拠点の機能の充実を図るという名目です。今後、区の地域生活支援拠点の障害者グループホームの運営法人とも連携していく上では、指定管理として今回指定をさせていただきました。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、出石のほうは拠点という位置づけが必要だったので区立にしたけれども、今後はそのような形ではなく、民設民営という方針でいくという、区の方針そのものがそうだというようなことで捉えていいのか、ちょっとその点も確認したいと求めました。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"意見","question":"そうすると、建設費を減価償却していくという、そのような考え方になっていくのか。今差があると思うのですけれども、そのような点では、区立と同じ家賃で利用できるようになるのかとの意見を述べました。","respondent":"川崎障害者施策推進課長","answer":"家賃につきましては、区と民間ではやはり差はあります。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"提案","question":"そのような方針にぜひともやるべきだと思うし、このようなやり方を進めていくということになるのか、その点の考え方についても伺います。提出書類の中で多分提案されていると思うのですけれども、その辺はどうなっているのか、その点についても伺いますとの意見を述べました。","respondent":"川崎障害者施策推進課長","answer":"今回の収支計画についてですが、本施設の運営収支計画としては、おおむねほかの施設と遜色ない水準で提案をされてあります。基本報酬以外にも、加算分や活用可能な補助金を全て盛り込まれて、緻密に計算がされているというところです。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"提案","question":"同じ、何というのですか、そのような提案になっているということなのでしょうか。そのようなグループホームと同じ条件で運営ができるのか、そういう提案になっているのか、その辺はどうなっているのか伺いますとの意見を述べました。","respondent":"川崎障害者施策推進課長","answer":"中重度の方を受け入れるという想定にはなっておりますので、今げんきが運営しているグループホームと、また違うものではあります。今、そういった実績を踏まえて、今回民設民営でこちらを運営していくことで手を挙げていただきました。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"提案","question":"質問に答えられていないのですけれども、同じ待遇というのですか、そのような提案になっているのかどうかということなのです。毎年毎年指定管理者では数百万円ずつ出しているというようなことも全くない中で、そのようなことができるのですかということなのですとの意見を述べました。","respondent":"川崎障害者施策推進課長","answer":"本案件は事業者公募により実施することから、障害者グループホームの運営収支を見ましても、やはり全般的に厳しいところというものはあります。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"そのげんきの条件で、今回の民設民営でげんきが行うグループホームも同じ条件で障害者の方々に提供できますよというようなことでいいのですかという。そこのところどうなっているのですかと伺っているのですけれども。","respondent":"松山障害者支援課長","answer":"障害者施策推進課長が説明しましたように、同様の金額でということは、区としてはお願いしたいところです。品川区民の方が、本当に不利益を受けないような形の家賃設定を、げんきと、事業者と協議しながらつくっていきたいと考えております。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなことなので、区立で指定管理者というようなことで進めていただきたいということは、強く要望をしておきたいと思います。何というのですか、建設費としてげんきが出さなければならないお金というものはどれぐらいになるのか、ちょっとその点を伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"東京との補助金が７,９００万円ほど、そして品川区のグループホームの整備費補助が２ユニットで５,０００万円となっています。品川区の開設準備経費助成補助金というものもありますので、そういった補助金を活用しながら資金計画書を立てているということになります。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"公募の実施要領の２ページのところなのですけれども、そのような施設として整えられるのか、その点を伺いたいと思います。職員の体制というものも、職員体制としては何人で、どのような資格の方が何人になるのかというところもお聞かせほしいと求めました。","respondent":"川崎障害者施策推進課長","answer":"高齢化・重度化に対応した障害者グループホームになりますので、重度化に対応した障害者グループホームとして設備は整う予定です。世話人兼生活支援員が常勤１人、生活支援員が常勤１人、女性１名という提案をいただいております。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"この重度というものは、どの程度までの重度の方を受け入れられるということになっていくのか。何というのですか、そのようなところも整えられていくのか、その点についても伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"もう１点、すみません。もう１回質問いいですか。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問","question":"この建設予定の建物というものは何階建ての予定でいらっしゃいますか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"２階建てです。","id":"exchange-025"},{"speaker":"やなぎさわ委員","kind":"確認","question":"先ほどの鈴木委員とのお話で純粋に思ったことが、やはり貸付期間３０年で更地にして返す。区のルールとして貸付期間を３０年までと決まっていて、確認なのですが、それでよろしいか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。","id":"exchange-026"},{"speaker":"やなぎさわ委員","kind":"質問","question":"例えば３０年たって、なぜ壊してしまうのだろうねという、その点はいかがか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"現在、区の公有財産管理規則では３０年と書いてはおりますが、協議により更新もできるですので、そのときの社会情勢を踏まえて、そのときの方針というものは考えてまいりたいと思います。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"質問","question":"協議により更新ということでお伺いして、非常にそれはいいことだなと思うので、それに関しては、何かこう取決めといいますか、例えば３０年たつ、何年ぐらい前からこのような話合いがスタートするとか、具体的なことというものはどのような取決めになっていますか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"取決めに関してですが、区として総合的に判断ということになりますので、今ここで何年前からということをお示しすることはできません。ただ、その都度、その都度の地域のニーズというものがありますので、そういったものを反映しながら決定していくことになるかと思います。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、一応ルールとして３０年になっているけれども、例外的事例も考えられるというような受け止めでよろしいか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"協議により更新できるということで進めていくことになります。","id":"exchange-029"},{"speaker":"筒井委員","kind":"確認","question":"確認として、民設民営というものは、これいわゆるＰＦＩ、プライベート・ファイナンス・イニシアチブの方式ということでよろしいのか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"ＰＦＩではございません。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"運営はげんきがやられるということで、区の関与としては最初の土地の提供をしたというだけといいますか、そういった理解でよろしいのか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"区としては、もちろん土地の貸付けを行っておりますので、今後も区が関与しないというわけではございません。もちろん定期的にヒアリング等はさせていただきながら、その都度お話合いを進めていくということになります。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"現状、その民設民営の運営形態を取っている品川区の福祉施設は、大体どのくらいなのでしょうか。障害者に限らずなのですけれども、お分かりになればお願いします。","respondent":"川崎障害者施策推進課長","answer":"今、区立として障害者グループホームは４つあるのですが、それ以外は民間ということになります。箇所数としては、今２２か所グループホームあるうちの４か所が区立、それ以外は民間ということになります。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"今後区としては、その方針として、方向性として、民設民営というものを増やしていくというようなお考えなのか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。民間活力を使って、民間整備による障害者グループホームを促進していくと考えております。","id":"exchange-033"},{"speaker":"鈴木委員","kind":"質問","question":"この小山七丁目のグループホームについては、ちょっとここのところから伺いたいのですが、隣接するところに小山の家と小山倶楽部があります。そのようなところでは、声はかけられたのか、あとかけられたところはどのようなところにかけられたのか、その点もちょっと伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"公募開始前の事前の周知です。実際説明会には５社の法人に参加いただきましたが、結果的に応募が１社という形になりました。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私はもっと報酬などを国のほうが引き上げるというようなことが求められるのではないかなと思うのですけれども、その辺のところも伺いたいと思います。適切な運営がされているか、民設民営への指導検査というものはどのような形で行われるのか、そのことについても伺います。","respondent":"川崎障害者施策推進課長","answer":"応募参加辞退された方の事業者の回答によりますと、重度の方に対応できる対応技術を持った職員の確保が困難であるためという回答もございました。今後都と区に指導検査の権限がありますので、適切な運営がなされているかということは適時指導していくことになります。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問","question":"何というのですか、そこの仕組みについて伺いたいということなので、お願いしたいと思います。つなげて伺いたいことが、区の土地を無償で貸し付けているので、このようなルートに乗せますよということなのか尋ねました。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"指導検査は大体３年に一度の頻度で行ってまいります。ただ、何か事故等ございましたら、それはこちらのほうでも権限として、適切な運営がなされているかということは適宜指導しております。 私からは入居者選定についてお答え申し上げます。そういったようなところにつきましては、区が関与、何かしらの形で区が関与するということになります。","id":"exchange-036"},{"speaker":"鈴木委員","kind":"質問","question":"もちろん区立はそうなのですけれども、そのようなところは区が一緒になって誰を入れるかということは関与していくという、そういう捉え方でいいのか尋ねました。","respondent":"松山障害者支援課長","answer":"委員がおっしゃられるとおりです。最終的には、ただし事業者と区民との契約というものは、今の制度上はそのようになっておりますが、何かしらの形で区の関与というものが必ずあります。","id":"exchange-037"},{"speaker":"鈴木委員","kind":"提案","question":"具体的にどのようなことが提案されているのかということと、一人ひとりの部屋の面積というものは何m2になるのかも伺いたいと思います。離職率の集計表なども書かれているのですけれども、この離職率というものがどの程度になっているのか、その点も説明を求めました。","respondent":"川崎障害者施策推進課長","answer":"例えば重度化・高齢化に伴う医療行為の開始とか、どのように対応していくかということを利用者自身も含めて確認していきたいという提案はありました。こちら令和３年度における離職率になりますが、１３.５％でしたので、安定的な運用をしていると言えます。","id":"exchange-038"},{"speaker":"鈴木委員","kind":"質問","question":"部屋の面積は７.４３m2よりも上回るということなのですけれども、具体的にどれぐらいかということは、分かったら教えていただけると。","respondent":"川崎障害者施策推進課長","answer":"今回身体障害の方も含みますので、例えば車椅子をご利用されている方も、居室として無理なく安定した生活を送れるような、ゆとりのある面積ということで提案をされております。","id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問・要望","question":"分かりました。いろいろ伺いましたけれども、指定管理者であっても民間が運営するということになるわけですから、改めて要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"やなぎさわ委員","kind":"提案","question":"民間の活力で民設民営という流れが進んでいることに対してのご提案ありましたけれども、説明に来られた５社の中で、改めてそのような受け止めでよろしいか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"重度化に対応できる技術を持つ職員確保は困難であるためという意見もございました。そのほかのご意見もございました。","id":"exchange-041"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そのほかの意見というと、ほかには何がございましたか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"１０人の、２ユニットを建てて本当にぎりぎりの面積ですので、実際２ユニットの設置が厳しいのではというご意見もありました。傾斜地になっておりますので、傾斜部分を平らにするという負担も含めると、工程も含めると難しいという意見もございました。","id":"exchange-042"},{"speaker":"やなぎさわ委員","kind":"質問","question":"となると、重度介護の対応困難というものは、あくまで少数意見というところか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"今回の説明会にいらした５社の中で、そのご意見をいただいたのは１社です。","id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"提案","question":"４００社の中で、意見で、もしかしたら応募しなかったところもあるかもしれないと思うのです。強みになるということをぜひ考えていきたいと思いましたという提案と、合わせると１億２,９００万円、そのような受け止めでよろしいか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"質問","question":"もう一度その内訳、大体でいいので教えていただいてよろしいか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"都の補助金が７,９００万円ほど、品川区の整備費補助が５,０００万円です。それから開設に関わる補助金として、東京都のほうで５０万円ほど、そして品川区のほうの開設準備で１５万円ほど、そのほか借入金などもあります。","id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"それで、お伺いする限り１億３,０００万円ぐらいは補助が出ますと。先ほど２階建ての施設というようにお伺いしたので、７５０m2とか、それぐらいだと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問","question":"それから、この土地は区が取得しているわけですけれども、幾らで取得したのか、この額も教えてください。それからこれ、この土地所有者というものはもともと個人の方から売却意向があったのか、ちょっとそのところも教えていただけたらと思います。","respondent":"川崎障害者施策推進課長","answer":"現在計画を予定している隣の用地が小山在宅介護支援センター、小山の家がありまして、小山の家と連携して町会と調整いただくようお話はしております。公共用としての活用に限定した土地の売却意向がありましたので、区としては取得したいという要望を伝えた、そのような経緯です。","id":"exchange-047"}]},{"id":"topic-04","title":"品川区介護予防・日常生活圏域ニーズ調査の結果報告","agenda":"品川区介護予防・日常生活圏域ニーズ調査の結果報告","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"１点だけお願いします。この４３名の方というものは、1)番、認定時期等により含まれているという方の４３人と認識してもよろしいのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"この２ページで記載されています要支援（ｎ＝４３）というものが要支援１・２の方、ｎ＝３となってちょっと人数が少ないのですけれども、その方の数字となっております。","id":"exchange-048"},{"speaker":"おぎの委員","kind":"意見","question":"目的や、あと経費の面でも、非常にまとめていろいろなことが調査できるのでいいと思いました。こういった結果をその策定だけにとどまらず、関係する所管課などでも絶対共有して、いい方向に進めていけたらなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"実施していただきたい調査というところで、どのような地域課題があるということで把握されたのか、その点を説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"こちらの概要版を見ていただきますと、１３圏域に沿った答えをクロス集計しています。今後、こちらが６５歳から７４歳までということで、こちら７５歳以上は高齢者地域支援課実施の介護予防把握事業でも同じように。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問","question":"では、今のところは、その地域課題の把握というところが明確にはなっていないので、７５歳以上のそのようなものと併せて、これから地域課題がどのようなものがあるのかということを明らかにして第九期に反映をさせていくという、そのようなスタンスということでいいのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"委員おっしゃるとおりです。","id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"国のほうとして同様に実施していただきたいということで出されているのですけれども、区としてはどのようにされるのか、ちょっと伺いたいと思います。検討していただきたいというものは区で検討して、ぜひ国としては実施していただきたいという、区としてはどうされるのか伺います。","respondent":"菅野高齢者福祉課長","answer":"要支援、要介護者の在宅生活の継続などについて、利用実態等を分析するというような調査となっております。実際に要介護認定を受けている方、約２,０００人に対しまして、毎年モニタリングアンケートというものを実施しています。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２,０００人に対して、ではそれがどのような形ではまとめられているというものはあるのでしょうか。何というのですか、１０万人を超えたというような大問題になって、これが社会問題になっていると思うのです。","respondent":"菅野高齢者福祉課長","answer":"そのときに、モニタリングアンケートのほうを実施させていただきまして、介護サービスの実態と満足度等についてお話を伺って集計しています。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことはぜひ進めてほしいと求めましたけれども、本当に様々、区内に私はあふれているのではないかなと思うのです。まとめもしていただきたいし、そのようなところにも向けても、ぜひご報告をしていただきたいということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ご質問です。２１ページの「なるべく家族や周りに迷惑をかけずに暮らしたいか」という質問があるのですが、意図があれば教えていただきたいのですけれども。","respondent":"菅野高齢者福祉課長","answer":"そういったご本人の意思的な確認のものをここでお聞きできたらなということで、ここは質問の中に加えさせていただいた次第です。やはり９３.９％の方がそう思うというところで、健康維持などについての気持ちにつながっていくのかなというところで捉えているところです。","id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これからの取組というものはこれからということでお伺いしているので、ぜひお願いしたいところで、１位は趣味の活動と。ですから、その辺はぜひ注目していただきたいというか、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"ひがし委員","kind":"質問・要望","question":"皆さんが回答しやすい設問の数にするとか、有意義な質問というところを選択して選ぶ必要もあるのかなという点、それは要望としてお伝えしておきます。男性は９１.８％で、女性は８６.７％ということで、ここのギャップについてはどのように考えていらっしゃるか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"品川区が実施している健康づくり・生きがいづくり事業ということで、高齢者地域支援課などがやっているパソコン教室や、カラオケ広場。","id":"exchange-057"},{"speaker":"ひがし委員","kind":"意見","question":"区役所としても、発信というところはやはりもっともっと品川区、やっていくべきなのかなと思いました。ぜひ一緒に頑張っていければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"こんの委員","kind":"確認","question":"９問から１１問までが区の独自の設問だということですけれども、１１番のＩＣＴ、この３点に絞ったのはどういったところからなのか。質問の設問にしたのか、その辺の設問の設定の仕方というか、考え方をまず確認したいと求めました。","respondent":"菅野高齢者福祉課長","answer":"問９以降が区のほうで独自にというところで、前回の第八期のときには、ちょうど成年後見制度が始まりましたので、その質問についてを質問しています。区の施策として進めていくに当たって、ここについて少し触れさせていただこうかなというところで取り入れさせていただきました。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問","question":"その狙いでこの３点が今回ニーズ調査をされたということで、あまり設問が多くなるとというところもあって、絞ってこの３点にしたと。ほかにニーズ調査が必要だと、課題だと思っている点があれば、その点説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"前回に引き続き対応させていただいたというところと、そこについても前回と比較して比べてみたいというところで、質問のほうには加えしています。今後、皆さんのご意見等を聞きながら、次回の調査等には反映させていきたいなと思っているところです。","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問","question":"絞って３点も非常に大事なのですけれども、お考えにはなっていたけれども、やはり３点だったのか。そのようなものがあれば、その辺教えていただければと思うのですが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"いろいろな課題を抱えている方、まだ介護に結び着いていない方は、地域にたくさんいらっしゃるのかなというところは認識しているところです。","id":"exchange-061"},{"speaker":"こんの委員","kind":"質問","question":"ですから、孤独死対策もそうですし、お独り暮らしの方の見守り、それから生活支援、こうしたところが、やはりお独り暮らしの方も増えています。ヤングケアラーという問題もありますし、そうした観点からのニーズ調査というところも必要だろうと考えますけれども、重ねていかがか尋ねました。","respondent":"菅野高齢者福祉課長、東野福祉計画課長","answer":"やはり回答としましては配偶者が１番で、あとは友人、あと兄弟姉妹などとなっております。区としてはある程度つかんでおりますので、そういったところを参考にしながら、介護保険事業計画に活かしていきたいと考えているところです。今、委員のほうからお話がありました孤独死の関係ですとか、それからあと重層的支援体制整備の関係につきましては、区としても取組をしています。","id":"exchange-062"},{"speaker":"こんの委員","kind":"質問","question":"この、近所の人だったりした人が動ける権限というのでしょうか、そのようなところの把握も今後されるといいのではないかなと思うところです。業務の中でも拾い集めていっていただければなとは思いますけれども、最後、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"いろいろとご意見ありがとうあります。やはりそういった地域の、様々な手法を考えながら、少しでもつながっていけるようなものが盛り込めるように努めていきたいと思います。","id":"exchange-063"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ですから、あともう１点、すみません。８ページのところで、これ、仕事をしている理由というものを深掘りして聞いたりしているような設問というものはありますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"こちらが問５になりますので、国の指定の質問の仕方というようになっております。週２～３回週１、月１～３回、この設問の仕方でしか聞いていないという実態です。","id":"exchange-064"},{"speaker":"やなぎさわ委員","kind":"質問","question":"７０歳から７４歳の方が週１回以上が約３３％、６５歳から６９歳で約４９％ということで、かなり高いなと思いました。ですから、働かざるを得ないというような状況もあるのかなということで、ちょっとお伺いさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"筒井委員","kind":"確認","question":"ちょっと聞き漏らしていたかもしれないのですけれども、確認で、このアンケートを６５歳から７４歳までにした理由というものは何でしょうか。その７５歳以上の方の把握というものはやられないのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"７５歳以上の方につきましては、高齢者地域支援課実施で、介護予防把握事業というものを毎年行っております。１万８,０００人に対して、今回のニーズ調査においては７４歳以下という形で、７５歳以上の方は省略させていただいた次第です。","id":"exchange-066"},{"speaker":"筒井委員","kind":"質問","question":"その前の委員の方からもご質問出ていましたけれども、助け合いについてなどのご質問あったのですけれども、これは実現をされているのか。今現状どうお考えなのか、第九期にどのように反映されていくのか、区のお考えをお聞きしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"例えば１は、今回重点を置かせていただいておりますプロジェクト２では、プロジェクトの検証のほうもしています。そういったものをさらに進めるようにというような指針も出しておりますので、プロジェクトのほう推進させていきたいと思っているところです。","id":"exchange-067"},{"speaker":"筒井委員","kind":"質問・要望","question":"行政とのつながりをどうするのかという大変難しい課題かと思うのですけれども、ぜひブラッシュアップして進めていってほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"鈴木委員","kind":"質問・要望","question":"しかもそれも３か月とか、３か月だけはいなければはいけないとか、今の介護の現場にあると思うのです。これは厚労省で検討いただきたい調査ということなので、この問題に対してはどう捉えられているのか、その点についても伺います。","respondent":"菅野高齢者福祉課長","answer":"は区内法人の方のヒアリング等も行いながら、参入促進や離職防止、具体的に各法人で今取り組んでもらっているところです。なかなか限界もありますので、それ以外のところで、共に課題を共有して解決を考えていきたいと思っているところです。","id":"exchange-069"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ、実態把握というところでは、具体的なところでつかんでほしいと求めました。やはり改善をさせていくという具体的なところが求められていると思いますので、つながるような方向で、第九期に向けて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]},{"id":"topic-05","title":"品川区立平塚高齢者多世代交流支援施設（平塚ゆうゆうプラザ）指定管理者候補者の選定","agenda":"品川区立平塚高齢者多世代交流支援施設（平塚ゆうゆうプラザ）指定管理者候補者の選定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"これまで福栄会が５年間やってきて、基本的に福栄会でということで審査をするということになっていくということですよね。９月に選定委員会および予備委員会、選定委員会をやるということになっているので、そのメンバーについて教えてほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"予備委員会に関しましては、庁内の関係管理職員５名で予定をしています。および有識者委員として外部より２名、１名が行政の経験者、１名が学識の経験者をお呼びする予定です。","id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問・要望","question":"有識者の外部からの２名というものも、もう決まっていると思いますので、その点についても教えてほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"今、こちらの委員会の報告につきましては、あくまでもこれから実施をする予定ということで申し上げる形です。具体的な人員の内容につきましては、次回の報告の際に決定という形でご報告を申し上げたいと考えています。","id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問","question":"もう決まっていることなので、報告いただいてもいいのかなという思いがしています。何というのですか、解決すべき課題など、どのようなものなのかということも説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"ご質問いただきました、現指定管理者が実施する上での、運営上の課題についてあればということのご質問です。私どもの課で認識をしていますのは、これまで約２年から３年間、コロナで地域に向けた事業が実施できない形でおりました。","id":"exchange-073"},{"speaker":"鈴木委員","kind":"提案","question":"多分提案だったり、これからこうしていきますよという計画というものは出されるわけですよね、書類としても。できるだけそういうところも分かる形で、ぜひこの委員会にしっかりと報告をしていただきたいということでお願いをしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"ひがし委員","kind":"質問","question":"この施設の設置目的や事業内容などに特別な理由がある場合は、公募によらず特定の事業者を選定することができるものとするとあるのですが、この特別な理由というものは何か教えていただけますか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"２階が在宅子育て支援事業がメインのオアシスルーム、子どもの広場の事業も実施している観点で、判断基準の１つとなっています。高齢者に関しても、様々な介護予防事業もこの施設で実施していただく中で、継続して見ていただける施設の面を持っていただけるというところも。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問","question":"１つは、この意味合いのものは何を想定をされているというところなのかを１つと、あとは次の管理に関わる経費の縮減を図るものと。その辺のところは、これはどのようなことを、縮減を狙っていることなのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"それは施設長の協力によって、声を引き続き読み取っていただける、さらなるそこの向上を目指していただきたいという部分が１点としています。","id":"exchange-076"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひその辺のサービス向上というところも今後期待をし、その辺のお話もよく引き出していただきたいなと思います。その辺の運営の仕方についてのことも、しっかり聞き取っていただきたいというか、といったところをお願いして、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"}]},{"id":"topic-06","title":"新型コロナウイルスワクチン令和５年秋開始接種","agenda":"新型コロナウイルスワクチン令和５年秋開始接種","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"新たなＸＢＢなどというワクチンですか、９月１１日以降という形でいいのか、確認です。お願いできますか尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"次に２番の接種券についても、接種された方と接種されない方の認識ですが、委員のお見込みどおりの対応となっております。４番目の区の集団接種会場の実施見込みですが、今年の５月の金曜日、日程を調整しております。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問・要望","question":"届く方と届かない方の認識の差というところは、もう少し工夫をされたほうがいいのではないかなと考えるところですけれども、いかがでしょうか。同時接種というところを１つ伺いたいのですけれども、今、そちらをしたいという方との同時接種というものはどうなのか尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"特に接種の勧奨がある方たちに関しての、何らかの周知方法というものも、接種状況を見ながら検討を進めてまいりたいと考えています。国のほうからは、インフルエンザとの同時接種は可能であるとの見込みが示されておりますけれども、ただ。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問・要望","question":"接種券、すみません、しつこくて恐縮なのですが、要は接種券のない方は接種券を求める、それをしなければ、作業をしなければいけないわけですね。９月の上旬、ウェブ上でもその辺のところもきちんとうたっておいていただきたいなと思うのですけれども、いかがか尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"１点目、あと今回接種勧奨がある６５歳以上の方等に向けて、何らかできないかということは検討を進めていきたいなとは思っております。次に同時接種ですが、現在は、まだ厚生科学審議会のほうで、薬事承認も踏まえての審議が発足をする予定です。","id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですから、こうしたことも打っておいていただきたいという、その辺の対応をよろしくお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"ひがし委員","kind":"質問","question":"ワクチンを接種してほしいということは区からも発信していくとは思うのですけれども、打つと何か副作用が、そこについてのお考えを教えてください。もう１点、そのような現状についての担当課での把握というものはあるのかということも、併せて説明を求めました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"以下、ご質問ありました接種券等の問題も含めまして、希望される方が接種をしていただけるような体制を組んでまいりたいと考えています。ワクチンに関しましては様々なお考えの方がいることを鑑みまして、正確な情報を周知していけるように体制を組んでいきたいと考えています。","id":"exchange-082"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ただ明記するだけではなくて、その実態も載せていくべきかなと思いますので、その点については要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"おぎの委員","kind":"質問・要望","question":"こちら質問というより要望なのですが、人によってはかなり壮絶な内容で、非常に生活も困難になってしまっている方もいらっしゃいます。ですから、やはり双方でやっていかなければいけないと思いますので、そういった方への対応も。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"接種の際にも、副反応や安全性等を説明していくよう、医療機関のほうにはお伝えしていきたいと思います。予防接種救済制度、調査委員会のほうで内容を審議いたしまして、速やかに東京都および国のほうへ提出をしていきたいと考えております。","id":"exchange-084"},{"speaker":"筒井委員","kind":"質問","question":"ＢＡ２.８６が、この今までのＸＢＢ.１.５しか通用しないワクチンはやはりやめたとか、そういったことにはなるのでしょうか。そうした既存のワクチンが効かなくなった場合の対応というものは、どのようになるか尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"ただ今後、例えばＢＧ株ですとか、そういったものが出ているというふうにも聞いております。今回の秋開始接種におきましては、ＸＢＢ.１.５対応のワクチンを使うということが示されておりますが、現状は未定です。","id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問","question":"そのような点で、高齢者施設に入所されている高齢者の方や、在宅でこのような医療機関まで行けない方のワクチンの接種の体制というものはどうなっているのかお伺いしたいと思います。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"障害者等も、入所施設の方向けに巡回接種を実施しておりまして、こちら秋開始接種におきましても継続をしていきたいと考えています。施設以外、在宅で介護を受けていらっしゃる方等におきましては、在宅で受けていただけるような仕組みのほうも、引き続き実施をしていく予定です。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、打ってくださいね、打ってほしいというようなスタンスなのでしょうか。品川区のお考えはいかがか尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"接種につきまして、希望される方は接種いただく体制を取ってまいります。特に接種の勧奨や努力義務があります６５歳以上の高齢者の方、基礎疾患のある方等につきましては、接種のほうをお勧めしていきたいと考えております。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そういったことも１つ有効な周知の方法だと思うのですけれども、そういったことというのはお考え、予定はありますか尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"重症化リスクが高い高齢者の方、特にデイサービスに通われている要介護者の方への周知ですが、これまでも高齢者福祉課等、所管部署と連携しまして、高齢者施設に対してそういった周知をしていただくようなお願いをしています。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"貼ってもらうというような、施設内で掲示してもらうというような、そのような取組などもされたらいいのかなとは思います。選べる判断材料というか、それもしっかりと併せた上で、周知などしていただければというような要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"この頂いているパンフレットというか、チラシは、これもう実物ということでよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"取り急ぎ、こちらのほう印刷させていただきましたが、印刷中でございまして、完成版がありますので、改めてご案内申し上げます。こちらのほうはそのまま印刷に委託をしているものですので、情報は変わらないのですが、改めて別途、委員の皆様にはご案内申し上げます。","id":"exchange-090"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3668#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":61895,"voices":243}},{"id":"r05-20230821-8","meetingId":"r05-cm08","date":"2023年8月21日","dateIso":"2023-08-21","committee":"建設委員会","time":"午後 １時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"令和５年９月区民住宅（空き室）入居予定者登録募集","agenda":"令和５年９月区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これまでの応募倍率などを含めて、募集の状況を伺いたいと思います。令和２年度が３０件、令和３年度が６０件ということで倍に増えているわけですが、この増えている理由を伺いたいと思います。","respondent":"竹田住宅課長","answer":"令和２年度が、令和３年度が８７件に対して６０件で６９.０％、令和４年度が９６件に対して入居者数が４４件で４５.８％となっております。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"お伺いしたいのですが、２２日から２９日の間は、申込用紙を入手することはできないというふうに受け止めてしまっていいのでしょうか。目立つような形で、区民の方の目につくような形での働きかけというのがあってもいいのかなと思われるのですが、その辺はいかがか尋ねました。","respondent":"竹田住宅課長","answer":"ルール上は先ほど申し上げた日付までですが、皆様コロナ等様々なご事情がありますので、内容によっては柔軟に対応していきたいと考えております。募集しています等のご案内等をしておりますので、多くの方に知っていただくよう、今後も努力を続けていきたいと考えております。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"そうなってくると、品川区民の皆様方にとってこの区民住宅の魅力がどうなのかな。そして、当初の目的と、かなり意味合い的なところが変わってきてはいないかと思うのですけど、その辺はいかがか尋ねました。","respondent":"竹田住宅課長","answer":"全体の入居率というのは９５％なのですが、魅力を増やすことによってより多くの方に入っていただいて、入居率をより高めていきたいと考えております。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"全体的に、品川区の住宅事情をどう捉えていって、この区民住宅というのはどういう位置づけのものになっていくのか。区民住宅の、品川区の全体の住宅事情に対しての区民住宅の意味合いというのはどういうふうに捉えられて、これから進められていくのか尋ねました。","respondent":"竹田住宅課長","answer":"リニューアルの経費ですが、こちらは毎年厳選をしまして、適正な金額を財政部門に要求して、認められたものについてリニューアルを行ってあります。","id":"exchange-004"}]},{"id":"topic-02","title":"戸越６丁目地区における地区計画の変更","agenda":"戸越６丁目地区における地区計画の変更","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"住民へのメリット、デメリット、どういった変化があるのかというところを伺いたいと思います。今回、その範囲を拡大するということで、東地区のところでの変更点はあるのかどうかも伺います。","respondent":"小川木密整備推進課長","answer":"先ほどご説明をさせていただきましたが、また、現状からの変更点をもっと具体的に示してほしいといったようなご意見をいただいてあります。そして、３点目、現在の東地区の内容で何か変更があるのかというご質問ですが、東地区の内容については変更等はございません。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"その中で、建て替えへの支援の延長などを求めるというような声も出ておりました。そもそもそこからいろいろ暮らしを壊すことが始まっているということもありますので、やめるべきだということは意見として言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"敷地面積の最低限度６０m2という、これより小さい家をどうするのですかと、やはり気にされると思うのです。次の説明会のときにはそれが出てくるのかを説明するよう求めました。","respondent":"小川木密整備推進課長","answer":"２点目の具体的な内容等が分からないといった地域の皆様からのご意見等ですが、説明会、丁寧な説明に努めてまいりたいというふうに考えてあります。敷地面積６０m2以下に関しましては、その辺も、より分かりやすく丁寧に説明のほうは行っていきたいと考えています。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"この地区施設の設定というのは、地区施設になると何かメリットがあるのですか。いろいろな策を取っていますよというようなことを具体的に、ぜひ示していただきたいと考えていますので、その辺はいかがか尋ねました。","respondent":"小川木密整備推進課長","answer":"ある程度はもう半永久的にこの道路、公園という機能が担保される、確保されるといった点ではそれがメリットというふうに捉えてあります。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"確認をさせていただきたいのですが、特に私は、この2)の最低限度６０m2というところの地権者の方の理解がやはり必要だと考えています。６丁目の残りの地域の中で、これは具体的にどういう方々がどれぐらいの期間をかけて検討されてきたのか、そこからお伺いしたいと思います。","respondent":"小川木密整備推進課長","answer":"まだその検討も引き続き行われておりまして、その検討委員会を母体として、この６丁目地区の防災まちづくりの検討が行われていたところです。その検討が行われている中では、協議会の検討内容を、まちづくりの活動の状況等については周知を行っているところです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"そこは確認をさせていただき、まだまだしっかり地元の方のご理解をいただく必要があると思いますので、引き続きのご対応をお願いしたいと思います。恐らく６ｍはあるのかなと思えるので、大原通りはちょっと確認が必要なところもあるのかなと思うのですが、Ｃ。","respondent":"小川木密整備推進課長","answer":"区域に入っていない、半分入っているといったところで、全部入っていないからという理由です。大原通り等に関しましては、そういった意味では大原通りに関しましては、しっかりと位置づけのほうを行ってあります。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"４丁目もあるのでしょうか、１点だけ、逆にそれに対してどういうご回答をされていたのかをお聞かせほしいと求めました。ここの防災生活道路３号の高架の下の高さが今のままになってしまうのか、素案説明会のときのご説明内容をお聞かせほしいと求めました。","respondent":"小川木密整備推進課長","answer":"こちらの２か所につきましては、また、事業者等としっかりと協議をしていくといったところでご回答のほうをさせていただいているところです。３号のほうの高架下の高さにつきまして、幅員以外にもその高さにも視点を持って、協議のほうを行ってまいりたいと考えています。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"既にそういう一重二重の網がかかっている中で、今回防災、災害に強いまちづくりというところで、今までと要するに何が変わってくるのでしょうか。さっき道路の幅が６ｍというのはお聞きしたのですけれども、地元に対してどういう、もう少しご説明いただきたい。","respondent":"小川木密整備推進課長","answer":"こちらの事業に関しましては、基本的には強制力を持たない、防災まちづくりの方針を示す事業というふうに捉えていただければよろしいかと思います。建て替える際、道路の沿道にはブロック塀が設置できなくなるといった、ある意味強制力を持った計画といったところです。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"一定の強制力を持つことは、この２つの、今ある制度の中ではできないのだと。だから、今回の新しい地区計画で、いわゆる今おっしゃられたような制度をしっかりとつくっていくのだという理解でよろしいか尋ねました。","respondent":"小川木密整備推進課長","answer":"あくまでも、不燃化特区に関しては助成事業ですし、密集住宅市街地整備促進事業に関しましてはまちづくりの方向性を示すものです。地区計画に関しましては、そういうルールをしっかりと条例等で担保して、やっていただくといったような内容になってあります。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"資料に車両の出入口が書いてありますけど、事故がないようにしていただきたいと思うのですが、そこの区の見解と対策などがあれば伺いたいと思います。３施設統合することで、その後施設の活用などはどのように考えているのか、伺います。","respondent":"品川品川区清掃事務所長","answer":"それから、２点目、解体の間につきましては、品川庁舎、大崎のほうの品川清掃事務所のほうに人員のほうは持っていく予定です。それから、空き地につきましては、区としての政策のことになりますので、今この場で私がお答えすることは難しいかなというふうに思います。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"２０１９年の予算特別委員会では、多分、移転するというところでの検討の経緯というのはどういったことがあったのかを伺えればと思います。そうしたことがないようにというか、職場環境をしっかり確保してやっていただきたいと、それを要望しておきたいと思います。","respondent":"品川品川区清掃事務所長","answer":"２０１９年時点でのお話のほうですと、これはあくまでもほかの分室を残すというような考え方の中で進めていたものです。ある程度北品川分室に限定して考えていったところというのもありますので、やはり品川区内の分室全体の在り方について検討した結果です。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"対象がどういう方なのか、保護者などが参加できるようにしていただきたいと思うのですけれども、いかがでしょうか。そうすると、そこは使いやすいようにしていただきたいと思うのですが、区のお考えを伺いたいと思います。","respondent":"高梨公園課長","answer":"一括してお答えをしますが、まず、野球場の配置ができる部分というのは限られているというふうに考えてあります。今年度と来年度で実施する設計の中で決めていきたいなというふうに思いますが、大きさ等々を勘案しながら、このように考えているところです。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"それはもう、住民の皆さん、子どもたちの意見も反映してほしいと求めました。利用者の方、保護者の方にも周知をしていっていただいて、子どもの声をしっかりと反映していっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"１点確認が、子供の森公園のほうですけれども、野球場があったのです。なので、清掃事務所のほうも、やはりそういう車の行き来がとても怖いなと思っているのですが、ここは何か特別、整備をするとか何かあるのか尋ねました。","respondent":"高梨公園課長、品川品川区清掃事務所長","answer":"ワークショップですと、あまり何十人、ワークショップだけにとどまらない様々な手法でご意見を集めたいなというふうに考えてあります。今回も１０月に説明会を行いますが、また… 駐車場からの出口の予定場所につきましては、現在も警察といろいろと相談をしているような段階です。非常に危ない位置だというところは我々も認識をしておりますので、例えば回転灯の設置だとか、それから誘導体制。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ安全確保はお願いしたいと思います。そういうのをして、自分の描いた絵が少しでも具現化して公園になったのだというような、ぜひいろいろな手法を考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"１００ｍを越えた先の方も、１００ｍということの内容は、そこをまずご検討ほしいと求めました。その平成１２年だったか、これは議事録を確認しなかった私のミスなのかもしれません、その辺の経緯をお聞かせほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"議会とのやり取りの点ですけども、再編に当たっては今回案件を出すのは初めてですので、これまではなかったというふうにお答えするのが一番よいかと考えています。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"このままでいいのかどうかというのは、重たい課題として受け止めていく必要があるのかなと、意見として述べします。これ具体的にどういうものなのかということと、交通安全性をしっかり確保してほしいと求めましたが、その辺をお聞かせほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"中延中継所のほうですけども、こちら、分室というより積替え所ということで使用しています。中延中継所に大きな清掃自動車を用意しまして、そちらにごみを積み替えるというような場所で、使用しているというものです。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"こういうところは配慮すべきだということも当然していただくわけですが、また、ぜひご認識いただいた中で運営をしてほしいと求めました。そこだけ１点、ご決意のほどをお聞かせいただきたい。","respondent":"品川品川区清掃事務所長","answer":"３丁目と４丁目のちょうどぎりぎりぐらいの場所なので、申し訳ありません。児童相談所のほうとは話を進めておりまして、建設時等にも対応策等は考えていきたいと、このように思っております。","id":"exchange-022"},{"speaker":"まつざわ副委員長","kind":"質問","question":"質問は、荏原中央公園は全面改修工事で、子供の森公園というのは全体の再整備と書いてあるではないですか。荏原のほうは全部を無しにして考えて、この子供の森公園というのは、あるものをそのまま何か新しく造り変えるということでいいか尋ねました。","respondent":"高梨公園課長","answer":"部分改修であるとか、何かを残してというようなことではなく、全体の再整備ということで両方の公園ともそのように考えているところです。考え方といたしましては、全面の改修、再整備改修工事ということで捉えていただければと思います。","id":"exchange-023"}]},{"id":"topic-03","title":"Ｏ歩道橋補修工事","agenda":"Ｏ歩道橋補修工事","exchanges":[{"speaker":"田中委員","kind":"確認","question":"そもそもここのこういう歩道橋を造る際の強度というのでしょうか、これがもう少し増えるという際に、どの程度までここが強度があるのか。そういったことも、今のＯ歩道橋の構造的なものを踏まえた強度になっているのか、ちょっとそこを確認したい。","respondent":"森道路課長","answer":"例えば幅員であったりとか、重量については、例えば１m2当たりに何人乗るというようなイメージで設計がされているということだと思います。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"交通規制のところだけ聞きたいのですが、夜間作業の何か具体的な時間帯とか日にちとかが出ていれば、まず教えてほしいと求めました。ご心配とか、車が増えたということは出てくると思うので、そこら辺のいわゆる交通規制についてもちょっと教えていただけますか。","respondent":"森道路課長","answer":"それから、撤去については、最後の令和６年の１月頃に２週間程度を考えています。それを１車線ずつ通行規制しながら、片側１車線、片側２車線というのは確保しながら進めていくというふうに考えておりますが。","id":"exchange-025"},{"speaker":"木村委員","kind":"質問","question":"今この写真を見ていて、一番下段の右側にあります、この画像、外装版の補修ですか、道路と陸橋との段差がありますよね。できればこういうことに対しても全て改修をしていただければと思っているのですが、ご意見を説明するよう求めました。","respondent":"森道路課長","answer":"写真にあるとおり、少し陰になっている部分もありますので、多少の段差があるのかなというふうには思います。今回の工事の中で対応できることがあれば、しっかり対応して、段差はできる限り少なくしていきたいというふうに考えています。","id":"exchange-026"},{"speaker":"木村委員","kind":"質問・要望","question":"よろしくお願いしたいのですが、やはり本当に自分がそういう体になって初めて、そういうつらさというのがよく分かりますので、できればそういう点について細心の注意を払ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"西本委員","kind":"確認","question":"ここは完全に品川区の持ち物という形で整備がなされて、予算立てのほうも品川区の財源から出ていますよということなのでしょうか。そこを確認したいと求めました。","respondent":"森道路課長","answer":"約８ｍ弱ぐらいなのですけれども、そこの８ｍぐらいの部分については、今回の補修工事の費用も５分の１いただく予定にしております。全体的には区のほうでやるのですけれども、費用の負担をいただくという形で整備をしています。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"大崎ニューシティに協力いただいているのですね。ちょっと違うところからも関係性づくりというのをお願いしたいなというふうに思っているのですけれども、その点はいかがか尋ねました。","respondent":"森道路課長","answer":"全体約３９.４ｍ、４０ｍ弱あるのですけども、そのうちの８ｍ部分が大崎ニューシティの部分ということになりますので、５分の１になります。その５分の１で費用負担を案分しているということになりますので、様々、意見調整していければというふうに思っています。","id":"exchange-029"}]},{"id":"topic-04","title":"荏原中央公園改修工事","agenda":"荏原中央公園改修工事","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそうした複合遊具があるので、同じようなものなのかどうかというところを確認させてほしいと求めました。今回の改修にどのように反映されたのか、されなかったのかも含めて、それぞれの対応について理由も伺いたいと思います。","respondent":"高梨公園課長","answer":"検討と対策を進めてまいりたいというふうに考えているとともに、ほかの公園でも行ってまいりたいというふうに考えてあります。害虫が発生しない、もし発生した際には迅速に対応するといったところで、対応してまいりたいというふうに考えてあります。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用者の声を反映していってほしいと求めましたが、１点、今回のトイレの改修ではどのようになるのか伺いたいと思います。その利用者に周知をしていただきたい、保育園にも周知をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"契約工期のほうは８月１４日から着手ということになってありますが、９月の下旬頃、現地で着工する予定にしています。工事について情報提供をするとともに、ほかの公園のご案内等々、しっかりと対応してまいりたいというふうに考えてあります。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"トイレに関しての考え方をお聞きしたいのですけれども、公園を改修するときに、トイレはどういう形式を考えられているのでしょうか。どういう使い分けをしていくのだろうかとかと、今検討中であれば検討中でいいのですが、考え方があれば説明を求めました。","respondent":"高梨公園課長","answer":"２％までしか建築物が建てられないという制限がありますので、その制限の中でどういった構成のトイレが設置できるのかというふうに考えてあります。","id":"exchange-032"},{"speaker":"西本委員","kind":"意見","question":"そのときに、どういう方向性がいいのだろうとかというのを一つの意見として、これからいろいろ法整備もされる中で変わってくるかと思うのです。できればそういう方々へのご意見等を聞いて、公園だからこそトイレと私は思っておりますので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"工事期間中に関しましては、小学校に隣接しているということもありますので、ぜひ安全性、ご配慮ほしいと求めました。やはり公園のひとつ配慮すべき点は、そこも配慮した公園をぜひ造ってほしいと求めましたが、その点だけ１点お聞かせほしいと求めました。","respondent":"高梨公園課長","answer":"請負業者とともにしっかりと話をして、特に子どもたちに対しての安全性というものは担保してまいりたいと考えています。しっかりと防犯カメラ監視中というようなことを掲示して啓発するような対応等、ソフト対策も含めてやってまいりたいというふうに考えてあります。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/372951?Template=document&Id=4386#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":35788,"voices":108}},{"id":"r05-20230821-9","meetingId":"r05-cm08","date":"2023年8月21日","dateIso":"2023-08-21","committee":"文教委員会","time":"午後 １時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"令和６年度品川区立学校使用教科用図書の採択","agenda":"令和６年度品川区立学校使用教科用図書の採択","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、市民科はオリジナルの教科ということなので品川区で作っていると思うのですけれども、こちらのいわゆる教科書会社は何かあるのでしょうか。伺います。","respondent":"丸谷教育総合支援センター長","answer":"２会場ございまして、教育総合支援センター内にあります教科書センターで６月２４日から７月２２日まで、祝日の休館日を除きます。続いて、市民科の教科書の作成会社ということですけれども、こちらは教育出版にお願いをしているものです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"教科書展示の期間は今伺ったのですが、これはどう考えればいいのかというか、そこら辺はどのように考えたらいいのでしょうかということが１つです。現場の教師の意見を伺うということも大切だと思うのですけれども、話ですと、現在はどのようになっているのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"実際に採択に当たって、教科用図書の調査検討委員会という委員会を立ち上げております。現場の先生方の意見についてということですけれども、こちらも調査検討委員会の下部組織で調査研究会という組織を立ち上げております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"手続をしているわけですから、これは順番を今後工夫していただきたいのですけれども、いかがでしょうかということが１つ。もう少し現場の教師の意見を積極的に伺えるような、工夫が必要なのではないかというのはいかがでしょうかというのが２つ目。","respondent":"丸谷教育総合支援センター長","answer":"アンケートの総数については５５通です。現在、集計をしているところですので、整った段階で教育委員会にも報告してまいります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"どういう期間なのか、どういうふうに進めていくことが望ましいのか、また提案したいと思います。何のためにやっているのですかというふうに思ってしまうのですけれども、それは改善が必要なのではないかと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"そうしたところから意見は、ある程度、資料には反映できているものと考えております。表示が見づらいというようなご意見かと思いますので、来場された方が迷わないような掲示方法については、改めて考えていきたいと思います。","id":"exchange-004"},{"speaker":"吉田副委員長","kind":"質問","question":"これまで採用されていた会社と変わったのか変わっていないのか、そのことについて伺いたいと思うのですけれども、どうやって伺うのがいいでしょうか。変わったところを伺ったほうがいいか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"資料に１３種類の教科書がありますけれども、そのうち８種類が会社が変更になっております。図画工作は開隆堂から日本文教出版、保健は光文書院から東京書籍、特別の教科道徳が学研教育みらいから東京書籍へというふうに変更になっております。","id":"exchange-005"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そこで、例えばそういうふうに変わった理由とか、そういうことについては議論がされるのですか。全部おっしゃるのは難しいから、どこかに資料があればいただきたいのですけれども、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"そういった意味で、どうして出版社を変えるというような議論はなされていないというのが現状です。今後、ホームページに掲載予定ですので、それまでお待ちいただければと思います。","id":"exchange-006"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"では、ホームページをきちんと拝見させてほしいと求めました。第３庁舎が非常にありがたかったのですけれども、そういう展示の場所の変化というか、それはどのように決められたのか教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"展示会の場所ですけれども、今、教育総合支援センター内の教科書センターと、今回は品川図書館で、２会場で行いました。この２会場が、もう１か所、品川図書館という図書館の母体となる会場を設定しています。","id":"exchange-007"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"日頃から、もう少し多くの市民の方たちに子どもたちの教材について関心を持っていただくということも必要ではないかと思いますので、これは要望です。これは、もし何かコメントがあったら、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"会場の人員、そういったものが確保できれば、また検討していきたいというふうに考えております。現在使われている教科書については常時展示がありますので、何か興味があればお越しいただければ、いつでも閲覧が可能になっております。","id":"exchange-008"}]},{"id":"topic-02","title":"ヤングケアラー支援事業のこれまでの取り組み状況","agenda":"ヤングケアラー支援事業のこれまでの取り組み状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"４月１日からの相談件数、ＬＩＮＥは７月３日からということですが、現在どうなっているのでしょうかということが２つ目。そういったところなどに、協力ができそうなところには協力を呼びかけていただきたいのですが、いかがか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"コーディネーターの仕事の内容ですけれども、先ほどご説明をさせていただきました本人やご家族からの相談を受けるというのがまず１つ。実際にどういった形での支援が必要なのかといった、その支援策の検討に当たりまして、担っていただいているところです。","id":"exchange-009"},{"speaker":"安藤委員","kind":"確認","question":"周知をさらにしていくと、さらに増えていくのかなということで、こういった事業が始まったことに意義をすごく感じました。月曜日から金曜日、１１時から２０時の間はコーディネーターの方が相談を受けられるという体制になっているのかということだけ確認したいと求めました。","respondent":"染谷子ども家庭支援センター長","answer":"委員がおっしゃられた月曜日から金曜日の１１時から２０時の部分のお話かと思うのですけれども、こちらはＳＮＳ、この時間帯で相談は受けしています。実際に子ども家庭支援センターに勤務して相談に応じるのが、今、実施をしています。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"(3)の実態調査についてなのですが、記名式でやられるのかどうかだけ１点教えていただきたいのと、これは非常に重要なのです。２点、説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"アンケートの中に、区の子ども家庭支援センターのほうに相談をしてくださいというような形の記載はさせていただいて実施をしたいと考えております。","id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そこは要望で終わります。この周知方法を含めて取り組んでいただきたいと思うので、これは要望で終わりますので、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"私立の小学校に行っている４年生と、どちらにしても送ればいいのですけれども、どうやって抽出するのかということをお尋ねします。それとも小学校、中学生に関しては、どうやって区立の子以外の子を抽出できるのでしょうかというところです。","respondent":"染谷子ども家庭支援センター長","answer":"このＰＲカード、ポスター以外に、お子さん向けにリーフレットの作成を予定しております。そちらの方については、教員、担任の先生から説明をしていただきながら配付をしてもらうというところを想定しています。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"みんな、それを出してやりましょうねというふうに学校で説明するということで、そういう理解でよろしいですか。最後にそれを。","respondent":"染谷子ども家庭支援センター長","answer":"その同じタイミングに、学校のほうにアンケートに関する２次元コード等の入ったお知らせを直接お子さんに手渡しをしていただきたいというところで、同時期に区立のお子さんについては学校のほうから配付をしていただくというようなことで現在考えているところです。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"生年月日で対象をまず抽出し、教育委員会のほうで学籍が分かるので、その分は郵送しないという認識でよろしいですか。すみません、最後にそれだけ。","respondent":"染谷子ども家庭支援センター長","answer":"委員おっしゃるとおりで、区立のお子さんについては郵送はしない予定です。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"確認","question":"これは確認です。小学生には分かりやすい設問というのは、これ、３０問をやはり想定しているわけか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"３０問の設問については少しボリュームがあるかなというふうに考えておりますので、全体を通じて最大で３０問程度を想定しておりますけれども、アンケートの案を作っているところです。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは私の要望です。そういうこともやっていただきたいと思っているのですけれども、すみません、教えてほしいと求めました。","respondent":"染谷子ども家庭支援センター長","answer":"民生委員協議会のほう、また、今後も地域の方たちにヤングケアラーについて認知していただけるような研修会の企画はしてまいりたいと考えております。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"約１か月の間で７件の、人材の確保とか、その辺のことを教えてほしいと求めました。","respondent":"染谷子ども家庭支援センター長","answer":"現在、常時ではございませんけれども、５名体制でご相談を受けさせていただいているというような状況があります。今後、メッセージを送ったにもかかわらず、何も回答がないような状況といったことが発生しないように対応はさせていただきたいと考えております。","id":"exchange-018"},{"speaker":"ゆきた委員","kind":"意見","question":"非常にすばらしい取組だと感じております。さらに引き続き、人員の確保と、ヤングケアラーの浸透、啓発、さらなる支援をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そういう方たちこそ自分たちで発信ができないわけではないですか。そういう実態調査については、何か別の方法で取り組まれるのか伺いたいのですが、いかがか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"現状ご説明をいたしました小学校４年生以上のお子さんを対象としたもので実施していくということで今考えておりますけれども、これ以外にも、正に。","id":"exchange-020"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ぜひそういう実態調査も何らかの形で継続して考えてほしいと求めましたし、これ、やはり年数を重ねて何回もやっていく必要があるかと思います。既に何か方針をお持ちなのかということが１点と、ここの所管も合わせて考えていくべきだと思うのですが、ぜひそちらも説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"庁内連携して支援策を検討していくに当たっての資料として実態調査をさせていただきたいと考えておりますので、今後も引き続き組織横断的に対応できるように、そこの部分については実施をしていければというふうに考えております。","id":"exchange-021"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ぜひお願いいたします。幾つかの部を横断的に構築しないと支援策ができなかったというふうに伺っていますので、その点について、いかがか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"家事援助等の訪問支援ですとか、学習支援ですとか、そういった具体的な支援策の展開も実施してまいりたいというふうに考えております。","id":"exchange-022"}]},{"id":"topic-03","title":"品川区立ぷりすくーる西五反田指定管理者候補者の選定","agenda":"品川区立ぷりすくーる西五反田指定管理者候補者の選定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この施設の設置目的や事業内容などに特別な理由がある場合だということなのですが、今回の特別な理由というのは何なのか伺いたいということが１つ。こちらを変更するということなのか、それとも継続するという考えなのか、その辺を尋ねました。","respondent":"立木保育課長","answer":"幼児教育施設と保育園が一緒になった施設ですので、施設運営の連続性を重視するということが、特別な理由です。現在の事業者、指定管理者であります社会福祉法人福栄会を、指定管理者候補者として継続して選定をする予定です。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"どう考えたらいいのかなというのは、なぜ今回、いかがか尋ねました。","respondent":"立木保育課長","answer":"現在もご利用されている方がいらっしゃる中では、今現在の運営内容を引き続き連続的に提供していくというようなことで、特別な理由に当たります。","id":"exchange-024"},{"speaker":"吉田副委員長","kind":"意見","question":"福祉施設なので連続性を重視ということなのですが、それであれば、特別ということにならないのではないかと思います。永遠にという言い方がいいかどうか分かりませんけれども、もう一度気になるところなのですけれども、改めてご説明ほしいと求めました。","respondent":"立木保育課長","answer":"先ほどお答えさせていただいたところになるかとは思いますが、幼児教育施設と保育園との一体運営をしている福祉施設です。これは当初、今現在も、やはりこれも連続性を大事にするという意味合いでは特別な理由に当たると考えているところです。","id":"exchange-025"},{"speaker":"吉田副委員長","kind":"質問","question":"そのときは、特別な理由として、特に実績がないところに指定管理を任された。そこに特別な理由があれば、その辺に何か事業者として、品川区としてそこをどう評価するかというところを教えてほしいと求めました。","respondent":"立木保育課長","answer":"認定こども園化ということが１つ大きな目標としてある中で、ＮＰＯ法人では認定こども園化することが難しいというような状況でした。令和３年から福栄会のほうに事業譲渡がされた中で、そういった意味では、連続性はきっちり担保されているのではないかと考えているところです。","id":"exchange-026"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"この間、なるほどというふうに思うので、あくまでＮＰＯ法人だったときからの連続性というところだけが評価の対象というようなことなのでしょうか。ぜひ、そこに向けたきちんとした評価点をぜひ持つべきではないかと思うのですが、その点についていかがか尋ねました。","respondent":"立木保育課長","answer":"ＮＰＯ法人子育て品川で運営していたスタッフがそのまま福栄会のほうに移籍といいますか、雇用をされているという形になってあります。そういった面もプラスアルファされたところで、幼児教育施設の運営という中に融合されているのではないかというふうに捉えているところです。","id":"exchange-027"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これ以上伺っても同じようなやり取りになってしまうと思いますし、ぜひ福栄会にも確立していただきたいということを要望いたしまして、これは意見とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"区内保育園等あり方検討に関する経過","agenda":"区内保育園等あり方検討に関する経過","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"取り組んでいないものをこれから付加するということなのか伺いたいと思います。最初の１番のところの文章の中に、どのような役割だというふうにご説明されるのでしょうか、伺いたいと思います。","respondent":"立木保育課長","answer":"今、検討を進めているこちらの案の拠点園に関しましては、子ども・子育て支援事業計画の６区域の中に統括する拠点園をそれぞれ置いて。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"なぜなのか、人的配置が必要だというふうに思いますけれども、そこら辺はやっていただけるのでしょうかということを１つ質問したいと思います。そこら辺を伺いたいと思います。","respondent":"立木保育課長","answer":"先ほど説明の中でも少し触れさせていただきましたが、経営判断として、バッファ機能を区立側で持つ必要があると考えているところです。は施設の再配置等を考えた中で人員を生み出しつつ、そういうような考え方で、検討を進めているところです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"私の意見ですけれども、いかがでしょうか。最後に伺いたいと思います。","respondent":"立木保育課長","answer":"先ほど申し上げたとおり、区内どこのエリアでも同じ子育て支援が受けられるということを目指してこういったことを考えていくところがあります。当面、待機児童を再度発生させるわけにいかないので、そういったところも見極めながら、検討を進めていくというような考え方です。","id":"exchange-031"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"保育の質の向上というのは、全ての保育園に求められるところかと思うのですが、そこの機能を拠点園が担うという意味なのでしょうか。いかがか尋ねました。","respondent":"立木保育課長","answer":"子育て支援の特化というところで、質の向上や子育て支援の充実という部分に関しては、赤枠で特化という意味合いでここに付け加えているものです。事業として持たせるという、そういうようなイメージで、この２つの赤丸をつけているところです。","id":"exchange-032"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"例えばどこの保育園にも求められることなので、ほかのサブ拠点園も含めて、保育の質の向上を具体的に担うということなのでしょうか。もう一度お話を伺いたいのですが。","respondent":"立木保育課長","answer":"全ての園で同じ在宅子育て支援、この地域連携の中心的役割をそれぞれの園が担えばいいというようなことは、もちろん間違いありません。情報交換ですとか、そういったところの音頭を取っていく、そういうようなイメージを持っていただけると分かりやすいのかなと考えています。","id":"exchange-033"},{"speaker":"吉田副委員長","kind":"質問","question":"こういうことを１つの足がかりとして、今後の見直しも含めて、それはまた改めてご報告をいただけるというふうに理解してよろしいのでしょうか。その点についても伺いたいと思います。","respondent":"立木保育課長","answer":"やはり等しく質の高い子育て支援を受けられるということが、理想の目標として、この検討の中で置いているところです。それと、今回、途中経過ということでご報告させていただきましたが、取りまとめの部分に関しましてもご報告をするというふうに考えております。","id":"exchange-034"}]},{"id":"topic-05","title":"育児休業にかかる児童の預かり時間拡大","agenda":"育児休業にかかる児童の預かり時間拡大","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"子育て支援という点では、利便性も向上しますし、いい制度変更なのかなと思うのですけれども、この変更の動きの背景について、もう少しご説明いただきたいと思いまして、これまでのルールの理由も含めて、変更の動きの背景について説明するよう求めました。","respondent":"立木保育課長","answer":"親子で過ごす時間を多く取っていただきたいというような考え方で、９時－１６時の７時間のお預かりということを原則お願いをしている状況です。品川区も７時間ではなく８時間の預かりで、時間帯も各ご家庭の事情に合わせて設定をするというような方向に変換をするというものです。","id":"exchange-035"},{"speaker":"安藤委員","kind":"意見","question":"今の子育て環境といいますか、そういったものにしっかりと実態に対応していただいて、制度も適切に見直していただくということが必要だと思いますので、引き続き必要な変更などはお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問","question":"なぜ今この時期に急に制度変更するようになったのか。説明を求めました。","respondent":"立木保育課長","answer":"来年の４月からというふうにしてしまいますと、今、問い合わせが増えてきていることに合わせて検討を進めてまいりました。園のほうも対応できるのではないかというようなところから、お問い合わせが増えてきたこのタイミングでやらせていただきたいです。","id":"exchange-037"},{"speaker":"ゆきた委員","kind":"質問","question":"２人、３人と育児しなくてはいけなかったところが、非常に歓迎する内容だと感じております。それとも第１子のときと同じように、産前産後の２ヶ月の計５ヶ月は、こちらを明確なお示しをしてほしいと求めました。","respondent":"立木保育課長","answer":"産休に関しましては、短時間、それから標準時間、どちらもご家庭の状況に合わせて認定申請を出していただくことが可能です。必要であれば、例えば配偶者の方の勤務時間に合わせて、例えば１０時間とか、そういったお預かりも可能です。","id":"exchange-038"},{"speaker":"ゆきた委員","kind":"質問","question":"ということは、令和４年から令和５年になった際に改正されて、今までは午前９時から午後４時までの間の預かりだったものが、令和５年からは、上の子を預けていた場合、育児休業に入って妊娠した場合は、時間は最長１１時間まで預けることができるという認識でよろしいか尋ねました。","respondent":"立木保育課長","answer":"可能であれば、その時間帯でということを記載していたところはあるのですけれども、それはお願いベースでございました。なかなか保育園のお迎え等も難しいというところがあるので、そこは案内のほうも外した形で、今現在やっているところです。","id":"exchange-039"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"令和５年１０月から改正されるということになると思われるので、より周知してほしいと求めましたので、こちらは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"このチラシが郵送されて周知されるということでよろしいですかということと、それと、これは申請がないと支給されないという仕組みなのでしょうか。そこを伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"基本的に東京都から対象者へ、各家庭に通知が行くということです。そこの通知の中身が、振込先等も記入をしてもらうということなので、申請をしないといただけないというふうにこちらでは判断しております。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"申請漏れがやはりないように、品川区としても何か制度周知の工夫をしたほうがいいのではないかと思うのですけれども、そちらについては何か考えていらっしゃることはありますか尋ねました。","respondent":"飛田子育て応援課長","answer":"区のほうだと、もちろん戸籍住民課もそうですし、各地域センターのほうにも、こちらのお知らせを配布する予定です。我々の窓口だと、引っ越ししてきた方については、児童手当の申請等もありますので、そちらの方々にも通知をお知らせしていきたいと考えております。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/106437?Template=document&Id=5106#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":39636,"voices":128}},{"id":"r05-20230821-5","meetingId":"r05-cm08","date":"2023年8月21日","dateIso":"2023-08-21","committee":"総務委員会","time":"午後 １時００分～午後 １時５１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"令和５年度都区財政調整交付金当初算定結果","agenda":"令和５年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"石田（秀）委員","kind":"確認","question":"７区に入るのかというところからまずお聞きしたいのと、５区と来ていると思うけれども、そう考えるともうこれは協議に入るのかどうか。これほど２兆１,０００億円にもなっていて、出ていないのかというのを、まずそこだけ２つ教えてほしい。","respondent":"遠藤財政課長","answer":"０.１％の部分につきましては、５５％から５５.１％ということで東京都が暫定的にということで措置されている形になっているところです。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"だから、逆に特別区のほうでこの２％なら２％と算定してしまえばいいのですよ。例えば高校生の医療費、そこら辺のそういうところというのは絶対にないようにしてほしいなという希望なのだけれども、そこら辺はどうか尋ねました。","respondent":"桑村副区長","answer":"だから、いかに２３区の中の児童虐待をはじめとする、そういうことに一緒に取り組んでいこうというのが一つのテーマです。２３区の一枚岩というのがどうなるか、それは話し合いを続けるのは構わないと思いますけれども、その辺をまたよろしくお願い申し上げたいと思います。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど言った５５.１％を５５.０％にしてもう一度という前に、絶対にされてほしくないなということだけお願いをしておきます。の細かいことがあったけれども、それは結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"今後も頑張ってほしいということと、委員長にもお願いしたいのですが、支援できる方法を考えて要望していくような時期に来たのではないかと思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"区民アンケート","agenda":"区民アンケート","exchanges":[{"speaker":"澤田委員","kind":"意見","question":"それに自分たちで書いたものを送るとかそういうことなのかどうなのか、方法がちょっと分からないと思いまして、お教えほしいと求めました。","respondent":"辻広報広聴課長","answer":"特別支援学校ですとか国立・私立、インターナショナルスクール等、区立学校に通っていないお子様向けにはホームページを使っての実施となります。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"そうしたら、重複してしまうとか、何度も送ってしまうとかというトラブルは大丈夫か尋ねました。","respondent":"辻広報広聴課長","answer":"そこは懸念事項の一つですが、ホームページ上のそこにアクセスをすれば、どなたでもできてしまうというデメリットがあります。そのページの最初のところに１人１回ですとか、あとは性善説に従ってということでやるしかないかなと考えています。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"せっかくこれだけ皆さんのご意見を聞く場ができたのですから、私はもう１件でも１人でも多くの、回答をしていただけるようにやっていただきたいと。今回は児童・生徒アンケートのほうでありますが、裏面のほうで「１０年後、品川区はどんなまちになっていてほしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大倉委員","kind":"質問・要望","question":"これ、この低く飛んでいるからどうなのかというのがよく分からなくて、子供の気持ちを書いてもらうというほうが分かるのではないかなと思ったのです。先ほど今変更ができるのかと須貝委員のほうからも意見があったので、今から多少いじって変えることができるのかどうかというのを説明するよう求めました。","respondent":"辻広報広聴課長","answer":"まず保護者向けにこういうアンケートを実施しますということで、できる範囲でサポートしてくださいというような通知文を出す予定です。なかなかこれでは読み取れませんので、平仮名版も作りまして、その２つを載せるような予定でおります。","id":"exchange-008"},{"speaker":"大倉委員","kind":"質問・要望","question":"タブレットで基本的には回答を求めるというところで、もし可能であればそういったところの工夫をしてもらえるとありがたいというところです。回収見込みですけれども、６０％ということですが、ぜひ回答率を高く回答できるように周知をしてほしいと求めました。","respondent":"辻広報広聴課長","answer":"今この子供向けのアンケート自体は教育委員会のほうと連携してやっておりまして、教育委員会側で今考えているところですので、これからも連携しながらアンケートの回収率が上がるような方策をしていきたいと思っています。","id":"exchange-009"},{"speaker":"塚本副委員長","kind":"意見","question":"２番のところで、８月の上旬には到着したような記憶があるのですけれども、皆さんに配送が遅れたということがあったのか。この延長に至った理由をもう少し詳しくお伝えくださいとの意見を述べました。","respondent":"辻広報広聴課長","answer":"一度に問い合わせの電話がかかってきてしまいますと私どものほうでも対応できかねるというところがございまして。その最後のところの部分について、最後に到着した方が約２週間弱しかないとやはり答えるのに厳しいだろうということで、延ばさせていただいたです。","id":"exchange-010"}]},{"id":"topic-03","title":"Ｏ歩道橋補修工事請負契約","agenda":"Ｏ歩道橋補修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"Ｏ歩道橋補修工事ですけれども、ここは都道上にある歩道橋なのでしょうか。それなら品川区で予算をかけてやるものではなくて、全額都のほうで負担していただける場所なのか尋ねました。","respondent":"佐藤（聡）経理課長","answer":"工事内容につきましては所管のほうで実施しているところでありますので、聞いている限りでお答えします。先ほどご説明したとおりで、資料の４ページのところにもありますけれども、天井から漏水してきていると。","id":"exchange-011"}]},{"id":"topic-04","title":"荏原中央公園改修工事請負契約","agenda":"荏原中央公園改修工事請負契約","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"もしかしたら所管違いかもしれないですけれども、トイレの改修工事の中のこととかは、ここではなくて建設委員会ですか。では、すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246119?Template=document&Id=2274#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":17476,"voices":41}},{"id":"r05-20230822-14","meetingId":"r05-cm08","date":"2023年8月22日","dateIso":"2023-08-22","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"そのアクセシビリティの考え方を手引きとしてまとめるということは、今は大体どこもこのようなことをやられているのかどうかというところが１つです。こちらについては、皆様、了承を得たということでいいのかどうか、教えてほしいと求めました。","respondent":"山下新庁舎整備課長","answer":"基本計画策定後、区民の皆様に説明する機会を設けることで、新庁舎の整備を知っていただく一助になるのではないかと捉えているところです。","id":"exchange-001"},{"speaker":"山本委員","kind":"質問・要望","question":"そして、どのようにお聞きになるのでしょうかというところ。追加的な区民の方からの要望が出てきたときは、織り込まれるのでしょうかということでご質問させていただきました。","respondent":"山下新庁舎整備課長","answer":"昨年度、新庁舎整備基本計画の素案の説明会に当たりまして用いましたオープンハウス形式での説明会を実施できればと考えています。最後に、電子の形で期日までにいただいたものを手引きの修正に反映させて完成に向けて取り組んでまいりたいと考えています。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ、より多くの子育て世代の意見を拾っていただきたいということがありますので、それ以外のヒアリングについてもご検討いただければ幸いです。ぜひ、進めていることを広く区民の皆様に知っていただいて、アクセシビリティの観点においてもいろいろな意見を集めていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"今の、できるだけ区民の方からの意見をというところで言うと、一般的にはパブリックコメントの手法を使うことも考えられるのですけれども、今回は使わない理由はどうなるのか尋ねました。","respondent":"山下新庁舎整備課長","answer":"手引きの作成という形で考えてございまして、いわゆる計画の策定ではないところから、今回はパブリックコメントを実施する考えはございません。","id":"exchange-004"},{"speaker":"松本委員","kind":"確認","question":"ここは確認しておきたいのですけれども、パブリックコメントではないけれども、素案に対して意見などを電子でも応募することも検討されているのか。これはどちらになるのか尋ねました。","respondent":"山下新庁舎整備課長","answer":"説明をした際にも、説明会の場でご意見を直接伺う形も考えられますし、それ以外に電子媒体を用いたものも併用した形で取り組んでいきたいと考えています。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"今回でしたら、区内の障害者団体の方たちにヒアリングはするけれども、場合によってはそこに入られていない方で意見を言いたい。でも、説明会には参加されていないという方が意見を言いたい場合にはどのようにすればいいのかというところをお願いいたしますとの意見を述べました。","respondent":"山下新庁舎整備課長","answer":"説明会への来場が難しい方につきましても、ホームページ等々から、そのページより直接リンクを貼って、電子意見フォームに飛ぶ形でご意見をいただければと考えています。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは、区である程度、絞った項目、設問を作って、それぞれ当てはまる団体向けに設問していく形と、要望の聞き取りをやるのか。両方だと思うのですけれども、設問方式でやるのかどうかということを教えてほしいと求めました。","respondent":"山下新庁舎整備課長","answer":"一定、手引きの素案としてまとめていくというところからは、そのゴールに向けて、ある程度設問項目は設けた形で取り組んでいきたいと考えています。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。これは本当に要望で、ある程度絞って手引書を作ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"５番目の有識者への意見聴取なのですけれども、これはどの段階で有識者の方にお聞きするのか。どういった有識者を考えておられるのかを説明するよう求めました。","respondent":"山下新庁舎整備課長","answer":"その後の区民向けの説明の段階では、そういったお子様の保護者も含めまして、皆様にご周知ができるように取り組んでまいりたいと考えています。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一番最初にお伺いしたアクセシビリティの考え方で、ここにも「誰にでもやさしく便利で機能性にあふれた庁舎」ということが説明で書いてあるのです。様々な団体からの要望を聞く中で、そういったご要望もいただいているのですけれども、ソフトの部分での要望なども出るような気もするのですが。","respondent":"山下新庁舎整備課長","answer":"基本設計の段で反映できるもののほかに、実施設計で検討していくべき項目についてもご意見をいただくことはあろうかと考えています。どういった形なら新庁舎で適用できるかということをお示ししながらということで、素案、もしくは完成の段階でお示ししていくよう考えてあります。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけ要望です。聞き取っていただければいいなと思っているのですけれども、この点についてはいかがか尋ねました。","respondent":"山下新庁舎整備課長","answer":"実際にお話を始めれば、やはり多岐にわたるご意見を頂戴する形になるのかなと考えています。それ以外の部分は、また違う形でどのような対応ができるかというところは考えてまいりたいと考えています。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"固有名詞はこれからですか。今、その辺をどのように捉えていらっしゃるのか、お伺いしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"今回の庁舎跡地等活用検討委員会は、庁舎跡地等活用検討委員会の中で説明させていただきました資料や、そこのところで情報共有します。定めてまいります考え方や、検証していく想定される機能も含めまして、そういったところにご意見を反映していきたいと考えているところです。","id":"exchange-012"},{"speaker":"塚本委員","kind":"確認","question":"今度は行財政改革特別委員会での質疑の内容等が、庁舎跡地等活用検討委員会にはどのようにフィードバックされていく予定、考えなのか。ここも確認したいと求めました。","respondent":"泉広町事業調整担当課長","answer":"行財政改革特別委員会の中で出ました意見をどういった形で庁舎跡地等活用検討委員会の皆様にフィードバックしていくかというところのご質疑・ご意見…当然、庁舎跡地等活用検討委員会の中でもご紹介させていただきまして、ご意見に応じて検討してまいりたいと考えています。","id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。よりよい跡地活用に集約していけるように、それぞれでしっかり取り組んでいきたいところだと考えておりますので、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"もしそうだとすると、それについては、どのように庁舎跡地等活用検討委員会で話し合われる予定なのでしょうかというところが１つ目になります。応募のあった民間事業者と対話をすると書かれているのですけれども、公募する前に、公募して応募がない場合はどのようにお考えなのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"例えば、この庁舎跡地等活用検討委員会の中でしながわ中央公園について、特に再編等々の議論をしていくような予定はございません。２８名の応募があったということで、倍率としては４倍の応募があったということで、非常に多くの方から応募をいただいたと認識しています。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"追加でご質問させてください。アドバイザリー契約の４社の中からＰｗＣアドバイザリー合同会社を選ばれた理由は、どういうところだったのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"当委員会は区民ニーズを広く把握して、官民連携手法の導入を視野に入れた対話型市場調査を基礎にしながら、様々な手法を想定していくというものです。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"要望になるのですけれども、７名の方が採用で４倍だったということで、様々なご意見を持っている方がいらっしゃるということだと考えています。要望のところで言うと、最終的に決めるのは１つになっていくと思うのですけれども、そのようなアプローチもご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"確認","question":"幾つか確認をさせていただければと思うのですけれども、確認のために聞きますが、庁舎跡地等活用検討委員会がこれからスタートするということです。今回、区議会議員を入れなかった理由について、もう一度、お答えをほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"庁舎跡地等活用検討委員会の委員として入っていただかなかった理由ですけれども、十分反映していけるだろうという考えの下、今回はこういった委員構成で臨もうと考えているところです。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"提案","question":"結論、対話型市場調査というのは、企業がこのようなものを作りたいという提案をしてくることが並行して進む形になっているのです。民間が出してきた、区民の意見が反映されていない提案を基に検討するという理解でいいのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"当委員会は全５回で進めてまいりますけれども、今回の庁舎跡地等活用検討委員会の中で、手法を絞り込んでいくようなところではございません。庁舎跡地等活用検討委員会の進め方ですけれども、また、しっかり区民の方のご意見を反映した基本的な考え方を設定していくものです。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"提案","question":"この５回、民間から提案を受けたものを、追認をしていくような庁舎跡地等活用検討委員会にはならないですかということ。特筆すべきところもたくさんあったのですけれども、私も少し理解しがたい部分があって、そこら辺の説明をもう少し詳しくお願いいたしますとの意見を述べました。","respondent":"泉広町事業調整担当課長","answer":"区民のニーズと民間事業者の様々いただくご意見がどういった整合性を持っていくのかといったところを整理していきたいと考えています。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"提案","question":"民間の提案があって、意見どうですかということではなくて、民間活用ですから。最後、ご答弁をいただきたいというところですとの意見を述べました。","respondent":"多並広町事業担当部長","answer":"庁舎跡地等活用検討委員会につきましては、まずは、区民の皆様から幅広くご意見をお聞きしたいということが第一です。１０ページでご説明させていただいた、もっとブラッシュアップしていって、絞り込んでいくような作業になってきます。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"質問","question":"もし説明の中にあって、第３回のところに区民アンケートの実施概要ということで、第４回で区民アンケートの実施結果という掲載があります。どのような内容を考えていらっしゃるのか、今、分かる範囲で教えてほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"区民アンケートにつきましては、まさに、庁舎跡地等活用検討委員会の中でもこれから議論されていくものです。今のところは、第３回の庁舎跡地等活用検討委員会の中で、区民アンケートを通してお聞きしていきたいと考えているところです。","id":"exchange-022"},{"speaker":"えのした委員","kind":"質問","question":"先ほど、委員長からも、新庁舎の整備で若い人たちの意見、声を聞いてほしいということがありました。そういった意見も聞くことができるのではないかなと私は考えますが、その辺についてもどのようにお考えか、お聞かせ願えますか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"１２ページで記載させていただきましたとおり、さらに小さな子どもたちのご意見も、どのような形かで意見聴取をしていきたいと考えているところです。違うやり方で小学生、中学生たちのご意見を聴取していくのかといったところは、今後検討してまいりたいと考えています。","id":"exchange-023"},{"speaker":"えのした委員","kind":"意見","question":"なかなか大人と交じって子どもたちも一緒にということが難しいのであれば、また別の機会でも構いませんので、親子参加型ということも検討いただけると、小さなお子さんの声も、親に対してなら話しやすい、説明も分かりやすい等、あると思いますので、ぜひご検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"松本委員","kind":"提案","question":"企業の方々は、これだけ検討範囲があるので、最終的にしながわ中央公園をどうするのかというところも想定した提案をなされると思うのです。その辺りはいかがか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査の実施要領に関連するご質問かと思います。１ページ目で対象範囲といたしまして、一部でもということで、そういった形の質問の仕方になっていくものと想定しています。","id":"exchange-025"},{"speaker":"松本委員","kind":"意見","question":"すごく安心しました。現庁舎跡地のほうは別の手法でなど、いろいろなアイデアがあるかと思いますので、その辺りは予断を挟まない形で進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"品川区立しながわ中央公園も今回の庁舎跡地の活用として、私の記憶が少し間違っているかもしれないのですけれども、急に出てきたような感があります。今回、この庁舎跡地等活用検討委員会でも、しながわ中央公園について、活用を検討していいということなのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"１ページ目の検討範囲、この計画の中では進めていきたいというところで、こういったものを含めてあります。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"この品川区立しながわ中央公園のエリアをいじれるかどうかというのは、新庁舎建設費の区民負担軽減というためには、非常に重要なことだと思うのです。その点は、民間事業者としても、そうした大規模に品川区立しながわ中央公園のエリアをいじっていいのかということをお聞きしたいのです。","respondent":"泉広町事業調整担当課長","answer":"検討範囲に含まれるしながわ中央公園の取扱いですけれども、何か制限、条件を設けるようなことは考えてございません。区民ニーズを叶えるために、こちらの再編等々につきまして、今回の庁舎跡地等活用検討委員会の中で広く議論するものではないと認識しています。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"では、民間事業者がしながわ中央公園のエリアを大幅に再編というか、いじってくるという可能性もあり得るということでよろしいのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査につきましては、先ほど申し上げたとおり、何か制限を設けるわけではございませんので、今、委員からご指摘いただいたようなご提案もあり得るです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"新庁舎の財源、区民負担軽減という目的もあるのですということをしっかりと民間事業者の方にも説明していかなくてはいけないと思うのです。その辺りの区民負担の軽減という目的の理解、そうした点は共有していくべきだと思うのですけれども、いかがか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"庁舎跡地等活用検討委員会の目的、しっかり民間事業者の方々と共有するような実施要領とさせていただきまして、対話型市場調査に臨みたいと考えています。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"ワークショップの実施結果、対話型市場調査の実施結果については、行財政改革特別委員会でも報告していただけるものなのでしょうか。第３回の庁舎跡地等活用検討委員会の前だと思うのですけれども、開催日時をお教えほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査のスケジュールですけれども、今のところ、９月中には公募の開始を考えてあります。１０月中には対話型市場調査を実施していきたいということで、１０月実施というところで、大きなスケジュールとしては考えてあります。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"対話型市場調査もやるといったプロセスを分かりやすく区民向けに整理して見せていくということが非常に大事なことかなと思っているのです。その辺りを区はどのようにお考えなのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"跡地活用までのプロセスの区民へのＰＲ、見せ方のお話かと存じます。１０ページに書いてあるとおり、今後、検討していきたいと考えています。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問・要望","question":"９ページのところで、これまでいただいた庁舎跡地等に関する意見というところで、導入機能について、かなりの要望、望まれる意見が載っているのです。温泉施設なども書いてありますが、どこら辺を着地点として考えられているのか、教えてほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"説明会の中、または庁舎跡地等活用検討委員会の公募区民の応募時にいただいたご意見の中から、その上の丸２つも庁舎跡地に関連する。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"確認","question":"そうですか。もう一回、確認ですけれども、複数を組み合わせてイメージできるようなものが到達点だということでよろしいのか尋ねました。","respondent":"多並広町事業担当部長","answer":"これからワークショップであったり、また、庁舎跡地等活用検討委員会の中でも、いろいろなご意見があるかと思います。絞り込むのではなくて、幅広くご意見をいただいて、それをまとめていく段階ということでご理解いただきたいと考えています。","id":"exchange-034"},{"speaker":"山本委員","kind":"質問","question":"区民アンケートについて、今回の庁舎跡地等活用検討委員会のプロセスの中でご用意されているのでしょうかということが１点。区議会議員からはこのような意見が示されていますという形で示されることで、庁舎跡地等活用検討委員会の検討の中で織り込まれていくのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"区ホームページ等も活用して、区民の皆様から広くご意見を聴取できるような仕組みを検討してまいりたいと考えています。この庁舎跡地等活用検討委員会も進めていきたいと考えていますので、取りまとめの段階では、しっかりこういったご意見が出て。","id":"exchange-035"},{"speaker":"山本委員","kind":"質問・要望","question":"２つ目の庁舎跡地等検討委員会へのフィードバックというところは、フィードバックいただくという理解でいいですか。確認したいと求めました。","respondent":"泉広町事業調整担当課長","answer":"こういった行財政改革特別委員会の場でいただいたご意見も、しっかりと庁舎跡地等活用検討委員会の中に落とし込んでいって、それをまとめの中でしっかり反映していきたいと考えていますので、しっかりフィードバックしていくという考えです。","id":"exchange-036"},{"speaker":"こんの委員長","kind":"提案","question":"行財政改革特別委員会で、今、跡地活用のご意見・ご提案等をいただいております。そこに、跡地活用の皆様のご意見・ご提案もまとめて提出することになるかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/642035?Template=document&Id=6154#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":30058,"voices":101}},{"id":"r05-20230823-19","meetingId":"r05-cm08","date":"2023年8月23日","dateIso":"2023-08-23","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時３４分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これをぜひほかの公共施設でも実施していくべきではないかと思うのですが、そこのところを区に伺いたいと思います。１回充電してしまうと、１回使用したときに、区のお考えを伺いたいと思います。","respondent":"河内環境課長","answer":"その搬送動力などの見合いによりまして、様々、それぞれの場所で使う方向性で検討を進めていると聞いてあります。夜の９時半まで開館しておりますので、そこは屋上にあります１２０ｋｗ級の蓄電池とは別に、活用について進めているという状況です。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそれを進めていっていただきたい、増やしていっていただきたいと思うのですけれども、伺いたいと思います。品川区では学校の断熱というのはどうされているのか、学校以外のほかの施設でもどうなっているのか、伺いたいと思います。","respondent":"河内環境課長","answer":"かなり丹念に対応してくれているというところがございまして、そちらのほうが、可能な限り転用という形で進んでいるという話は聞いているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"さらにこれを進めていくということで、区としてもさらに拡充をしていっていただきたいと思うのですが、いかがでしょうか。それが取り返しのつかないところに至らないように、抜本的に大きな転換が求められていると思いますので、いかがか尋ねました。","respondent":"河内環境課長","answer":"そういったものがあれば進めていく形で、今後も認識しながら、そういった事業も検討していければと考えています。そういった考えの下に、太陽光パネル、再生エネルギーを積極的に活用する方向で進めてまいりたいと考えているところです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"資料で伺いたいのですが、２つに集約されているのですが、そこの内訳を教えてほしいと求めました。区の取組としても、国にそうしたＣＯ２排出を増やすような取組というのは意見をしていくことが必要ではないかと思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"先ほど説明の中で、鋭意取り組むべきものだと示したところですが、どこが駄目だったのかというところについて触れておきたいと思います。区民、事業者と一丸となって取り組んでまいりたい姿勢ですので、ご理解いただきたいと考えています。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"削減量が減ってしまうということになってしまうわけですから、区としても、そこは国に意見を言っていくことが必要だと思います。すぐいっぱいになってしまうということで、もっとためられるようにしていけないのかなということで、ぜひ検討していってほしいと求めました。","respondent":"河内環境課長","answer":"そういったものも取り入れながら、脱炭素、ＣＯ２の削減に向けて取り組んでいきたいという姿勢で臨みたいと考えているところです。いろいろなご意見があろうかと思いますので、今後も検討しながら、きちんと整理して進めていきたいと考えているところです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に１点だけ、よりロードマップを具体化していくということかなと思いますので、そうしたところで進めていっていただきたいと意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"ひがし委員","kind":"質問","question":"子どもの方とかがたくさんいらっしゃって、そして取組としても、私はとてもすばらしいことだと感じております。今日提示していただいた（３）令和５年度の取組のところで、参加の状況、現状というのはどうなのかとお伺いしたいと思います。","respondent":"河内環境課長","answer":"具体的行動に結びつけていくというところが大切かなと考えておりまして、何かをつかんでいただきたいというところで行っている事業がほとんどです。しっかり学んでいただけるようなことを中心に据えましてやっていきたいという考えは、変わりなくやっていきたいと考えています。","id":"exchange-007"},{"speaker":"ひがし委員","kind":"質問","question":"イベントの内容を見ていましても、自分も行ってみたいと思うような内容もあったりとか、すごく興味深いものが多くありました。例えば１５名とか２０名とか決まっている中で、今回この配られた資料では、実際の参加率的なところはどうなっているのか尋ねました。","respondent":"河内環境課長","answer":"アウトリーチの講座を増やしたり、様々な工夫の中で、エコルの講座を受けていただける工夫を重ねていきたいと考えているところです。数が足りなくて、本当に区民の方には申し訳なく思っておりますが、そういった状況です。","id":"exchange-008"},{"speaker":"ひがし委員","kind":"意見","question":"ここもせっかくやっているのにどうかなというところで、また、すごく広報としてしっかり伝えられているところなのではないかと思います。皆様に知っていただきながら、これからの次世代につなげていけるような活動を、議員としても共にやっていきたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"館長からお声を聞いたのですけれども、たくさんの自治体が視察に来られているというお話も聞きました。エコルとごしが始まってから、どのぐらいの自治体の方が視察に来られているかというのがもし分かれば、教えてほしいと求めました。","respondent":"河内環境課長","answer":"だんだん後半になってまいりますと、どういった方がたくさん来られているのかとか、委員からご質問いただいたとおりの質問が多くなってまいりました。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"様々な自治体として参考に求められているというところがあると思われるのですけれども、今回４回目の公募が開始されている、今後その見通しがあるのか教えてほしいと求めました。","respondent":"河内環境課長","answer":"エコルとごしが地域連携を進めていけば、戸越地区の教育機関やいろいろな機関と連携を取りながら、やっていきたいと考えているところです。企画課などと調整の上、そういったことをやることも検討の視野に入れておりますので、よろしくお願いいたします。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"本年度６月にはゼロカーボンシティしながわ宣言もされて、一区民の声として、ご要望で上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"今このキッチンカーで使っていますというアピールが、あまりなかったような感じなのですけれども、どうなのでしょうか。アピールはそもそも求めているのか、アピールを求めているとしたら、その辺を伺いたいと思います。","respondent":"河内環境課長","answer":"ここに連携５事業などを書かせていただいておりますが、今まで環境活動を様々やられていた区民の方々にご参画いただきながら、力を合わせて。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"でも、あそこの中には今のところないなと、この間も確認したつもりだったのです。ぜひこの姿勢は続けていってほしいと求めましたので、それは要望としておきます。","respondent":"河内環境課長","answer":"中学生・高校生というのは大変難しい時期だと思うのですが、その中でも、こういったものを発信できるように工夫してみたいと考えているところです。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"指定管理者のお考えもあると思いますが、これからも要望を出していきたいと思いますので、どうぞよろしくお願いいたします。残念ながらお花はまだのようですが、来年に期待したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"こしば委員","kind":"確認","question":"まず確認の意味でもお聞きしたいのですけれども、まさにその上の、区民および事業者の自主的な環境活動の推進。育てていくというのは人材の育成に尽きるのかなと思うのですけれども、まず、そのとおりでよろしいかどうか。","respondent":"河内環境課長","answer":"様々、環境指針ありますが、やはり実践に結びつけていきませんと、例えばですが、脱炭素の目標しかり、いろいろな目標はありますが、結びつかないというところで、実践に結びつくようなところをキーにして進めているというところは間違いございません。","id":"exchange-016"},{"speaker":"こしば委員","kind":"質問・要望","question":"その取組の一つとして、環境学習講座だとか、アウトリーチの講座があると。先ほどひがし委員からも質問がありましたけれども、振り返りを教えていただきたいのと、また今後のことも教えてほしいと求めました。","respondent":"河内環境課長","answer":"無視できないほどの太いものになると確信しつつ、子どもたちと接しているところではありますが、講座の振り返りです。２０５０年、そういったきっかけになればといつも考えながら、今後も進めていきたいと思っているところです。","id":"exchange-017"},{"speaker":"こしば委員","kind":"質問・要望","question":"枝葉のことも含めて、しっかりと未来に向かって根を張っていけるように、この目標に向かって、本当にこれは大変長い時間がかかる取組だと思いますけれども、ぜひ取り組んでいただきたいと思いまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"新妻委員","kind":"確認","question":"昨年もエコルとごしに視察をさせていただきまして、１年がたちました。最初に確認でお聞きしたいのですが、どれくらいの目標の達成に向けて、どこかにされていましたか尋ねました。","respondent":"河内環境課長","answer":"そういったものに合わせて変更しているのですが、いろいろ指定管理者と検討しながら、今のようなお考えを形にできればと思っているところです。ご指摘ありがとうあります。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"余談ですが、３・１１の東日本大震災が起きたときに、電力不足が生じて、まちの中が暗くなりました。エコルとごしが開設をして１年で、まずは品川区の子どもたち、エコルとごしは全ての学校で見学できているのかというところを説明するよう求めました。","respondent":"河内環境課長","answer":"そういったところも含めて脱炭素の取組を進めて、あと１０年、しっかり取り組んでいければと感じたところです。１年間一生懸命やってきて、１年前に明確にイメージできていたのですかと言われると、しっかり進めたいと考えているところです。","id":"exchange-020"},{"speaker":"新妻委員","kind":"意見","question":"何年たっても足を運んでいただける、何か新しいことが、ここに来ると学べるという施設であってほしいとも思います。そういう方もお越しいただける場があったらいいとも思いますので、また今後、ご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"澤田委員","kind":"質問・要望","question":"既に様々取り組まれているということでしたので、申し訳ありませんが、子どもたちが、こんなことがあるのだというのを自分たちで考えつつも、さらに発見できるような、分かりやすい何かをつくっていただけたらと、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"そういうのも積極的に２０％ぐらいの補助金を出して、国と区も挙げて、私は取り組むべきではないかと考えています。そういう問題、弱点も出てくるのかなと思ったのですが、その辺についても説明を求めました。","respondent":"河内環境課長","answer":"脱炭素に向けてのＥＶの普及の在り方も、今後の検討課題の大きなものと捉えておりますので、しっかり進めていきたいと考えています。そういう条件のところばかりではありませんので、今後、こういったところの進展に向かって検討を進めてまいりたいと考えているところです。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"もう１点言っておかなければいけないのは、今度は、あまり電力ができ過ぎると遮断されてしまう。そういう問題もあるので、何とかこれから国・都・区で考えていただいて、私はよりいい方向に目指してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"せりざわ委員","kind":"質問","question":"環境のすごく手前の段階を教えてくれている一方で、品川区の制度とか、そこまでタッチできるといいなという思いも少しだけあります。手を差し伸べられると、今やっていることもたくさんあると思うのですが、今後の方向性を最後に説明を求めました。","respondent":"河内環境課長","answer":"そういったところで検討を進めてみたいと、今、感じたところです。何らかの形でやりたいというところが思いとしてはありますので、少しまたお時間をいただきながら、検討を進めていきたいと考えています。","id":"exchange-025"},{"speaker":"せりざわ委員","kind":"意見","question":"最後に意見だけ。２分の１補助していますとかというのは、５分の４補助していますとか、ぜひ都とか国の制度も含めて周知できると面白いなという意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"西村委員","kind":"質問","question":"１点だけ、すみません。開設から１年ちょっとたちまして、区内の全学校が訪問されているのかどうか、伺いたいと思います。","respondent":"河内環境課長","answer":"教育委員会と調整しながら進めて、全校に来ていただきたい思いは変わりございませんので、今後もそういう方向でしっかり進めてまいりたいと考えているところです。","id":"exchange-027"},{"speaker":"西村委員","kind":"質問","question":"なかなか品川区も広いものですから、行き方がなくて、大井地域から歩いて行くような学校もあったと伺っておりますので。子どもが大人になってからしか感じられませんので、そのことにチャレンジしていただいていることを、改めて感謝申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"二酸化炭素発生分析における対策例別の想定削減量の中の貨物車両なのですが、これは対象数が１万１,０００台です。この数字は、運輸局の数字から引用されているのかというのと、自家用、事業用、それぞれ両方で約１万１,０００台ということでよろしいか尋ねました。","respondent":"河内環境課長","answer":"おっしゃるとおりで、運輸局です。","id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"エコドライブ１０とかというのは、事業用はぱっとイメージするのですが、自家用の貨物というのはどのような感じの車両のことを言うのか尋ねました。","respondent":"河内環境課長","answer":"２０３０年度までに、観光バスも含めて１万台、電動化したいという表明がありました。まずは現実的な対応、こういったものをもって進めるものが大事ということで、こういった表現にしたというところが本音のところです。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"家庭については5)で、貨物車両のほうは自家用・事業用それぞれ、エコドライブしてくださいと。要するに、促して、それを推計でこのぐらいだろうという算定の下でいくのか、具体的に何かつかめるものがあるのかというのを説明するよう求めました。","respondent":"河内環境課長","answer":"そこの辺りは今後の検討課題なのですが、結果が浮かび上がるかどうかの検討をしている間にも、ここに踏み切っているです。そういった検討、現実感を見ながら進めてまいりたいのですが、怠りなく進めたいと考えているところです。","id":"exchange-031"},{"speaker":"つる委員","kind":"質問","question":"４,５９０万円の歳入があったと思うのですが、先月、森林環境譲与税の活用に係る都内連携に関する協定というのが結ばれました。２０１９年ぐらいか、１２区市町村がなったのが７月３１日という理解でいいのか、まずそこを説明するよう求めました。","respondent":"河内環境課長","answer":"こういったものを有効に使って、１ha当たり４トンぐらいのＣＯ２を吸収してくれるということも捉えまして、そういったところに参画を決意したです。１０年、２０年かけてしっかり取り組むというところに、品川区としても存在感を見せていきたいと考えているところです。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問","question":"で、橋梁のライトアップの関係で高知県とのカーボンオフセットの協定、提携があります。相殺する部分のこととか、ここについて具体的なことが既に検討に上がっているのであれば、教えてほしいと求めました。","respondent":"河内環境課長","answer":"お金でＣＯ２の削減を買うわけなのですが、基本的には日本国中で考えますと、全国的にも非常に注目されている大都市圏です。ＣＯ２の削減を金で解決するというやり方がありますと、そういったところを基本にしながら、頑張ってみたいと考えているところです。","id":"exchange-033"},{"speaker":"つる委員","kind":"質問・要望","question":"しっかりと今後も推進していただきたいし、区でどうこう言ってもなかなか難しいところがあるかもしれませんけれども、有効に活用できるような形で今後も推進してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"主な二酸化炭素発生分析における対策例別の想定削減量のところで伺いたいのですけれども、そこの確認をさせてほしいと求めました。それと、品川区も３万円の補助を出していますけれども、年間で太陽光パネルの実績というのが何件ぐらいあるのか、その点についても伺います。","respondent":"河内環境課長","answer":"今後の見込みなのですが、新型の太陽光電池パネルを自分のところの都有施設に設置してみるような、そういったものをいければと考えています。今の環境のマインドを大事にしながら、より多い削減に向けての取組が継続できますよう、努力を重ねていきたいと考えているところです。","id":"exchange-035"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"４０年と建て替えないわけですから、ぜひとも誘導していただきたいと思うのですけれども、その点についての考え方も伺いたいと思います。９７％削減できるということで示されたわけですから、そして計画を立てて、その点はいかがか尋ねました。","respondent":"河内環境課長","answer":"多くの件数が受け答えできるように、状況に応じながら、その辺りは進めていければというところが今の考え方です。ＺＥＢ化を経験した職員、あるいは一定の業者との蓄積ノウハウもありますので、必ずその検討を行っていると聞いております。","id":"exchange-036"},{"speaker":"鈴木副委員長","kind":"質問","question":"今回のロードマップの一番下の表というのは、１０年後の想定削減量ということで出されているわけです。それも１年ごとに、計画というのを立てていって、その点はいかがか尋ねました。","respondent":"河内環境課長","answer":"最善を尽くして検討していると聞いておりますが、ただ、なかなかそうはいかないかなと感じているところです。現状の流れの中では、そういったことを視野に入れながら、きちんと進められていると聞いているところです。","id":"exchange-037"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"断熱とか、そういうことも含めて、ＣＯ２削減に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-02","title":"令和５年度地区総合防災訓練の実施","agenda":"令和５年度地区総合防災訓練の実施","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"３地区が実施をしないということですけれども、理由がどういうことなのかお知らせください。やります１０地区におきまして、今回この訓練の中で、どのようにやっていくのかお知らせほしいと求めました。","respondent":"伊藤災害対策担当課長","answer":"その他の地区につきましては、１２月に予定をしております区内一斉防災訓練というのがございまして、今回の訓練は見送ると聞いております。訓練はまだ１１月の最後まですので、関係課と連携をしまして、誤りとか事故のないように対応させていただきたいと考えています。","id":"exchange-039"},{"speaker":"新妻委員","kind":"質問・要望","question":"障害のある方との訓練は、働きかけをしないとなかなか進まないと思いますので、ぜひ各地区に声かけを、区のほうからしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"今後の計画の中で、どうやって入り込んでいくのかという意気込みとかがあれば、教えていただきたい。大崎第１地区が今の私の推測どおりなのであれば、改築が終わった、人工芝化が終わったところに対しての対応について説明を求めました。","respondent":"平原防災課長","answer":"その際、私どもが防災の視点で、基本は避難所という単位で考えておりますけれども、必要なもの等々の申入れというか、協議を行っているところです。","id":"exchange-041"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"現実の災害時にはどうするかといったら、現実、そうだと思うのです。フルスペックで防災訓練ができるような体制というのを、ぜひ整えてほしいと、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/924121?Template=document&Id=6640#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":51112,"voices":97}},{"id":"r05-20230824-10","meetingId":"r05-cm08","date":"2023年8月24日","dateIso":"2023-08-24","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"令和６年度予算（議会費）","agenda":"令和６年度予算（議会費）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"幾つか、共産が出した要望について、何かそういったところで関わるようなことなどはないのでしょうか。５や１１あたりは、検討していただいたのかなということは、こちらについては伺いたいなと思います。","respondent":"渡辺議長","answer":"各論については、来年度予算に直結するものを中心に検討した結果ということで、個別にいい・悪いはそんなにこだわりはなく進めてまいりました。それが検討経緯です。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5514#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":6479,"voices":31}},{"id":"r05-20230920-10","meetingId":"r05-cm09","date":"2023年9月20日","dateIso":"2023-09-20","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"副区長なのですけれど、既におられる桑村副区長と、新井さんの担任事項はどのように分担するのか、ご説明ほしいと求めました。新井氏のほうは、特命に関することという事項も担任事項に入っておりましたけども、特命というのはどんなことを指すのか伺いたいと思います。","respondent":"森澤区長","answer":"それ以外を桑村副区長に引き続き担っていただくこととなります。特命に関しましては、政策推進を含めまして、区長が特命ということで任ずるものと考えております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"教育委員のほうですけれど、公募には何名の応募があったのでしょうか。それと、６月に総務委員会と教育委員会で報告があって、どういう基準を重視したのかというのをもう少しご説明ほしいと求めました。","respondent":"森澤区長","answer":"応募は３４名で、論文審査を経て、７名の方を面接させていただきました。それで、教育委員にふさわしい適性ということで、それぞれが面接において質問をさせていただきまして、審査をさせていただいたという次第になります。","id":"exchange-002"},{"speaker":"若林副委員長","kind":"確認","question":"ただいま区長より説明がありました２件の人事議案につきましては、後ほど議事日程の中で確認してまいりますが、２２日の本会議２日目に議決予定となります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"若林副委員長","kind":"確認","question":"ないようでしたら、本件につきましても、２２日の本会議２日目に議決予定となります。そのため、後ほど、議事日程の中で、本件に対する各会派の態度を確認します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"若林副委員長","kind":"確認","question":"９月２２日の追加議事日程第１の副区長の選任同意につきまして、各会派の態度を確認していきたいと思います。自民からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"若林副委員長","kind":"質問","question":"維新、無所属のうち、反対の方がいるですので、本件の取扱いについては、起立採決ということでよろしいでしょうか。〔「はい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"若林副委員長","kind":"確認","question":"続いて、追加議事日程第２の教育委員会委員の任命同意につきまして、各会派の態度を確認していきたいと思います。自民からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"若林副委員長","kind":"質問","question":"全会派および維新、無所属議員が賛成ですので、本件の取扱いについては、簡易採決ということでよろしいでしょうか。〔「はい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"若林副委員長","kind":"確認","question":"次に、議事日程(2)の日程第１５、議員派遣の件につきまして、各会派の態度を確認していきたいと思います。自民からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"若林副委員長","kind":"質問","question":"全会派および維新、無所属議員が賛成ですので、本件の取扱いについては簡易採決ということでよろしいでしょうか。〔「はい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"若林副委員長","kind":"質問","question":"正副委員長互選につきましても、先ほどの局長の説明のとおりですが、本件につきましても、ご異議ございませんでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"若林副委員長","kind":"質問","question":"さよう決定いたします。なお、予定表に記載のとおりですので、各会派での周知のほど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"若林副委員長","kind":"質問","question":"(1)の日程についてから(3)の質問者の氏名報告についてまでの３件を一括して、局長より説明願います。","respondent":"大澤区議会事務局長","answer":"(2)一般質問の順序については、予定表に記載のとおりです。(3)質問者の氏名報告ですが、１０月１０日午後５時までに事務局へお願いいたします。","id":"exchange-013"},{"speaker":"若林副委員長","kind":"質問","question":"ないようですので、第４回定例会の一般質問者の氏名につきましては、１０月１０日火曜日までに事務局へご報告願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"若林副委員長","kind":"質問","question":"ほかにいかがでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"若林副委員長","kind":"意見","question":"ないようですので、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"若林副委員長","kind":"意見","question":"次回の開催は、１０月２３日月曜日、午前１０時３０分からを予定しています。○午前１１時０２分閉会との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/881920?Template=document&Id=5516#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":11280,"voices":67}},{"id":"r05-20230922-4","meetingId":"r05-c-settlement","date":"2023年9月22日","dateIso":"2023-09-22","committee":"決算特別委員会","time":"午後 ３時２９分～午後 ３時３７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松永副委員長","kind":"意見","question":"ただいまご推挙いただきました副委員長を務めします、しながわ未来の松永よしひろです。重要な役割を担うに当たってしっかりと議会運営、そして委員長を支えて頑張ってまいりますので、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/242414?Template=document&Id=1530#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":2048,"voices":17}},{"id":"r05-20230925-6","meetingId":"r05-cm09","date":"2023年9月25日","dateIso":"2023-09-25","committee":"区民委員会","time":"午前１０時００分～午後 ０時２９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件整理しています。","topics":[{"id":"topic-01","title":"令和５年陳情第３１号、行政が運営主体となる新規火葬場建設を求める陳情","agenda":"令和５年陳情第３１号、行政が運営主体となる新規火葬場建設を求める陳情","exchanges":[{"speaker":"山本委員","kind":"質問","question":"私から何点か質問をさせてください。質問したいところは、陳情の理由の４のところで、もしくは事前相談というのはなされているのか尋ねました。","respondent":"舩木生活衛生課長","answer":"さらにしっかりとより行き渡るような説明も必要である部分、こういった部分にも、保健所の立場としても促してまいりたいと考えています。委員のご指摘も含めて重要な課題だとは認識しておりますので、少しそのあたりについて、確認をしてまいりたいと考えています。","id":"exchange-001"},{"speaker":"山本委員","kind":"質問・要望","question":"ここでお願いしたいのは、ぜひ連携を取っていただきたいというところと、ぜひ早く増設の計画が進むことをお願いしたいです。区民の皆様がすごく心配になることだと思いますので、これは一つ大事なこととして、ぜひそういった働きかけを進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"いわゆる組織区というのですか、運用上の見解については、今お伺いをしたところです。これはあれですか、６区において当然民間を置いているわけですから、もう１回確認したいと求めました。","respondent":"舩木生活衛生課長","answer":"埋葬等に関する法律の第９条では、第一義的には「死亡地の市町村長が、これを行わなければならない」という規定があります。もうこれは全国大半で、もうほぼ全ての自治体で、私が申し上げました経営主体の要件が条例に落とし込まれていると理解しております。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"確認","question":"私もお通夜とかご葬儀によく伺うのですけれども、やはり臨海斎場の利用率は民間斎場と比べてもかなり多いなという印象を受けています。こういった理解でいいのかどうか、もう１回確認したいと求めました。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、臨海斎場につきましては、半分の方がご利用になっているということです。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"２０２４年度から２０２５年度ですから、令和６年度から令和７年度に精査・見直しを検討すると書いてあるのですが、今年度から検討を開始するということでよろしいのか尋ねました。","respondent":"吉野戸籍住民課長","answer":"失礼いたしました。既に令和５年度から、いわゆる組合の中では一応お話は出ておりまして、実際に議会に出てくるのは、やはり令和６年とか令和７年になると思われます。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここについては本当にご要望に沿うのかなと思いつつ、これは２０３０年度に増築施設での事業開始ということで、あともう７年ですか。利用数の多い品川区民のご意見として、感覚として前倒しをすべきではないかと思いますので、これはぜひ私からも要望させてほしいと求めました。","respondent":"吉野戸籍住民課長","answer":"その辺も、先ほど答弁でも言いました、火葬炉の増設の数も含めて検討してまいりますという答弁がありました。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"確認","question":"生活衛生課長にお伺いしたいのですけれども、民間斎場を置いている６区の共通見解として、いわゆる落合斎場と四ツ木斎場を使ったのだと。確認ですが、落合斎場、四ツ木斎場に送られて火葬されたということでよろしいのか尋ねました。","respondent":"舩木生活衛生課長","answer":"本民間事業者が運営している６か所の火葬場では、新宿区と葛飾区のみで受け入れてきたという認識でおりますので、葬儀が行われてきたと認識しております。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"もう一つ品川区内には民間の火葬場があるわけですけれども、民間ですから、価格設定というのはそこが決められるわけですよね。幾ら以上は駄目ですよとか、そういう法律というか条例の担保というのは、まず民間の葬祭場に関してはあるのか、分かれば教えていただけますか。","respondent":"舩木生活衛生課長","answer":"民間企業が経営する事業所の火葬料金を、例えば１０万円以内にしなさいとか、そういう具体的な部分については規定がございません。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"うちも経営ですからと言われたら、火葬する親族の方にとっては、やはりどうしようと悩むと思うのです。その辺について、行きやすくしていただきたいとすごく思っていますので、その辺については、これからどういうふうに考えていくか。","respondent":"吉野戸籍住民課長","answer":"平日は１４便、そこから３分か５分ということで、大体葬儀をしますとマイクロバスで送迎ということで用意していただいている現状もあります。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"これは本当に大きな要望なのですけれども、設計等はきちんとしていると思うのですけれども、新規の火葬炉を設置しますよね。それを１つでも多く要望していただいて、その辺については臨海部広域斎場組合に要望してほしいということも含めて、いかがでしょう。","respondent":"吉野戸籍住民課長","answer":"先ほど答弁させていただいたとおり、平成２７年度の数字が基になっておりますので、現状に合った数値でもう一度計算するということを臨海部広域斎場組合は言っておりまして、そちらの見解を見た後、こちらの要望も伝えていきたいと考えています。","id":"exchange-010"},{"speaker":"えのした委員","kind":"意見","question":"やはり令和１２年度利用開始の、他区の状況ですとか、品川区は今後そういったことを検討されるのか。万一何か故障ですとか、そういったことが起こった場合のことも考えると、そういった協定というのも考えてほしいと求めました。","respondent":"吉野戸籍住民課長","answer":"どこ、どこという形での、件数を東京都が差配するような感じになります。","id":"exchange-011"},{"speaker":"えのした委員","kind":"質問・要望","question":"でも、課題としては、今ニーズがありますので、継続ということで。会派としても施設増設の時期を早めていただきたいと要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど確認させていただきましたが、この陳情と品川区の見解で若干異なる部分もありますけれども、おっしゃっている意味はよく分かります。この状況を早くしてほしいとさっき要望して、それを検討しているという臨海部広域斎場組合の様子を見守りたいと思いますので、継続とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"山本委員","kind":"意見","question":"ほかの委員からもお話がありましたけれども、今後の進捗を見守るということで、継続といたします。区民の皆様にも関わるとても大事なことですし、一刻も早い、そして、安価に使えるようにしていただけることを望みますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"せらく委員","kind":"質問・要望","question":"継続です。やはり場所だとか、今ある臨海斎場の炉を増やす、そういうところはスピード感を持ってやっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"横山委員","kind":"確認","question":"平成２７年度から少し現状が、大分変わってきているというところがあるので、そうした状況を確認する必要があると思います。なるべく正確な情報を様々な関係者の方にお伝えいただきながら、情報交換ですとか、区にも丁寧なやり取りを引き続きお願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"第６５号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第６５号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"先日、私たちの会派も他自治体の役所に、おくやみコーナーの視察に行かせていただきました。そういったところを丁寧にお考えいただいて、これ、申請手続きが必要な課がどのぐらいあるのだというところを教えていただけますか尋ねました。","respondent":"吉野戸籍住民課長","answer":"そういったところと連携しながら行いたいと考えています。特設開設みたいな形になっておりますけれども、周知のほうは気をつけていきたいと考えています。","id":"exchange-017"},{"speaker":"えのした委員","kind":"意見","question":"やはり８課にわたるということになると、おくやみコーナーをつくってよかったなという話になると思いますが、やはりその場所ですね。何かパーテーションを作るなり、見えないようにするなり、ご配慮ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれのところに行って、しかも普段やる手続きではないものですから、とてもいいことだと思っています。この手続きの流れのところで幾つか教えていただきたいのですけれども、８課ですかね、このような状況なのか尋ねました。","respondent":"吉野戸籍住民課長","answer":"電子申請書にチェックボックスみたいなものを用意する予定でおりまして、そこをチェックするような形にしたいと思っています。何が必要であるかというところも把握されておりますので、実際にお話を聞きながら、関係各課と連携を図りたいと考えております。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"すぐ来られないとすると、やはりそういった効率的にするというところで言うと、事前に確認できたりするのが好ましいなどというのもあると思います。で、私が申し上げたい趣旨としては、やはり効率的によりよく手続きが進むようにしていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは２００３年から我々もワンストップサービスのこういった手続きをずっと求めてまいりまして、ようやく、非常にうれしく思っています。一旦そこまでお伺いをしたいと思います。","respondent":"吉野戸籍住民課長","answer":"それから、予約ということで、午前２件、午後２件という形で対応していただこうと考えております。お隣の声が聞こえないように、やはりブースを少し離しまして、設けていきたいなと考えております。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"確認","question":"行政書士会に確認したら非常に歓迎しているということで、人員の配置等で今、そこで一定の信頼関係もできたのかなと考えています。そういう形でブースでご用意をされているのかどうか、そういうことを想定されているのかどうか、お伺いします。","respondent":"吉野戸籍住民課長","answer":"実は、書かない窓口というのを情報推進課といろいろと話をしている最中でして、始まった当初は無理かなと思うのですが、来年度に向けて、事前にもう入力しておいて、申請書も出るような感じに、バージョンアップをしていきたいなと考えております。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"確認","question":"手続きが例示されているものがありますけれども、これも一般質問のご答弁で、刷新をされていくというようなお話も伺いました。当然ネットでご覧になる方もいらっしゃると思いますので、このあたりについてどのようにお考えになっているのか、最後に確認したいと思います。","respondent":"吉野戸籍住民課長","answer":"一般質問でもありましたとおり、少し小さめのものになっておりますので、少し大きくして、他区のいいところを取り入れながら、刷新していきたいなと考えております。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問","question":"今のところどういうお考えなのかというところと、ごめんなさい、これも聞き忘れていました。これは委託契約をして、それとも代理として申請書類を書くのか、このあたりの法的な関係がもし分かれば説明を求めました。","respondent":"吉野戸籍住民課長","answer":"相続に関しましては、委員のおっしゃるとおり、それ以上のことはできないのですけれども、ただ、相談という形ではできるかなと考えています。行政書士はあくまでもその補助という形でおりますので、申請書はあくまでもご自身で書いていただくことになります。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"私も令和３年１１月の区民委員会で要望させていただいていて、ほかの議員もいろいろな場で要望されていて、物すごくうれしいなと思っています。相続という話も一般質問のご答弁でもありましたし、相続以外にどういったご相談をされているのかというのが分かりましたら、説明を求めました。","respondent":"吉野戸籍住民課長","answer":"それに倣いまして、まずそこから試行的に進めまして、増えた場合にはまた考えていきたいなと考えているところです。こういった手続きだけではなくて、いろいろな困り事があったり、そういったものについてもあったりするというのを聞いております。","id":"exchange-025"},{"speaker":"横山委員","kind":"質問・要望","question":"１月から３月までの様子を見つつ、来年度どうするかというところを考えて進めていかれるのかなということで、確認させていただきました。１つの申請があったときに、この部分は大丈夫ですかなどと声をかけていただいたり、スーパーバイザーみたいな形で担っていただく。","respondent":"吉野戸籍住民課長","answer":"ですので、情報推進部門とその辺を今詰めておりまして、書かない窓口であったり、もう少し手のかからないものを目指していきたいなと考えています。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらはまた一般質問でも話がありましたけれども、グリーフケアの部分、そういった専門性もぜひ大切にしていただきたいなと考えているところです。そういった様々な機会にもなるのかなと思っているのですけれども、そのあたり、現在どういうふうになっているのかを確認したいと求めました。","respondent":"吉野戸籍住民課長","answer":"遺族の方に寄り添うというところでは、委員のご指摘のとおりでして、どういったしつらえがいいのかというところを今ちょうど考えている最中でありますので、やはり寄り添ったサービスができるようなしつらえを、今後考えていきたいと考えています。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問","question":"ご相談先をご案内していただいたり、またこの冊子は、これからバージョンアップされていくというお話があったのです。次の質問にもなるのですけれども、そのあたりもどうされていくのかなというのが少し気になっていましたので、その２点を説明するよう求めました。","respondent":"吉野戸籍住民課長","answer":"こちらの冊子につきましては、できるまで少しお時間をいただきますので、やはり少し違った案内のものを作りたいなと考えているところです。ご案内につきましても、この冊子を渡すときに、こういったものを作りますというものをつけてと、考えております。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"要望なのですけれども、そのあたりもぜひ区と一緒に寄り添っていただく、そういったサービスにしていただけたらいいなと思います。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"予約等ができなかった方へのフォローといいますか、対応はどういうふうにしていくのでしょうか。その辺の、残り二千何百人の方に関してはどのように考えているのか、教えていただけますか。","respondent":"吉野戸籍住民課長","answer":"臨機応変に対応していただくというような形を取ろうかなと思ってはいるのですけれども、冊子をお渡ししてという、そういった対応になってしまうかなと考えている次第です。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"その辺についてはいかがですかということと、もう一つは、その冊子に関しても、実質、死亡届は、遺族の方が出すのはあまりないではないですか。葬儀屋ですかと伺うのもあれですけれども、また火葬する方にお渡ししておいて、その辺についてはいかがか尋ねました。","respondent":"吉野戸籍住民課長","answer":"どのように対応したら寄り添えるのかというところを含めて、もう一度、その辺につきましては検討させていただきたいと考えております。業者の方には事業案内チラシ等を事前に配ろうと考えていますので、そのような対応をさせていただきたいと考えております。","id":"exchange-031"},{"speaker":"山本委員","kind":"確認","question":"再度お聞きをすることなのですが、それで、その場でもう提出して進むというようなものなのでしょうか。で、各課の方がそれぞれ確認しなければいけないといって、そうすると待っている時間が結構長くて大変だみたいなことにもなるかなと思ったのです。","respondent":"吉野戸籍住民課長","answer":"こちらのおくやみコーナーですけれども、住基のシステムを見えるような形にしようと考えております。間違いないねというような、そういった確認の手順を今考えておりますので、全てそこで終わらせるようにといった手順を考えている次第です。","id":"exchange-032"},{"speaker":"山本委員","kind":"確認","question":"その場に各課の方が来なくても、デジタルで共有できることでリアルタイムに確認いただけて、手続きは進められるということで、それはとても効率的でいいのではないかと思いましたので、ぜひそのように進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"せらく委員","kind":"意見","question":"今回関わる各課は８課あることをお話しいただきましたが、今後、日曜日の窓口開設が可能かどうかというところをお聞かせほしいと求めました。","respondent":"吉野戸籍住民課長","answer":"おくやみコーナーに関しましては月曜日から金曜日で、日曜日の開設は今は考えていないところではあります。やはり今後のニーズ、そういった状況によって、検討課題になるかなと考えています。","id":"exchange-034"}]},{"id":"topic-03","title":"令和５年陳情第３５号、適格請求書等保存方式（インボイス制度）で新たな負担を受ける事業者に対して区独自の支援策を求める陳情","agenda":"令和５年陳情第３５号、適格請求書等保存方式（インボイス制度）で新たな負担を受ける事業者に対して区独自の支援策を求める陳情","exchanges":[{"speaker":"山本委員","kind":"質問","question":"区は現状、インボイスに特定した支援策というのはないようですが、インボイス制度導入に伴って、例えば資金繰りが悪化したりして経営に困る事態の方向けの制度ということで言うと、物価高騰等総合支援資金があるということですが、それは使えるという理解で合っていますか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"物価高騰等総合支援資金は、区がもっている融資あっ旋制度の１つのメニューですけれども、いわゆる設備資金、運転資金というところで、区の事業者の経営課題、あるいは経営困難を乗り越えるために必要だということであれば、こういった支援制度が使えるです。","id":"exchange-035"},{"speaker":"山本委員","kind":"質問・要望","question":"国の経過措置で８割、経済の混乱を起こさないという観点からも、前向きにご検討をいただきたいと考えていますというのが要望です。この要望に対してご見解がございましたら、いただけますと幸いです。","respondent":"小林商業・ものづくり課長","answer":"具体的には、これについては国の充実した補助制度がありますので、こういうもののご案内などもできるのではないかなと考えております。この部分については、国の税制措置の対応の考え方というところで、区として直接申し上げるのは難しいところです。","id":"exchange-036"},{"speaker":"山本委員","kind":"質問・要望","question":"今回始まるということでどうなっていくか分からないということ、ぜひそういったことも踏まえて、前向きにできることをご検討いただきたい。それから、工夫をして、支援につながるようなご検討をいただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"えのした委員","kind":"質問","question":"今、ご答弁がありましたように、国の税制に関わるものでもあります。区民の方に広く周知いただいて、国の助成や取組をご案内して、小規模事業者の方の負担軽減につながるようにご対応をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"専門性が必要なものについては、国等、また税理士等の窓口を紹介していくということで理解しております。品川区独自で区内事業者の支援を図ることのご要望ですけれども、国が必要だからやるよと言っているものですから、不採択ということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"山本委員","kind":"意見","question":"こういったものを考えたときには、やはり区としてもできる対策を講じていくことが、私は必要なのではないかと思います。先ほどの質疑でも申し上げましたとおり、区としての独自の支援策をしていくことがふさわしいと思いますので、この陳情は採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"維新としては、インボイス制度については公正な納税をするべきだと考えておりまして、区でできる支援は考えるべきだと考えています。事務負担というところが私は大きいものだなと考えておりまして、そういった部分で区で補助できる部分がないかと考えていただけたらと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"業界ごとにその構造やビジネスモデルは異なります。ご相談があった際には、業界ごとの違いや、お一人おひとりのご事情に寄り添ったご対応を引き続きお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-04","title":"「品川区再犯防止推進計画（素案）」およびパブリックコメントの実施","agenda":"「品川区再犯防止推進計画（素案）」およびパブリックコメントの実施","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"これからまたパブリックコメント等も１０月１日から始まりますが、寄り添った支援、計画を立ててほしいと求めました。私からは要望として以上ですが、何かご見解があればお願いします。","respondent":"宮澤地域活動課長","answer":"犯罪をした方の中には、貧困や疾病、障害など、様々な生きづらさを抱えている方がいらっしゃいます。住居、保健医療や福祉といった多岐にわたっている施策というのを、整合性をもって総合的に進めていくです。","id":"exchange-043"},{"speaker":"横山委員","kind":"確認","question":"第２章、保護司の適任者の方には、今後どういった方が必要とされるのかという区の考えを確認させていただけたらと思います。第１章、計画の基本的な考え方の４、具体的にどういったイメージなのかということを説明するよう求めました。","respondent":"宮澤地域活動課長","answer":"今年６月１日現在、いわゆる更生保護に日頃から取り組んでいただいている保護司の役割というのが、非常に重要だと認識しています。保護司会と連携しながら、活動の周知等も踏まえながら、連携して対応していきたいと考えているところです。","id":"exchange-044"},{"speaker":"横山委員","kind":"質問","question":"４をお聞きしたのですが、５の計画推進体制で、また少年センターに所属していらっしゃるボランティアの方々もいらっしゃるかと思うのです。そこは区の役割としてとても大事だなと思っているのですけれども、そのあたりを教えていただけたらと思います。","respondent":"宮澤地域活動課長","answer":"もとよりこれまでも、７月を社会を明るくする運動の強調月間ということで、運動に取り組んできているところです。７月が国での強調月間ですので、関係づくり、連携というのも深めていきたいと考えているところです。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"保護司の所管が地域活動課だから、今回、地域活動課長がこういったものの取りまとめをされていらっしゃるということなのでしょうか。地域のそういう活動を所管しているところが統括をやるというのが、自治体のこういう計画をつくるときの通常のやり方なのかどうか、説明を求めました。","respondent":"宮澤地域活動課長","answer":"所管の考え方というところからお答えします。保健センターでのサービス等を踏まえて、そういったものが医療に適切につながるようにというところで、計画の中に盛り込んでいるところです。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問・要望","question":"そうした深い事情等もご存じだと思うのですけれども、実際に立ち直りを目指す方というところのイメージのギャップみたいなところがあるかと思います。７月の社会を明るくする運動であったり、今後の対策につなげていっていただきたいと思うのですけれども、一言お願いいたします。","respondent":"宮澤地域活動課長","answer":"今回、計画に盛り込むことによって、様々な分野で再犯防止の視点が反映される契機となればと考えているところです。周知も含めて、行政として取り組んでいきたいと考えているところです。","id":"exchange-047"}]},{"id":"topic-05","title":"まちぐるみ文化イベント","agenda":"まちぐるみ文化イベント","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"このまちぐるみ文化イベントも同じ日に行われるということなのですが、この企画もあえて意図的にそういう形にされたのかどうか。このチラシに載っていますけれども、そのあたりを説明するよう求めました。","respondent":"篠田文化観光課長","answer":"こちらの「あつまれ！荏原地区で広く実施するですので、様々なイベントを実施していただけるということであったものですから、併せて連携を。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"意見","question":"連携を取って各所管で行うということで、何かそれで効果が見込める、集客効果が見込めるとか、何かＳＤＧｓに資するとか。先ほどの２つのイベントについてはそうなのですけれども、その目的というのは、連動してやる目的というのは何でしょうとの意見を述べました。","respondent":"篠田文化観光課長","answer":"この区役所の手前までが荏原地区ということになりますので、できるだけ広く地域を知っていただこうということもあって、この地域内にある各関係所管等と連携したです。","id":"exchange-049"},{"speaker":"えのした委員","kind":"意見","question":"荏原文化センター、あと西小山周辺のほうへ、そういったイベントが。もちろんこの１枚で分かるとは思うのですけれども、また新しい発見などにもつながるとは思うのですが、その辺は何か考えておられますかとの意見を述べました。","respondent":"篠田文化観光課長","answer":"商店街において謎解きのツアーを毎年やっておりまして、今回はこのタイミングに合わせて、２２日から開始をするという形でやっております。","id":"exchange-050"},{"speaker":"えのした委員","kind":"意見","question":"地域の方、そういった方にご協力いただいて、さらに盛り上がってほしいと求めました。お願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/753456?Template=document&Id=2968#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":44975,"voices":155}},{"id":"r05-20230925-7","meetingId":"r05-cm09","date":"2023年9月25日","dateIso":"2023-09-25","committee":"厚生委員会","time":"午前１０時００分～午後 ３時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を113件整理しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"よろしくお願いします。こちら１５年たちましたので、改めて公平に公募したところ、応募してきた１件がこちらという認識でよろしいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"こちらの指定管理者候補者のことにつきましては、現行も、こちらの大起エンゼルヘルプのほうが１５年間行ってきておりまして、今回公募した結果、選定をしまして、また、同じく株式会社大起エンゼルヘルプになったという次第です。","id":"exchange-001"},{"speaker":"ひがし委員","kind":"質問","question":"この１社になった理由、それとも前回と慣れていたこの１社が来てくれて、区のお考えとしてはどうなのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"指定管理者制度を民間の活力をより活用できるようにという中で改定されたと認識しておりますので、現行の１社の公募ということになっています。１社としても、選定委員会のほうは実施させていただきまして、選定に至ったと考えています。","id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問","question":"やはり何社からも来て、そうなると、課題としてはやはり１社からしか申請が来ないというところは問題なのかなと思います。これからそういった公募を募集するときの課題などについても教えていただけますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"施設によりましては何社も出てくることもありますので、恐らく幅広くいろいろな事業者がホームページ等見られていらっしゃるのかなと推測できます。","id":"exchange-003"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その内容も含めて検討していただいて、窓口を広く、ほかの人たちが手を挙げやすいような公募方法というものを考えてほしいと求めました。こちらは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"このように公募しますという通知をしたというようなことも伺いましたが、その点１点伺いたいということと、区としてどう考えられているのかも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"今第９期の介護保険事業計画のところで審議会等開いておりますが、先日も厚生労働省のほうから、決して魅力がない事業ではないと考えています。その辺りのところは、ほかの事業者が応募しなかった理由については、もう少し検証していきたいと思っているところです。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"提案","question":"それから経営、そのようなところが厳しいために、その点についてはいかがでしょうかということをお聞かせください。今回新たに公募という形で、これまでと違う新たな提案というものがあるのか、あったらその中身についてもお聞かせほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"介護人材の採用、そちらのほうをして職員の負担軽減というところも図っていて、いろいろと介護の人材の確保に努めていると認識しているところです。そうは言いましても、介護保険料、逆に安定した収入も得られるという部分もあるのかなと認識しているところです。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、もう１５年もやっているわけですから、そのようなところではどのような状況になっているのかも伺いたいと思います。１年、その西大井の利用率がどれぐらいなのかも分かったら教えていただきたいのですけれども、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"ケアホームの利用率８０.９％、令和２年度９５.５％というところから比べましても、令和４年度の利用率がかなり下がっていることが実情です。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"この大起エンゼルヘルプは株式会社ですけれども、同じところで、同じ系列で社会福祉法人をつくっているではないですか。なぜ東大井の多機能ホームは、株式会社というようなことで区としても選んでいくのか、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"介護度によって少し差はありますが、おおむね２０万円前後が、引き続きまたご利用様に負担されるものというところで認識しております。そこは会社の方針ということで、区におきましては、この施設についてはこの提案でというところでお受けをしている次第です。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問","question":"これまで還付されたことはあるのか、もしあるとしたらどれぐらい還付されているのかも伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"これについては、指定管理施設、形態によっていろいろと利用料収入というものが、差が出ると思います。平成２１年に開設以来、収入額が支出額を上回ったという事例がございませんので、このような還付の事例がないということが実情となっております。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"提案","question":"何を基準に決めるのかということと、５５０万円との額も、どのように算定されたのかについても伺いたいと思います。提案のあった経費を精査して区の予算の範囲内で認められた指定管理料を支払うと書いてあるのですけれども、これは、そのことも説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"基本的に小規模多機能の生活相談支援業務として約５００万円のお支払いと、建築設備の法定点検や防火設備の法定点検などの費用もお支払いしています。","id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問","question":"はですけれども、今回公募１社だけだったということなのですが、仮にこれ１社もなかった場合、結構最近１社の公募だけということはよく聞くのですけれども、公募がなかった場合というものはどうなるのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"公募がなかった場合は、応募していただく事業者が出るまで、また公募をするという次第になります。","id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問","question":"となると、例えば指定管理の期間が過ぎてしまったりなどということは、考えられなくもないかもしれません。そういった場合はどのように対応される予定か尋ねました。","respondent":"菅野高齢者福祉課長","answer":"そのような場合には、例えば現事業者のほうに延長してやっていただくなど、そういった対応もあるとは聞いております。ただ今回については、幸いにも現行事業者のほうが応募していただきましたので、このような事態には至らなかったという次第です。","id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"確認","question":"分かりました。改めて確認なのですけれども、そうではないのか、ひとつその辺お伺いしたいです。","respondent":"菅野高齢者福祉課長","answer":"介護人材、世の中全般的に不足しているというお話、国のほうでも審議会で取り上げられておりますので、そのように認識しております。平成３年度に介護人材の確保戦略という、そういった制度のほうも、ここの介護人材の確保については支援をしていきたいとは考えているところです。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問","question":"となると、今区として取り組んでいる、こういった対策で、ある程度十分であるとお考えか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"区として取り組んでいることで決して十分であるとは、常に事業者等のお声に耳を傾けながら、そういった支援について考えていきたいと思っているところです。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問","question":"松永委員長は、本会議一般質問で介護人材の不足についてお話しされたときに、区としてご見解で、介護人材の不足は認識していないというようなお話があったのですけれども、その点、ちょっと今のお話と併せてなのですが、改めて区の見解をお聞かせいただけますか。","respondent":"菅野高齢者福祉課長","answer":"人口が増えていく中、生産年齢人口も減っていきますので、なかなか厳しい状況に各事業者がなっていくだろうというところは認識しております。ここの部分については、確保支援のほうは考えていかなくてはいけないと思っているところです。","id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問","question":"その確保事業の１つに海外人材の確保が含まれているということか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"管理団体がどこでお願いするかとか、いろいろなルートとか、難しい部分もあります。そのときには、その事例の発表などもするなどして、ほかの法人に好事例として展開していくような支援をしています。","id":"exchange-016"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"私も介護職員として１３年働いていましたけれども。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"筒井委員","kind":"提案","question":"複数の事業者から提案を受けてみて、ぜひ積極的に品川区のほうからも働きかけを行っていただきたいと考えています。１社しか公募に応募をしなかったということが続いたら、品川区としてはどう今後ご対応というか、お考えになっているのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"令和３年度に指定管理者制度に係る基本方針というものを区としては改定させていただきまして、そこのところの改定によりまして。今回１社の申込みということで、あと２１施設指定管理施設がありますので、動向を注視していきたいと思っているところです。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"積極的に公平性を保つように、そして積極的に働きかけを行ってほしいと求めましたので、ぜひ注視のほうよろしくお願いします。３ページの（５）番の採点表と、５ページの（６）番で、その辺伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"対象事業者のプレゼンテーションとヒアリングを実施し、また、委員には有識者２名も入るということも考えますと。いずれにせよ、得点率７割以上というところでは、一定程度お認めいただいていると認識しております。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問","question":"このように捉えていますけれども、所見を伺いたいと思います。どうしたらば離職者を減らしていくことができるのか、いま一度その点、そのときの聞き取りの様子をもう少し詳しく教えていただけますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"１点目の、こちらも令和３年度に基本方針を改定した際に、状況が設定されてしまっているのかなという部分は拭えないところはあります。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"これまで１５年やってきた区との関係がある中で、その辺もどうか、そこを支援するといったところもどうか見ていただきたいなと思います。ですから、事業者の人材確保というところにもどうか視点を当てて、その点もどうか見ていただきたいなというところです。","respondent":"菅野高齢者福祉課長","answer":"この後の定着していただくというところも大きな課題として、各事業者、認識しているところだと思います。この事業者についても同じような認識でいると思いますので、いろいろと連携を取りながら、離職率が改善していくように努めていきたいと思っています。","id":"exchange-021"},{"speaker":"こんの委員","kind":"提案","question":"ぜひお願いしたいと思います。新たな提案ということも先ほど伺いましたので、先ほど申し上げた点も踏まえて進めていただきたい、このように考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"６ページのところに別添ということで、これは今回の大起エンゼルヘルプのところでも、これを評価したということなのでしょうか。点数がそれぞれ出ているということなのか、もしも出ているのだったらば、それぞれ何点で合計何点なのかということを教えていただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"６ページのところの入所サービス施設の選考基準評価項目の配点の部分についてです。よりよい、分かりやすい情報を提供するということも前提に、報告書の内容等については区全体として考えていきたいと思っています。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"でもそれを報告するには、何というのですか、区全体で決めないと、委員会としては報告できないというようなことなのですか。区として検討していただいて、そのような情報としてはもっともっと出していただけるようにお願いしたいと思うのですが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"基本方針の中で、選定予備委員会または選定委員会の審議内容を取りまとめたものを、報告書を用いて公表することとしております。採点表を公表する情報として定めていると、決め事としていますので、その基準にのっとって報告をさせていただいているという次第です。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"指定管理をしている品川区として、ぜひその辺をしっかりとチェックといいますか、していただきたいなと思います。何かしっかり入り込んで、いろいろと、大起エンゼルヘルプと一緒に何かできるような体制をつくっていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"おぎの委員","kind":"提案","question":"幅広い地域連携を視野に入れている提案があったということで、どういった提案がなされたのか、もしよろしければお聞かせください。２点目の、６ページの上のところで、この人件費増額がどういった経緯で３年目以降増額されていったのかといった点をお聞かせほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"人件費の増額が３年目以降に見込まれているです。収支計画のところで５年間分の事業の説明を受けているところでございまして、この５年間の収支計画、妥当なものということで把握しています。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"何というのですか、もしあるようでしたらつけられるようにしていただきたいと思うのですが、１点伺いたいと思います。何というのですか、区としても総合事業としてのミニデイなどというものをこのところに求めているのか、その辺について説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"１点目、あとは品川区全体の指定管理者公募に関する基本方針にのっとりまして、検討もしてまいりたいと考えています。あくまでも法人のほうで実施をしてくださるかというところに関わってはくるのですけれども、総合事業、地域ミニデイというところも要望はしています。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"提案","question":"事業メニューも豊富で期待感が持てる提案の内容ということで書かれているのですけれども、具体的にどのような中身なのかも伺いたいと思います。運営収支について、これは年間幾らくらいの委託料になっているのか、その点についても伺いたいと思いますとの意見を述べました。","respondent":"川原高齢者地域支援課長","answer":"令和６年度の予算編成等の議会の議決にも関わってきますので、おおよそ、ここでは大きくは変わらないというように見込んでいるところです。生きがいづくり支援事業、ぜひそこは実施をしていただきたいということで、高く評価をさせていただきました。","id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この年間の委託料なのですけれども、これはほとんど、何というのですか、人件費になるということになっていくのでしょうか。この多世代交流のところでは、この委託料がほぼ人件費になっていくのか、その点の考え方を教えてほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"収支の収入の部分につきましては、多世代交流支援施設については、主な収入というものは特に見込みはない形です。副施設長も配置をしていただく予定ですけれども、介護予防の事業も行えて、そのときの人件費が上乗せされているところということで見込んです。","id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問・要望","question":"３人、２人、委託職員１人というような。そのようなところでは、そういうものの保障というようなところでも、ぜひしていっていただきたいということでお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"こんの委員","kind":"確認","question":"ちょっと確認で、事業者Ｂというところでの（１）の運営体制について、１点確認させてください。そこをお願いします。","respondent":"川原高齢者地域支援課長","answer":"事業者Ｂにつきましては、委員ご指摘のとおり、既に区内で運営をしてくださっている法人の１つです。ただ、北品川、こういった多世代交流施設ではなく、別の高齢者福祉施設の運営をしているです。","id":"exchange-031"},{"speaker":"こんの委員","kind":"提案","question":"より提案がよかったというご説明だったのですけれども、先ほどの男性、そちらのほうの視点を入れた取組もされる提案のお話を伺いました。その中で１点、確認なのですけれども、いわゆる指定管理料のお話がありましたとの意見を述べました。","respondent":"川原高齢者地域支援課長","answer":"やはり人件費の考え方というところが、常駐のスタッフの方との協議をした上で、私のほうもしっかりと確認していきたいと考えています。経験値の高い人材をきちんと配置をしていただけるのかというところは、ぜひ念頭に置いて確認をさせていただきたいと考えています。","id":"exchange-032"},{"speaker":"こんの委員","kind":"提案","question":"そもそもの働く方というところの視点が外れてしまうと、いい提案は本当に区民のためのサービスになるのかということは少し気になったところです。ですから、この指定管理料がきちんと運営として使われていくような形もどこか確認をしていただいて、進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今後も引き続き、１社ではなくて、ほかのところの応募があったときには載せていただきたいなと考えています。併せて見ていっていただきたいと思うのですけれども、その点について、相談しながら変えられるものなのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"的確な配置がされているかというところをしっかりと、先ほどの選考の内容にのっとっているかというところはしていきたいと考えています。実際に法人の本部の方との協議を今後していただく形になりますので、奉優会さんのほうとお話させていただきたいと考えています。","id":"exchange-034"},{"speaker":"ひがし委員","kind":"質問・要望","question":"１０ページのところの上に書いてある、その管理をしている方々にも適正な賃金が払われるように、区としても見てほしいと求めましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"提案","question":"１０ページの、そのボランティア活用に関して提案があって、育成や活動を視野に入れた養成講座と、何か非常に面白いなと思うのですけれども、具体的に何か、どのような提案だったのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"活動支援、あと３点目は、ボランティアのコーディネートサイトというウェブサイトを持っております。そちらを活用してボランティアのマッチングも行いたいということで、提案をしていただいているところです。","id":"exchange-036"},{"speaker":"やなぎさわ委員","kind":"質問","question":"旧来から、奉優会はこういった活動はほかでもされていらっしゃるということでよろしいか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"そのとおりです。","id":"exchange-037"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"別の質問ですが、職員４名、フルタイムの非常勤なのか分からないですけれども。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"お話で、この奉優会、多世代交流支援施設のノウハウがあるというお話でしたけれども、今奉優会のホームページを見ているのですが、事業所、支所がいっぱい出ておるのですけれども、具体的にこの多世代交流支援施設、現在奉優会がやっている施設はどこなのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"は墨田区に高齢福祉センターゆうゆう館などの名称で実施をしていたり、本当に様々です。江東区や新宿区においても実施をしていただいているところです。","id":"exchange-039"}]},{"id":"topic-02","title":"第６５号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第６５号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"先ほど北品川のほうのシルバーセンターは、今回のこの案件に伴っての工期の変更はないというご説明をいただきましたが、確認です。グループホームの、こちらについての工期の変更を確認したいと求めました。","respondent":"川崎障害者施策推進課長","answer":"こちらのほうも工程表どおりに進捗しておりまして、工期のほうに延長はございません。","id":"exchange-040"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回賃金等の変更ということで、賃金以外でどういったものが該当するのか尋ねました。","respondent":"川崎障害者施策推進課長、川原高齢者地域支援課長","answer":"物価上昇に伴うインフレスライド条項ということで、今回障害者グループホームのところにつきましては、資材の高騰、それから労務費に対して適用されるものになります。高齢者地域支援課所管の北品川シルバーセンターの改築の工事における詳細も、物価の部分もやはりインフレスライド適用となっています。","id":"exchange-041"},{"speaker":"やなぎさわ委員","kind":"質問","question":"もともと１,２００億円と言われていたものが、最近のニュースだと２,０００億円を超えるなどといって、その点は大丈夫でしょうか。心配しているのでというところの懸念を申し上げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"公共工事標準請負契約約款第２５条、まだ今後、もっともっとインフレが進む可能性もあるかと思います。ある程度予算立てや、その準備をしていかないと駄目なのかなと考えているのですが、その点いかがお考えなのか尋ねました。","respondent":"東野福祉計画課長","answer":"インフレスライド条項につきましては、工期が長いものにつきましては、再度の適用というものは可能となります。本件、今回の２件につきましては、適用はないものと推測されます。","id":"exchange-043"}]},{"id":"topic-03","title":"第６６号議案、生活衛生関係営業等の事業活動の継続に資する環境の整備を図るための旅館業法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","agenda":"第６６号議案、生活衛生関係営業等の事業活動の継続に資する環境の整備を図るための旅館業法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"随分前にこれは国会の中に提案された法律なのですけれども、かなり提案した側としても慎重にこれを進めてきて、それで与野党７会派。","respondent":"舩木生活衛生課長","answer":"その辺も併せた形で、この法の改正の趣旨をしっかりと営業者の方が捉えていただけるような形で、周知を図っていきたいと考えております。現時点ではまだガイドラインも示されておりませんので、その部分も確認しながら進めていきたいと思います。","id":"exchange-044"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今度は何というのですか、この品川区で実際これが適用されるようなところというものはどれぐらいあるのか、分かったら教えてほしいと求めました。１年以内に、これ東京都になるのかどうか分からないのですが、その点を伺います。","respondent":"舩木生活衛生課長","answer":"１点目のご質問の割合ですけれども、いろいろ飲食店業なり、ほかの旅館業なり、様々ありますが、全体の許可件数、１割はいかない見込みです。それから、最低でも半年に１回は、その辺りは保健所の立場としてしっかりと対応していきたいと考えております。","id":"exchange-045"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。何というのですか、１５坪もないくらいの一戸建てが旅館業法でつくられるというような、その点を伺いたいと思います。","respondent":"舩木生活衛生課長","answer":"これ事務事業概要の前年度末の数字ですと１３６件、そのうちの５０件はリモートというか、そのようなことをしているという数になります。","id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問","question":"今の１３６件というものは、１年間で許可した件数ということなのでしょうか。そうすると、１年間で５０件がリモートで許可した件数ということであれば、その数字を教えていただけたらと思います。","respondent":"舩木生活衛生課長","answer":"トータルという件数は、すみません、ちょっと把握していないのですけれども、今申し上げた件数というものは、許可をし、そして廃止をしという現状の数ですので、今現在その数が現存しという、そのように捉えていただければと思います。","id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"国の法律なのであれなのですけれども、ぜひ規制もしていただきたいし、しっかりと見ていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"こんの委員","kind":"質問","question":"２つの一部改正ということで、主な改正の内容をお聞きしました。こうしたことが出てきているのか、この一部改正が出てきた背景、両方の背景をまずお聞かせ願いたいと思います。","respondent":"舩木生活衛生課長","answer":"国のほうで規制改革実施計画ということが閣議決定されておりますけれども、一致もあったというところであったかというように聞いております。そのようなところが大きく２点、法改正の背景にあったのではないかというように認識しております。","id":"exchange-049"},{"speaker":"こんの委員","kind":"質問・要望","question":"その点が理解が合っているかどうか確認をさせていただきたいということと、この金額から見てもかなり簡素化されるというようなところなのですか。その２点お願いします。","respondent":"舩木生活衛生課長","answer":"冒頭にご説明いたしましたように、１類・２類感染症であったり、そのとおりだというように認識しております。そしてこの金額が７,６００円、このような手続があった場合には、適正に手続を履行していくことが求められているのかなと考えております。","id":"exchange-050"},{"speaker":"こんの委員","kind":"質問・要望","question":"指導、改善というところまでは求められるのか。どの程度その事業者に指導、改善を求める、その権限が区としてはあるのか尋ねました。","respondent":"舩木生活衛生課長","answer":"１点訂正です。先ほど私、たしか７,６００円と申し上げましたが、正しくは７,４００円だということで、訂正します。","id":"exchange-051"},{"speaker":"こんの委員","kind":"意見","question":"案件によって、確かにそうだと思います。やはり懸念の声というものはあったりしますので、ぜひ、そうしたことが上がったときにはご対応をしていただくようお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]},{"id":"topic-04","title":"および(2)につきまして、関連する内容のため、一括して議題に供します。進め方といたしまして、一括して説明、質疑を行い、その後、その取扱い","agenda":"および(2)につきまして、関連する内容のため、一括して議題に供します。進め方といたしまして、一括して説明、質疑を行い、その後、その取扱い","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"ちょっと具体的なところで何点か伺いたいのですけれども、何人中何人くらい、何％なのかということをそれぞれ伺いたいと思います。取りあえずお願いします。","respondent":"池田国保医療年金課長","answer":"そのうち医科が３５１件、歯科が２０３件、薬局が２１６件です。３番目の質問ですけれども、１００％の登録がまだ国のほうでできていないということになっておりますので、多少は登録はされていないところです。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"意見","question":"患者も１つも悪くもない、医療にかかれない、アクセスできない。医療機関や区民から品川区に対しての相談や訴えなどが届いていたら、その件数と、どのような中身なのかもお聞かせいただけたらと思いますとの意見を述べました。","respondent":"池田国保医療年金課長","answer":"医療を受診する際のトラブルにつきましては、残念ながら私どものほうには、医療機関のほうからの申出はまだございません。それから患者からも、今のところは、こちらのほうにできなかったという直接のお声はいただいていないところです。","id":"exchange-054"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区内の医療現場の方からも伺っていますし、医師会の先生方とも様々やり取りする場面というのはあるわけですから、その点についていかがでしょうか。それというものは、２年間はこのまま使えるということで捉えていいのか、それから、国から何か示されているものがあるのか伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"来年の８月、次回保険証の発行について、今広域連合のほうで検討しています。通常ですと令和８年まで有効なのですけれども、令和７年の最大１２月までの有効期限ということに、後期高齢者医療制度のほうはなるです。","id":"exchange-055"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ちょっとその辺の確認をさせていただきたいということと、資格確認書と保険証というものは何がどう違うのか、ちょっとその点も伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"国のほうでは最大５年まで有効の資格確認書ということになってございまして、こちらのほうは社会保険のほうを考えているところであるかと思われます。","id":"exchange-056"},{"speaker":"ひがし委員","kind":"質問","question":"いろいろとトラブルが出てくるのではないかなと想定をしているのですが、区としてどのような問題が起こると考えられているのか、その場合の対応としてはどのように考えているか尋ねました。","respondent":"池田国保医療年金課長","answer":"国民健康保険の保険証に対してのお答えしかできないところですけれども、特に４０歳以上の方で特定健診を受けていらっしゃるかと思いますけれども、マイナ保険証というものは有効になるかとは考えているところです。","id":"exchange-057"},{"speaker":"ひがし委員","kind":"質問・要望","question":"特に高齢の方々が不安に思わないような対応というところを、国だけではなくて、区としてもやっていくべきだと考えています。ですから、今後何か問題があってからでは遅いと思いますので、その点についてはしっかりと強化をしていただきたいと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"もう１回自宅に戻って取りに帰ってくださいなどということが多発しているようで、また、家に２往復して保険証を取りに戻らなければいけない。登録作業等も混乱していると思いますが、今どれぐらいタイムラグが起きているのかということが分かれば、お聞かせ願いたいと思います。","respondent":"池田国保医療年金課長","answer":"いろいろな変更があったという点で、いわゆる実施のことが行ったところでございまして、特に調査の項目に入っておりません。で保険者については何日間できちんと入力するようにということで指示が出てありますので、それは安心していただければと思います。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"現場のほうにも、ヒアリング等で足を運んでいただいて、対応を見て一緒に解決していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お伺いします。歯科、薬局に設置されていると思うのですが、この費用負担というものはどういった形になっているのか尋ねました。","respondent":"池田国保医療年金課長","answer":"申し訳ございません。費用負担は把握してございません。","id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問","question":"例えば病院、歯科、薬局以外でも、保険証を使う医療機関はあると思うのですけれども、整骨院とか。そういったところに対して、今後このカードリーダーの普及などというものは、そういったことに関してはご存じか尋ねました。","respondent":"池田国保医療年金課長","answer":"今お話がありました、柔道整復でしたか、そういった医療機関につきましても、今度の秋以降にマイナ保険証での請求というようなことが、国のほうで少し話題になっているということで、実際に令和６年の秋には実施という形になってまいります。","id":"exchange-062"},{"speaker":"やなぎさわ委員","kind":"質問","question":"来年の秋ということですか。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"やなぎさわ委員","kind":"質問","question":"よろしいですか。例えば施設に入られていて、写真を撮ることが難しいなどという方に対して、どういった配慮を区のほうでされるという予定はありますか。","respondent":"池田国保医療年金課長","answer":"私どものほうではお答えできないところですけれども、暗証番号のないマイナンバーカードを発行する予定があるということ、こちらは保険の部分で使えるところでご説明をさせていただいたところです。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問","question":"マイナ保険証になったときは対応するすべがあるのか、介護の現場ではどのような対応ができるのか、ちょっと伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"どのような対応をしていくかというところは、戸籍住民課等と調整をしながら、考えていきたいと考えています。施設のほうとしては、その方針に基づいて、個人情報の取扱いなどといった部分もあると思いますので、検討していくことになるとは思います。","id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問","question":"それを、マイナ保険証を保険証と同じような形で施設側が預かってしまうということになっていくという、そのようなことで進められていくということなのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"区内の施設に限らず、こちらについては全国共通のことだと思いますので、その辺りのところ、国の見解なども確認しながら、今後進めていきたいと思います。","id":"exchange-066"},{"speaker":"鈴木委員","kind":"確認","question":"そうでなければ資格確認書だよという、そのようなことに持っていこうというものが、今回のマイナ保険証の問題だと思います。先ほども資格確認書というものが、１回目は、国民皆保険が保障されてきたわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"こんの委員","kind":"意見","question":"そもそもなぜ一体化をしようとしたのかと。マイナ保険証になったときにかかる医療とのメリット、そこの違いというか、そこをまずご説明くださいとの意見を述べました。","respondent":"池田国保医療年金課長","answer":"保健指導というものができてまいりますので、この先の医療費の削減にもなってまいりまして、やっていただければと思っているところです。悪意による使用もできなくなりますので、そういったところで、かなりよくなるのではないかと考えるところです。","id":"exchange-068"},{"speaker":"こんの委員","kind":"質問","question":"病歴というのでしょうか、次の医者にとっても、これまでの患者の受診する参考にもなるというものだと理解をしております。今、現状どういった状況であるか、分かる範囲でお答えできましたらば説明を求めました。","respondent":"池田国保医療年金課長","answer":"１,５７０万件の登録データを対象に総点検を実施したというところでございまして、１,５１５万件の作業を完了しているということになってあります。","id":"exchange-069"},{"speaker":"こんの委員","kind":"質問・要望","question":"公明党としても、国でそれは求めております。何か国のほうで、現時点で、総点検されている中で上がってきているものなどがありますか尋ねました。","respondent":"池田国保医療年金課長","answer":"お名前と、それから生年月日、それと性別の３つの部分で間違いが発覚したというものが多くあったということです。４点を確認することによって間違いはなくなるということで、必ず４点以上を、再発防止の対策の１つとして出ているところです。","id":"exchange-070"},{"speaker":"こんの委員","kind":"確認","question":"総点検の状況も確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"筒井委員","kind":"確認","question":"確認として、自治体向けの総点検の対象には、品川区はなっていないということでよろしいですか。その判断基準は、国の判断基準というものはどうしたものなのかということを教えてもらいたいと思います。","respondent":"池田国保医療年金課長","answer":"何点かの形で確認をした上でということで国のほうに回答させていただいたところ、関係部署のほうで、会議したところ聞いておるところです。関係部署で聞いたところ、このようなことを言われました。","id":"exchange-072"},{"speaker":"筒井委員","kind":"質問","question":"では、総点検の対象になっていないからといって、そのひもづけの誤りが今後起きないとまでは言い切れないということなのか尋ねました。","respondent":"池田国保医療年金課長","answer":"Ｊ－ＬＩＳとは４点検を確認するようにということでやっていますので、現在のところは品川区の住民情報におきましては間違いないかと思います。今後については、必ずしもとは言い切れません。","id":"exchange-073"},{"speaker":"筒井委員","kind":"確認","question":"マイナ保険証と資格確認書では、患者が窓口で負担する受診料というものは差がある。つまり、マイナ保険証のほうが少し安くて、資格確認書だと受診料は高くなるということで、それで間違いないか尋ねました。","respondent":"池田国保医療年金課長","answer":"資格確認書になったときにはどうかということについては、資格確認書自体、細かな部分は私ども区は把握してございませんで、分かりません。住民情報と連携しているのでまず間違いがないということで、国民健康保険ではない部分でのお話をさせていただいたところです。","id":"exchange-074"},{"speaker":"こしば副委員長","kind":"意見","question":"１０言いたいことがあっても７つ、８つぐらいしか言えなくて、把握しているけれども口に出すことはできないという方もいらっしゃいます。区民の皆様が幸せに暮らすことができる環境に資するものだと思いますので、この請願には沿い難い、不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問・要望","question":"マイナ保険証を持たない人に交付する資格確認書ですけれども、できるだけ簡素化をすること、こうしたことを国に求めております。ですから、こうしたことから、本請願については沿い難いと結論します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"ひがし委員","kind":"意見","question":"安全性の観点からも、まだ大きな課題があると認識しており、区民の方からも不安の声が上がっていることが現状であります。安全性が確保できたときには、この第１２号の請願に関しては、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ユーチューブで見られますので、ぜひご覧ほしいと求めました。マイナンバーカードと保険証のひもづけというものはやめるべきだし、保険証の廃止を中止して、存続をするべきだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"筒井委員","kind":"意見","question":"医療ＤＸ化の推進ということはやらなくてはいけないので、これまでの健康保険証の廃止を中止するということは取り難いので、今回の請願第１２号に対しては不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私はここのところをもう少し検討して、点検を行っていただいているとは思いますが、もう一度基本に立ち返ってほしいと求めました。私はこの請願は採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"メリットもお伺いしてはいるのですけれども、それを行使するかどうかは、個人的に思います。やはりトラブルがあまりにも多いということで、メリットよりデメリットのほうが上回っているのかなというように感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今回の第１３号、今の健康保険証の存続を求める意見書」の提出を求める請願につきましては、採択でお願いいたします。安全性をしっかりと確保して、国民の不安を払拭した上で進めていくべきと考えますので、この請願に対しては採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は健康保険証の廃止はやめるべきだと考えていますが、存続を求める意見書ということなので、このことに対しても賛成をしたいと思います。ここに書かれているそのとおり、トラブルだらけ、そのような状況になっておりますので、これを採択して、ぜひ意見書を上げていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"筒井委員","kind":"確認","question":"本日結論を出すでお願いします。資格確認書がどのようなものなのか、一定期間の延期は必要かなと考えるので、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"おぎの委員","kind":"質問","question":"理由は、先ほど第１２号の議案で述べたものと同じものになります。実際の患者が今一番不利益を被っている、こういった現状を国のほうへ伝えるためにも、こちらのほうも私は採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"意見","question":"採択でお願いします。私が第１２号で申し上げたとおり、まず何よりも保険証を存続するということが大切だと思いますので、これに関して採択するものでありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"}]},{"id":"topic-05","title":"令和５年陳情第３０号、福祉避難所となる心身障害者福祉会館の安全で快適な整備を求める陳情","agenda":"令和５年陳情第３０号、福祉避難所となる心身障害者福祉会館の安全で快適な整備を求める陳情","exchanges":[{"speaker":"ひがし委員","kind":"質問","question":"この心身障害者福祉会館の現状についてお伺いしたいのですけれども、現状の建物も定期点検というものをやっていると思うのですが。建物の検査は３年ごとで、建築設備に関しては１年以内ごとの点検を実施ということで、もしありましたら説明を求めました。","respondent":"松山障害者支援課長","answer":"委員おっしゃられるとおり、点検の状況ですが、建築課のほうで、建物に係る点検は３年に一度しております。","id":"exchange-087"},{"speaker":"ひがし委員","kind":"質問・要望","question":"問題点などがあれば教えていただきたいという点と、あともう１点、どこか情報載っているのか。それに対する対策も併せて見ていったほうがいいのかなと思うのですが、そのような公開というものはどうなっているのか説明を求めました。","respondent":"松山障害者支援課長","answer":"点検に関わる公表なのですが、特に公表されているものはございません。どちらかというと、それと指定管理者のところできめ細かく修繕をしていくというものになりますので、今のところ公表しているものは特にございません。","id":"exchange-088"},{"speaker":"ひがし委員","kind":"質問","question":"ごめんなさい。１点、４０年以上経過して古いというところでいうと、指摘として上がってきていないのか尋ねました。","respondent":"松山障害者支援課長","answer":"その都度対応しているものです。","id":"exchange-089"},{"speaker":"ひがし委員","kind":"質問","question":"２００２年６月からだとエレベーターの昇降路などを、そこが今どうなっているのかということが気になったので、先ほどの質問になりました。皆にも公表していただいて、内容の精査というところも一緒に進めていきたいなと思いますが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"特に何か、すごく細かいことまで公表するというよりは、現在もう改築に向けて検討しているというところが大きな今回のところです。実際に訓練につきましても、毎月１回、障害者の方、それから荏原消防署に来ていただいたりして、実際に現場で訓練を行っているところです。","id":"exchange-090"},{"speaker":"ひがし委員","kind":"意見","question":"その定期点検などのエレベーターの状況などというところも引き続き見ていただいて、何か問題がある場合は対策についても、建て替え以外でも検討していただいたほうがいいのかなと思いますとの意見を述べました。","respondent":"東野福祉計画課長","answer":"〔翌日「建築課で公表しているのは民間のみ。","id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問","question":"心身障害者福祉会館が改築に向けて検討しているということなのですけれども、具体的にいつ頃までに改築を目指すという、そのようなスケジュール的なところで、おおよその見通しがついているのか、ちょっと見通しがついているのであれば、その時期的なところも教えていただけたらと思います。","respondent":"松山障害者支援課長","answer":"代替施設の確保ができれば、スケジュールはおのずから決まってくるものと考えております。代替施設が決まりましたら、またこちらの委員会のほうにもご報告させていただきたいと考えています。","id":"exchange-092"},{"speaker":"鈴木委員","kind":"質問・要望","question":"代替施設とは考えられないのか、どのような形で代替施設を探していこうとしているのか、その点ちょっと伺いたいのですけれども。何というのですか、敷地と延べ床面積の平米数が分かったら教えていただきたいということと、もしも分かるようでしたら教えていただけたらと思います。","respondent":"松山障害者支援課長","answer":"延べ床面積が１,５９９.１７m2です。安全な継続したサービスを続けることというものが一番の目標ですので、また東京都と確認の上で探していくという、今実際に探しているという方向です。","id":"exchange-093"},{"speaker":"鈴木委員","kind":"質問","question":"何ですか、このような形で代替施設を確保しようとしているのですというようなところが見えるような形で教えていただけたらと思うのですけれども、どうか尋ねました。","respondent":"松山障害者支援課長","answer":"今は実際に検討していますのは、１つは機能分散の方法です。今現在４種類の形態で、嚥下、飲み込みが難しい方へ対応している状況です。","id":"exchange-094"},{"speaker":"鈴木委員","kind":"質問","question":"ちょっとまだ発表はできないけれども、候補地としてはこのようなことで、分散でこのように考えているのですということがあるということなのですか。今築４６年で、例えばこの５年間のうちにとか、ちょっとその点も伺いたいと思います。","respondent":"松山障害者支援課長","answer":"実際問題、本当に東京都の指定が取れなければ、安全なサービスが提供できないというのが大きなところになります。あるいは地域の、地元の町会の方、障害者団体の方々のご意見を伺いながら考えていきたいと考えています。","id":"exchange-095"},{"speaker":"鈴木委員","kind":"質問","question":"何というのですか、拠点の１つとしても充実をさせてほしいということは、ぜひ具体化をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"筒井委員","kind":"確認","question":"確認も含めてお聞きしたいのですけれども、今後バリアフリー法に適合したようなものの改築のご予定がある。代替地を見つけやすくするために機能を分散させて、代替地を見つけやすくして、今お探しになっているという状況ということでよろしいのか尋ねました。","respondent":"松山障害者支援課長","answer":"委員のおっしゃるとおりです。機能分散だけがもう決まっているわけではございませんので、１つの方法としてということで、東京都に相談に行っているところです。","id":"exchange-097"},{"speaker":"筒井委員","kind":"質問","question":"の代替地が見つけにくいという問題がどうしても生じてくると思うのですが、２つ３つ取得しておいて、区のお考えというものはどうなっていますか尋ねました。","respondent":"松山障害者支援課長","answer":"私どももそれぞれ、福祉部でそれぞれの施設を所管しておりますので、総合的に、やはり判断という、例えば施設のこれからの代替地の確保につきましては、企画の所管のほうで総合的にどうされるかということは考えるものと認識しております。","id":"exchange-098"},{"speaker":"こんの委員","kind":"質問・要望","question":"計画策定をと求めている内容ですけれども、同じ方からの質問で、改修という方向が明確にご答弁をされたということがよかったと思います。ここを確認したいと求めました。","respondent":"松山障害者支援課長","answer":"新たな会館として、福祉の避難所として整備するというところで、様々な方に配慮しながら進めていくです。今具体的に東京都に相談しているというところで、もう今、既に区は前向きに動いております。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこを次どのようにするかという、これをどう活用していくかというところは、その辺のところの取組についても確認させてほしいと求めました。こうしたことに一定の安心感、こうしたこともあるのかなと思いますが、その点も説明を求めました。","respondent":"松山障害者支援課長","answer":"それぞれ区の中で今活用検討しているような、総合的に、やはりこれは検討が必要だと考えております。もう１点は計画なのですが、今公共施設等の総合実施計画というものもありますので、きちんとさせていただければということを考えております。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほど町会の方々や地域の方々、あるいは団体の方々のご意見を伺いながらということですけれども、ぜひお願いしたいと思います。具体的にこのように進めていますということを発信していただくことが、不安払拭につながるのかなと考えますけれども、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"改築に向けて具体的な動きを進めていること、代替地を必ず確保して安定的に継続的なサービスを実施していくことというものは明文化した上で。不安を払拭するために、安心して通所していただくために、一律の情報をきちんと利用者向けに丁寧に発信していきたいと考えています。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"団体の方々、町会の方々とやり取りをして、丁寧に進めてほしいと求めました。いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"実行委員会をつくって、皆さんのご意見を集約した形で、やはり毎年のようにお祭りを実施しているわけです。皆さんが安定して施設をご利用して、福祉避難所としても強化していくということも明確に打ち出してまいります。","id":"exchange-102"},{"speaker":"やなぎさわ委員","kind":"確認","question":"改築や建て替え、そういったものを含めて、なかなか計画策定ができないということは、今日改めて確認なのですけれども、やはりある程度まとまった用地の取得ができないからといいますか、めどがすぐには立たないからということでよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"まとまった用地の取得ができないからめどが立たないというよりは、今機能分散の方向も考えていますし、幾つか候補地はあるかと思います。ただ、適切に会館の方が安心してサービスを継続できるところを、今現実的に検討しています。","id":"exchange-103"},{"speaker":"やなぎさわ委員","kind":"質問","question":"この福祉会館が、あそこで１,５００m2あるということで、例えば同じサイズぐらいの用地があれば、分散という話もありましたけれども、そちらに新しくつくって、同じような施設をつくって、そこでサービスを継続するということは可能か尋ねました。","respondent":"松山障害者支援課長","answer":"どのように代替になった場合に通っていただくかということも、様々な障害の方がいらっしゃるので、きめ細かく考えなければならないです。","id":"exchange-104"},{"speaker":"やなぎさわ委員","kind":"確認","question":"分かりました。１つ確認なのですけれども、先ほどから東京都と相談というお話なのですが、こういった施設の指定権者が東京都だからという認識でよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"委員のおっしゃられるとおりです。東京都が指定権限を持っております。","id":"exchange-105"},{"speaker":"やなぎさわ委員","kind":"質問","question":"例えば、これ東京都の指定を受けずに、区で独自に何か取組を持って施設をつくるということは可能なのか尋ねました。","respondent":"松山障害者支援課長","answer":"例えば委託という方式が考えられますけれども、施設の基準等を区などでつくっておりませんということが１つ、全て全部区の単費になります。安定して継続するサービスということを考えたときに、やはり年単位、東京都の指定を受けるというものが着実な方法であると考えております。","id":"exchange-106"},{"speaker":"こしば副委員長","kind":"質問","question":"３月の予算委員会、先般の高橋伸明議員の一般質問での回答を踏まえ、具体的な対策のほうもお話を伺いました。そういったところで、この陳情に書かれている願意には沿い難いと考え、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"こんの委員","kind":"質問・要望","question":"思いとして改築を早急に、これは私も同じ願いです。どうかこの辺を利用者、そして改築に向けていただきたい、今請願については沿い難いと結論します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"ひがし委員","kind":"質問","question":"先日の一般質問で、建て替えを含めた計画を検討するとご答弁されておりました。都や各所管と連携をして、代替地取得の方法も含めた具体的なロードマップを示した計画の策定を要請いたしますので、この陳情については採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当にもう築４６年で改築が必要ということで、いつまでにどのような形でやるかということを具体化してほしいと求めました。その検討をぜひとも早急に進めていただきたいという思いを込めて、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"筒井委員","kind":"質問","question":"この点、陳情者の願意に沿うのかなとは考えております。先ほどからご答弁にもあったとおり、なかなか現実的には厳しい点があるのかなと思いまして、この点をもって不採択ということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"おぎの委員","kind":"意見","question":"４７年、４８年とどんどん老朽化していってしまいますので、都と連携して積極的にやっていったほうがいいと感じました。採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出します。ぜひ、この陳情を採択をもって計画を進めていけるような体制になっていければいいなと思いますので、採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/651938?Template=document&Id=3670#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":80667,"voices":318}}]);
